(window.GIM_TS=window.GIM_TS||{})["Ketubot.2"]={"from":48,"a":[["\u0003במסיח לפי תומו.\u0004 שלא העיד האח ממש אלא שמתוך דבריו, שהיה מסיח לפי תומו, מובן היה שזה אחיו ושהוא לוי. \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003אמר רב יהודה אמר שמואל: מעשה באדם אחד שהיה מסיח לפי תומו, ואמר: זכורני כש\u0004הייתי \u0003אני תינוק ו\u0004הייתי עוד \u0003מורכב על כתיפו של אבא, והוציאוני מבית הספר, והפשיטוני את כותנתי, והטבילוני\u0004 כדי להיטהר מחשש טומאה כדי שאוכל \u0003לאכול בתרומה לערב.\u0004","\u0003ור' חייא\u0004 שהיה מספר סיפור זה \u0003מסיים בה\u0004 בספרו שאותו אדם המשיך וסיפר: \u0003וחבירי\u0004 היו \u0003בדילין\u0004 (פורשים) \u0003ממני, והיו קורין אותי\u0004 בכינוי \u0003\"יוחנן אוכל חלות\".\u0004 שהחלה המופרשת מן העיסה דינה לכל דבר כתרומה, ואסורה לזרים ונאכלת רק לכהנים טהורים. והיו חביריו מכנים אותו כך על שאוכל דבר שאין הם רשאים לאוכלו. ומתוך הדברים הללו מובן שכהן הוא \u0003והעלהו רבי לכהונה על פיו.\u0004 וכשם שאפשר היה לסמוך על עדות עצמו, כך אפשר היה לסמוך על עדות האח בכגון זה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: כשם ש\u0004אכילת \u0003תרומה\u0004 הריהי \u0003חזקה לכהונה — כך\u0004 לקיחת \u0003מעשר ראשון\u0004 הריהי \u0003חזקה לכהונה, והחולק בבית־דין אינה חזקה.\u0004","ותוהים: \u0003מעשר ראשון\u0004 הלא של ה\u0003לוי הוא!\u0004 ומדוע תהא נטילתו חזקה לכהונה? ומשיבים: הוא סבור \u0003כ\u0004שיטת \u0003ר' אלעזר בן עזריה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003תרומה\u0004 ניתנת \u0003לכהן, מעשר ראשון ללוי,\u0004 אלו \u0003דברי ר' עקיבא. ר' אלעזר בן עזריה אומר: מעשר ראשון\u0004 ניתן \u0003אף לכהן.\u0004 ושואלים: אפילו כך, \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' אלעזר בן עזריה \"אף לכהן\",\u0004 אך שניתנת דווקא \u0003לכהן ולא ללוי מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004 ואף לשיטתו אם כן אין קבלת מעשר ראשון חזקה לכהונה.","ומשיבים: \u0003אין, בתר דקנסינהו\u0004 \u0005[כן, לאחר שקנס אותם]\u0006 \u0003עזרא\u0004 את הלויים מפני שלא רצו לעלות לארץ ישראל וגזר שלא יתנו להם מעשר ראשון, ומאז מעשר ראשון ניתן רק לכהנים, בעוד שמדין תורה אפשר היה לתת אותו גם ללויים וגם לכהנים. וממילא, נטילת מעשר ראשון מוכיחה על כהונה. ושואלים: כיון שכך הדבר \u0003ודלמא\u0004 \u0005[ושמא]\u0006 אותו אדם לוי הוא באמת, ובאותו מקרה \u0003איקרו ויהבו ליה\u0004 \u0005[הזדמנו ונתנו לו]\u0006 מעשר ראשון! \u0003אמר רב חסדא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — במקרה מיוחד, \u0003כגון\u0004 ש\u0003מוחזק לן\u0004 \u0005[לנו]\u0006 \u0003באבוה דהאי\u0004 \u0005[באביו של\u0006 איש \u0005זה]\u0006 ש\u0003כהן הוא, ונפק עליה קלא\u0004 \u0005[ויצא עליו,\u0006 על הבן, \u0005קול]\u0006 ש\u0003בן גרושה\u0004 או \u0003בן חלוצה הוא\u0004 וחלל הוא והוא נחשב לכל דבר כישראל, \u0003ו\u0004ראינו כי \u0003חלקו ליה לדידיה\u0004 \u0005[לו עצמו,\u0006 לבן\u0005]\u0006 \u0003מעשר בבית הגרנות.\u0004","ואם כן לענין החשש שמא \u0003לוי\u0004 הוא, הרי יודעים אנו \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003לוי הוא,\u0004 שהרי ידוע מי הוא אביו, ועל מקרה כזה \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 מה יש רק לחשוש בו — שמא \u0003בן גרושה או בן חלוצה הוא.\u0004 ואז, \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003מעשר ראשון אסור לזרים,\u0004 שודאי \u0003לא הוו יהבי ליה\u0004 \u0005[היו נותנים לו]\u0006 שכיון שהוא בן גרושה, דינו כזר. \u0003אלא אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003מעשר ראשון מותר\u0004 לאכילה \u0003לזרים,\u0004 ולכאורה אין בכך הוכחה שכהן הוא, הרי \u0003הני מילי למיספק להו\u0004 \u0005[דברים אלו\u0006 אמורים דווקא לענין \u0005לתת להם לאכול],\u0006 \u0003אבל בתורת חלוקה\u0004 בבית הגרנות \u0003לא יהבי ליה\u0004 \u0005[אין נותנים לו\u0006 לזר\u0005].\u0006 ולכן חלוקת מעשר ראשון בבית הגרנות, לדעת ר' אלעזר בן עזריה, היא עצמה מהווה הוכחה לכך שאותו אדם הוא כהן כשר.","באותה ברייתא שנינו: \u0003והחולק בבית־דין אינה חזקה.\u0004 ותוהים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003בבית־דין לא הויא\u0004 \u0005[אינה]\u0006 \u0003חזקה, היכא הויא\u0004 \u0005[היכן היא]\u0006 \u0003חזקה?!\u0004 הלא בית דין הוא המקום שבו מבררים את הדברים על בוריים! \u0003אמר רב ששת: הכי קאמר\u0004 \u0005[כך אמר,\u0006 זו הכוונה\u0005]:\u0006 \u0003החולק תרומה בנכסי אביו עם אחיו בבית־דין — אינה חזקה\u0004 שהוא עצמו כהן. משום שייתכן שלענין ירושה יש לו זכות בתרומה כמו בשאר הדברים, משום שהוא יורש חלק מרכוש אביו, ובכלל זה תרומה, אבל הוא עצמו ייתכן שזר הוא, כגון שהוא חלל.","ותוהים: אם כך, \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שאין זו הוכחה! ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מדהנך\u0004 \u0005[מ\u0006כיון \u0005שאלה,\u0006 שאר האחים\u0005],\u0006 מקבלים את התרומה \u0003לאכילה — האי נמי\u0004 \u0005[זה,\u0006 החלל, \u0005גם כן]\u0006 מקבל אותה \u0003לאכילה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין זו הוכחה. שאפשר לומר \u0003הנך\u0004 \u0005[\u0006ש\u0005הם]\u0006 מקבלים אותה \u0003לאכילה, האי לזבוני\u0004 \u0005[\u0006ו\u0005זה\u0006 מקבל אותה כדי \u0005למכור],\u0006 שאף שהוא עצמו אינו רשאי לאכול את התרומה, יכול הוא למוכרה לכהנים.","שנינו במשנה ש\u0003ר' יהודה אומר: אין מעלין לכהונה על פי עד אחד.\u0004 ור' אליעזר אומר שאין מעלים לכהונה על פי עד אחד רק כשיש עוררין, ורבן שמעון בן גמליאל אומר שמעלים לכהונה על פי עד אחד. ושואלים: שיטת \u0003רבן שמעון בן גמליאל היינו\u0004 \u0005[הרי זו]\u0006 שיטת \u0003ר' אליעזר,\u0004 ומה ההבדל ביניהם? הרי שניהם מסכימים שמעלים לכהונה על פי עד אחד כשאין עוררין?! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי במקרה של \u0003ערער חד\u0004 \u0005[\u0006ש\u0005המערער\u0006 הוא \u0005אחד]\u0006 \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 ש\u0003ר' אליעזר סבר\u0004 ש\u0003ערער\u0004 אפילו הוא של \u0003חד\u0004 \u0005[אחד],\u0006 שאף אם בא עד אחד ואומר שפלוני אינו כהן — יצא מחזקתו, וצריך שני עדים להעיד עליו. \u0003ו\u0004אילו \u0003רבן שמעון בן גמליאל סבר: ערער\u0004 \u0005[ערעור]\u0006 הוא רק \u0003תרי\u0004 \u0005[שנים],\u0006 וכל עוד לא ערערו שנים על יחוסו, מעלים אותו לכהונה —אינך יכול לומר כן, שכן \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003ר' יוחנן: דברי הכל אין ערער\u0004 \u0005[ערעור]\u0006 על חזקה של אדם ב\u0003פחות משנים\u0004 ואין מחלוקת בדבר זה!","\u0003אלא,\u0004 כך צריך לפרש: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — ש\u0003מוחזק לן\u0004 \u0005[לנו]\u0006 \u0003באבוה דהאי\u0004 \u0005[באביו של\u0006 אדם מסופק \u0005זה]\u0006 ש\u0003כהן הוא, ונפק עליה קלא\u0004 \u0005[ויצא עליו,\u0006 על הבן, \u0005קול]\u0006 ש\u0003בן גרושה או בן חלוצה הוא, ואחתיניה\u0004 \u0005[והורדנו אותו]\u0006 מחזקת כהונה בגלל הקול הזה. \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003עד אחד ואמר: \"ידענא ביה\u0004 \u0005[יודע אני בו]\u0006 ש\u0003כהן\u0004 כשר \u0003הוא\"\u0004"],["\u0003ואסקיניה\u0004 \u0005[והעלינו אותו]\u0006 שוב לכהונה, כי עד אחד מועיל לבטל את הקול. \u0003ואתו בי תרי ואמרי\u0004 \u0005[ובאו שני\u0006 עדים \u0005ואמרו]:\u0006 \u0003בן גרושה\u0004 או \u0003בן חלוצה הוא, ואחתיניה\u0004 \u0005[ו\u0006שוב \u0005הורדנו אותו]\u0006 מכהונתו, שהרי שני עדים ביטלו את עדות העד האחד. \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003עד אחד\u0004 אחר כך \u0003ואמר: ידענא ביה\u0004 \u0005[יודע אני בו]\u0006 ש\u0003כהן הוא, ו\u0004אנו מניחים עוד \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 שני עדים אלה שהעידו להכשירו \u0003מצטרפין לעדות\u0004 אף שלא העידו בבת אחת. ואם כן יש עליו עדות שהוא כהן כשר, וצריך היה להחזיר אותו לחזקת כהונתו.","\u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004בעיה של \u0003מיחש לזילותא דבי דינא קמיפלגי\u0004 \u0005[חשש לזלזול\u0006 כבוד \u0005בית הדין חלוקים\u0006 הם\u0005];\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר\u0004 כי \u0003כיון דאחתיניה\u0004 \u0005[שהורדנו אותו],\u0006 שוב \u0003לא מסקינן ליה\u0004 \u0005[מעלים אותו],\u0006 כי \u0003חיישינן לזילותא דבי דינא\u0004 \u0005[חוששים אנו לזלזול\u0006 כבוד \u0005בית הדין],\u0006 שאם מעלים ומורידים אותו ושוב חוזרים ומעלים אותו נראה הדבר כמעשה משחק, וכאילו אין בית הדין יודעים מה הם עושים. \u0003ורבן שמעון בן גמליאל סבר: אנן אחתינן ליה ואנן מסקינן ליה\u0004 \u0005[אנו הורדנו אותו ואנו מעלים אותו],\u0006 \u0003ולזילותא דבי דינא לא חיישינן\u0004 \u0005[ולזלזול\u0006 כבוד \u0005בית הדין אין אנו חוששים],\u0006 אלא עושים את הכל על פי הראיות.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על הסבר זה\u0005]\u0006 \u0003רב אשי: אי הכי\u0004 \u0005[אם כך]\u0006 שזה טעם המחלוקת, מדוע צריך להעמיד את הכל בעד אחד? \u0003אפילו תרי ותרי נמי\u0004 \u0005[שניים ושניים גם כן],\u0006 אם יבואו שני עדים ויורידוהו על פיהם, ויבואו שניים אחרים ויעידו שיש להעלותו, גם אז יהיה קיים אותו חשש עצמו!","\u0003אלא אמר רב אשי: במצטרפין לעדות קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 כלומר, המחלוקת היא בנושא שאותו הנחנו קודם כמוסכם, בשאלה האם שני עדים המעידים בנפרד מצטרפים לעדות, \u0003ובפלוגתא דהני תנאי\u0004 \u0005[ובמחלוקת של אותם תנאים]\u0006 שנחלקו במפורש בשאלה זו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003אין עדותן\u0004 של עדים \u0003מצטרפת עד שיראו שניהם כאחד\u0004 את הדבר. \u0003ר' יהושע בן קרחה אמר: אפילו\u0004 ראו את המעשה \u0003בזה אחר זה\u0004 עדותם מצטרפת. \u0003ו\u0004כן \u0003אין עדותן\u0004 של עדים \u0003מתקיימת בבית־דין עד שיעידו שניהם כאחד,\u0004","\u0003ר' נתן אומר:\u0004 אין צורך שיעידו יחד, אלא \u0003שומעין דבריו של זה היום, וכשיבא חבירו למחר שומעין דבריו,\u0004 והעדויות מצטרפות. ובמחלוקת זו של תנא קמא ור' נתן נחלקו גם ר' אליעזר ורבן שמעון בן גמליאל. ר' אליעזר סבור כר' יהושע בן קרחה שאין עדות העד האחרון האומר שכהן הוא מועילה, כיון שאינה מצטרפת לעדות העד הראשון. ורבן שמעון בן גמליאל סבור כי יש לצרף עדות זו שנאמרה באחרונה לעדות שנאמרה בראשונה ומעמידים אותו על חזקתו, שהרי בן כהנים הוא.","\u0003האשה שנחבשה\u0004 (נאסרה) \u0003בידי גוים,\u0004 אם נאסרה \u0003על ידי\u0004 (לצורך) \u0003ממון,\u0004 שלקחו אותה כעין משכון עד שישלם בעלה ממון שהוא חייב — \u0003מותרת לבעלה\u0004 אפילו הוא כהן, שאין חוששים שנהגו בה מנהג הפקר ובעלו אותה. משום שהם יודעים שבעלה צריך לפדות אותה, ואם יבעלו אותה, שמא שוב לא ירצה לחיות איתה ולא יהיה לו איפוא ענין רב בתשלום חובו. אבל אם נחבשה \u0003על ידי נפשות,\u0004 שנידונה למוות — \u0003אסורה לבעלה,\u0004 שמא נהגו בה מנהג הפקר, והיא התרצתה להם.","\u0003אמר רב שמואל בר רב יצחק אמר רב: לא שנו\u0004 הלכה זו במשנתנו \u0003אלא\u0004 בזמן \u0003שיד ישראל תקיפה על אומות העולם\u0004 ואף הגויים עושים כדין, \u0003אבל\u0004 כאשר \u0003יד אומות העולם תקיפה על עצמן\u0004 (בלשון נקיה, והכוונה היא שידם תקיפה על ישראל) \u0003אפילו\u0004 אם נחבשה \u0003על ידי ממון — אסורה לבעלה,\u0004 שאין הם חוששים לנהוג בה מנהג הפקר.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבא\u0004 ממה ששנינו: \u0003העיד ר' יוסי הכהן ור' זכריה בן הקצב על בת ישראל שהורהנה\u0004 (נמסרה כמשכון) \u0003באשקלון, וריחקוה בני משפחתה,\u0004 שחששו שנבעלה שם, \u0003ועדיה\u0004 שהיו עמה \u0003מעידים אותה שלא נסתרה ושלא נטמאה. ואמרו להם חכמים\u0004 לבני המשפחה: \u0003אם אתם מאמינים שהורהנה — האמינו\u0004 לעדים שאומרים \u0003שלא נסתרה ושלא נטמאה, ואם אי\u0004 \u0005[אין]\u0006 \u0003אתם מאמינים שלא נסתרה ושלא נטמאה — אל תאמינו שהורהנה\u0004 כלל. ועל כל פנים היא כשירה.","ומכאן לעניננו: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אשקלון\u0004 שהיא מערי הפלישתים ו\u0003יד אומות העולם תקיפה על עצמן,\u0004 שהרי עיר גויים היתה, \u0003וקתני\u0004 \u0005[ושנה]\u0006 שם:"],["\u0003הורהנה\u0004 (נמסרה כמשכון), ומכאן שרק אם הורהנה, שבעלה הפקיד אותה מדעתו כמשכון, שאם לא ישלם יטלו אותה לשימושם \u0003— אין\u0004 \u0005[כן],\u0006 אבל אם \u0003נחבשה\u0004 על ידי השלטון — \u0003לא.\u0004 משמע שאין לחלק לא בין יד ישראל תקיפה ואינה תקיפה, אלא באופן שבו נתפסה האשה. ודוחים: \u0003לא, הוא הדין\u0004 שאסורה \u0003אפילו נחבשה\u0004 על ידי השלטון, \u0003ו\u0004אולם, \u0003מעשה שהיה, כך היה\u0004 — שהורהנה, אבל אין לדייק מכאן שבאופן אחר היא מותרת.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 נוסח אחר של השמועה, \u0003אמר רבא: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 ראיה לדברי רב שמואל בר רב יצחק. ששנינו: \u0003העיד ר' יוסי הכהן ור' זכריה בן הקצב על בת ישראל שהורהנה\u0004 (נמסרה כמשכון) \u0003באשקלון, וריחקוה בני משפחתה, ועדיה מעידים עליה שלא נסתרה ושלא נטמאה. ואמרו חכמים: אם אתם מאמינים שהורהנה — האמינו שלא נסתרה ושלא נטמאה, ואם אין אתם מאמינים שלא נסתרה ושלא נטמאה — אל תאמינו שהורהנה.\u0004","ונדייק מן הסיפור: \u0003והא\u0004 \u0005[והרי]\u0006 מקרה זה שהיה ב\u0003אשקלון,\u0004 שכל דבר מסירתה לידי הגויים \u0003על ידי\u0004 (לצורך) \u0003ממון הוה\u0004 \u0005[היה],\u0006 ולא היה כאן ענין של נפשות, \u0003וטעמא\u0004 \u0005[והטעם,\u0006 דווקא\u0005]\u0006 כש\u0003עדים מעידין אותה\u0004 (עליה) שהיא טהורה, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003אין עדים מעידין אותה\u0004 על כך שהיא טהורה — \u0003לא,\u0004 אינה נחשבת לטהורה, אף על פי שהיה על ידי ממון. ו\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נפרש ש\u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 ש\u0003הורהנה\u0004 מדעת, \u0003ולא שנא\u0004 \u0005[ואינו שונה]\u0006 ש\u0003נחבשה,\u0004 הרי שאם יד גויים תקיפה, אפילו שסיבת המאסר היא על ידי ממון, חוששים שנטמאה! ודוחים: \u0003לא, הורהנה שאני\u0004 \u0005[שונה],\u0006 שאפשר לומר שכיון שמשכנה בעלה מדעת, נוהגים בה הפקר, אבל אם נחבשה על ידי אחרים אין לחשוש לה.","ועוד נוסח אחר של הדברים: \u0003איכא דרמי לה מירמא\u0004 \u0005[יש שמשליך זאת\u0006 כ\u0005השלכה,\u0006 כסתירה\u0005],\u0006 שמראה סתירה בין שני מקורות: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 שאם נחבשה \u0003על ידי ממון מותרת לבעלה, ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ש\u0003העיד ר' יוסי כו'.\u0004 ומהי — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אשקלון\u0004 ש\u0003על ידי ממון\u0004 היה הדבר, \u0003וקתני טעמא\u0004 \u0005[ושנה הטעם]\u0006 שמותרת מפני ש\u0003עדים מעידים אותה\u0004 שלא נסתרה, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003אין עדים מעידין אותה — לא,\u0004 אינה מותרת, משמע שאפילו בנחבשה על ידי ממון יש לחשוש!","\u0003ומשני\u0004 \u0005[ומתרץ],\u0006 \u0003אמר רב שמואל בר רב יצחק: לא קשיא\u0004 \u0005[אין זה קשה]\u0006 \u0003כאן\u0004 במשנה, מדובר באופן \u0003שיד ישראל תקיפה על אומות העולם\u0004 ואז אם נחבשה על ידי ממון, מותרת, \u0003כאן — שיד אומות העולם תקיפה על עצמן\u0004 (על ישראל) ולכן גם אם נחבשה על ידי ממון אסורה, אלא אם כן יעידו עליה במפורש שטהורה היא.","שנינו במשנה שאם נחבשה \u0003על ידי (לצורך) נפשות\u0004 — \u0003אסורה\u0004 לבעלה. \u0003אמר רב:\u0004 כאן מדובר \u0003כגון נשי גנבי\u0004 \u0005[\u0006ה\u0005גנבים]\u0006 שנידונו למוות, שהמלכות מפקירה את כל רכושם ובכלל זה גם את נשיהם. \u0003ו\u0004אילו \u0003לוי אמר:\u0004 כאן מדובר \u0003כגון אשתו של\u0004 אלעזר \u0003בן דונאי\u0004 שהיה רוצח, ובמקרה כזה המלכות באמת מפקירה את אשתו, אבל כשנידון אדם למוות בגלל גניבה, אין המלכות מפקירה את כל אשר לו. \u0003אמר חזקיה: והוא שנגמר דינן להריגה,\u0004 רק אז מפקירים אותן, \u0003ור' יוחנן אמר: אף על פי שלא נגמר דינן להריגה,\u0004 אלא שאם היה המאסר מחמת דיני נפשות, כבר נוהגים בהן הפקר.","\u0003עיר שכבשוה כרכום\u0004 (מצור של צבא) — \u0003כל כהנות\u0004 (נשי הכהנים) \u0003שנמצאו בתוכה,\u0004 בתוך העיר, \u0003פסולות,\u0004 כלומר, אסורות לבעליהן, כי אנו חוששים שאנסו אותן החיילים, ואשת כהן שנבעלה לאחר אפילו באונס, אסורה לו. \u0003ואם יש להן עדים\u0004 שלא נבעלו — \u0003אפילו\u0004 היו העדים \u0003עבד, אפילו שפחה\u0004 שהם פסולים לעדות, \u0003הרי אלו נאמנין. ו\u0004אולם \u0003אין נאמן אדם על ידי עצמו,\u0004 שתעיד האשה על עצמה שלא נטמאה.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 ממה ששנינו: \u0003בלשת\u0004 (חיל) \u0003שבאה ל\u0004עשות חיפושים ב\u0003עיר,\u0004 אם באו \u0003בשעת שלום — חביות פתוחות\u0004 של יין שיש בעיר \u0003אסורות,\u0004 שאנו חוששים שהחיילים הגויים ניסכו מהן לעבודה זרה, וחביות \u0003סתומות מותרות,\u0004 שיש להניח שלא פתחו אותן. אולם אם הבלשת נכנסה לעיר \u0003בשעת מלחמה — אלו ואלו מותרות, לפי שאין פנאי לנסך,\u0004 שהחיילים חוששים מפני התקפה של האויב. ומאחר שבמשנתנו מדובר בחיילים שנכנסו בשעת מלחמה, מדוע חוששים שכל הכהנות נבעלו?","\u0003אמר רב מרי: לבעול יש\u0004 להם \u0003פנאי,\u0004 שהחיילים, מחמת תאוותם מוצאים זמן לכך אפילו בזמן מלחמה, ואולם \u0003לנסך אין\u0004 להם \u0003פנאי. ר' יצחק בר אלעזר משמיה\u0004 \u0005[משמו]\u0006 של \u0003חזקיה אמר,\u0004 אפשר לפרש באופן אחר: \u0003כאן\u0004 מדובר \u0003בכרכום של אותה מלכות,\u0004 שהצבא שלה צר על העיר שלה עצמה, ולכן הוא משתדל לא לגרום השחתה יתירה בעיר. ואילו \u0003כאן\u0004 במשנתנו — \u0003בכרכום של מלכות אחרת,\u0004 שכאשר מלכות אחרת כובשת, ודאי אין חייליה מקפידים לא על טהרת נשי העיר ולא על רכוש תושביה.","ומקשים: גם אם נכנס הצבא \u0003של אותה מלכות נמי\u0004 \u0005[גם כן]\u0006 \u0003אי אפשר\u0004 ש\u0003לא ערק חד מינייהו\u0004 \u0005[יברח\u0006 חייל \u0005אחד מהם]\u0006 ויאנוס אשה. \u0003אמר רב יהודה אמר שמואל:\u0004 מדובר פה \u0003כשמשמרות רואות זו את זו\u0004 ואין מניחים לחיילים לשלול ולבוז את העיר. ומקשים: גם כך הלא \u0003אי אפשר\u0004 ש\u0003לא ניימא פורתא\u0004 \u0005[ינמנמו קצת]\u0006 השומרים, ואחדים מהחיילים ייכנסו לעיר! \u0003אמר ר' לוי:\u0004 מדובר שעשו שמירה מיוחדת לעיר, \u0003כגון דמהדר לה למתא שושילתא וכלבא וגווזא ואווזא\u0004 \u0005[שמסבבים את העיר\u0006 ב\u0005שלשלאות וכלבים וענפים ואווזים\u0006 למכשול, לשמירה\u0005]\u0006 ובגלל כך אין אדם יכול להכנס בלי רשות.","\u0003אמר ר' אבא בר זבדא: פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה,\u0004 בשאלה זו, \u0003ר' יהודה נשיאה\u0004 נכדו של ר' יהודה מחבר המשנה, \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: כאן בכרכום של אותה מלכות, כאן בכרכום של מלכות אחרת, ולא קשיא ליה\u0004 \u0005[היה קשה לו]\u0006 \u0003ולא מידי\u0004 \u0005[דבר],\u0006 שאין חוששים שמא ייכנס חייל בודד לעיר. \u0003וחד קשיא ליה כל הני\u0004 \u0005[ואחד\u0006 מהם \u0005היה קשה לו כל\u0006 הקושיות \u0005הללו]\u0006 ששאלנו, \u0003ומשני\u0004 \u0005[ותירץ]\u0006 גם כן כפי שתירצנו: \u0003כגון דמהדר ליה למתא שושילתא וכלבא וגווזא ואווזא\u0004 \u0005[שסובבים את העיר\u0006 ב\u0005שלשלאות וכלבים וענפים ואווזים].\u0006","לענין הלכה זו שבמשנה \u0003אמר רב אידי בר אבין אמר ר' יצחק בר אשיאן: אם יש שם\u0004 בעיר \u0003מחבואה אחת,\u0004 מקום שבו יכולות הנשים להתחבא מפני החיילים — \u0003מצלת על הכהנות כולן.\u0004 כלומר, אנו תולים במחבואות, שהכהנות נחבאו שם. ואין פוסלים אותן מספק.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 אם המחבואה \u0003אינה מחזקת\u0004 (מכילה) \u0003אלא\u0004 אשה \u0003אחת מהו,\u0004 מה יהיה הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 כי \u0003כל חדא וחדא\u0004 \u0005[אחת ואחת]\u0006 שבאה לפנינו \u0003היינו הא\u0004 \u0005[זו היא זו]\u0006 שנחבאה שם, \u0003או דלמא לא אמרינן\u0004 \u0005[שמא אין אנו אומרים\u0006 זאת\u0005]?\u0006","ושואלים: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 הדבר \u0003מ\u0004דין \u0003שני שבילין,\u0004 שהיה ברור לנו ש\u0003אחד\u0004 מהם \u0003טמא ואחד\u0004 מהם \u0003טהור, והלך\u0004 אדם \u0003באחד מהן ועשה\u0004 (התעסק, נגע) לאחר מכן ב\u0003טהרות\u0004 ואינו זוכר באיזה מהם הלך, \u0003ובא חבירו והלך\u0004 בודאי \u0003ב\u0004שביל ה\u0003שני,\u0004 וגם הוא אינו זוכר באיזה שביל הלך, \u0003ועשה\u0004 גם הוא לאחר מכן \u0003טהרות,\u0004","\u0003ר' יהודה אומר: אם נשאל זה בפני עצמו וזה בפני עצמו,\u0004 כלומר, כל אחד מהם בא לחוד ושאל על ספק זה — הרי הטהרות שעשו, \u0003טהורות.\u0004 כי אנו תולים לגבי כל אחד שבשביל הטהור הלך, שיש כאן ספק טומאה ברשות הרבים, וטהור. ואם באו \u0003שניהם כאחת\u0004 להישאל — הרי הטהרות \u0003טמאות. ר' יוסי אומר: בין כך ובין כך טמאין\u0004 שניהם.","\u0003ואמר\u0004 על כך \u0003רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יוחנן:\u0004 אם באו להישאל \u0003בבת אחת — דברי הכל,\u0004 גם ר' יהודה מסכים, שהם \u0003טמאין.\u0004 אם באו להישאל לחוד בלי קשר \u0003בזה אחר זה — דברי הכל\u0004 ששניהם \u0003טהורים,\u0004 שאין מטמאים אותם מספק; \u0003לא נחלקו אלא ב\u0004אדם ש\u0003בא לישאל עליו ועל חבירו\u0004 שהלך בשביל השני. ובכך נחלקו: \u0003מר מדמי ליה\u0004 \u0005[חכם\u0006 זה, ר' יוסי, \u0005מדמה זאת]\u0006 \u0003ל\u0004מקרה בו באים שניהם לשאול \u0003בבת אחת\u0004 ולכן אוסר, \u0003ומר\u0004 \u0005[וחכם\u0006 זה, ר' יהודה\u0005]\u0006 \u0003מדמי ליה\u0004 \u0005[מדמה זאת]\u0006 לבאים לשאול \u0003בזה אחר זה. והכא נמי\u0004 \u0005[וכאן\u0006 במקום במחבוא לאחד \u0005גם כן]\u0006 \u0003כיון דשרי להו לכולהו\u0004 \u0005[שמתיר להן, לכל\u0006 הכהנות כולן\u0005],\u0006 שהרי אנו תולים במחבוא זה ומתירים את הכהנות כולן. \u0003כ\u0004אילו נשאלה השאלה \u0003בת אחת דמי\u0004 \u0005[נחשב]\u0006 הדבר, וצריך להחשיב את כולן לטמאות!","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בשני השבילים הלא \u0003ודאי איכא\u0004 \u0005[יש]\u0006 \u0003טומאה,\u0004 באחד מהשבילים, ואחד האנשים ודאי טמא, אבל \u0003הכא מי יימר דאיטמי\u0004 \u0005[כאן מי יאמר שנטמאה]\u0006 אף אחת מהן. וכיון שמתחילה יש ספק באיסור, אפשר שכאן נוכל לתלות להיתר יותר מאשר בשני שבילים.","באותו ענין \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 היתה מחבואה בעיר ו\u0003אמרה\u0004 הכהנת: \u0003לא נחבאתי ולא נטמאתי, מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006"],["\u0003מה לי לשקר,\u0004 שאילו היתה רוצה לשקר הלא היתה יכולה לומר שנחבאה. \u0003או דלמא לא אמרינן\u0004 \u0005[שמא אין אנו אומרים]\u0006 נימוק זה?","ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 ענין זה \u0003מההוא\u0004 \u0005[מאותו]\u0006 \u0003מעשה, דההוא גברא דאגר ליה חמרא לחבריה\u0004 \u0005[שאדם אחד השכיר לו חמור לחבירו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לשוכר: \u0003לא תיזיל באורחא\u0004 \u0005[אל תלך בדרך]\u0006 של \u0003נהר פקוד דאיכא מיא\u0004 \u0005[שיש\u0006 שם \u0005מים]\u0006 ועלול החמור לטבוע, ולכן \u0003זיל באורחא\u0004 \u0005[לך בדרך]\u0006 של \u0003נרש דליכא מיא\u0004 \u0005[שאין\u0006 שם \u0005מים],\u0006 \u0003ואזל איהו באורחא\u0004 \u0005[והלך הוא בדרך]\u0006 של \u0003נהר פקוד ומית חמרא\u0004 \u0005[ומת החמור].\u0006","\u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רבא, אמר ליה\u0004 \u0005[לו]\u0006 הנתבע: \u0003אין\u0004 \u0005[כן],\u0006 \u0003באורחא\u0004 \u0005[בדרך]\u0006 של \u0003נהר פקוד אזלי\u0004 \u0005[הלכתי],\u0006 \u0003מיהו\u0004 \u0005[אולם]\u0006 \u0003לא הוו מיא\u0004 \u0005[היו\u0006 שם \u0005מים],\u0006 והחמור מת מסיבה אחרת. \u0003אמר רבא:\u0004 במקרה כזה אפשר לסמוך עליו מפני הנימוק של \u0003\"מה לי לשקר\"\u0004 שהרי \u0003אי בעי אמר ליה\u0004 \u0005[אם היה רוצה\u0006 לשקר \u0005היה אומר לו]:\u0006 \u0003באורחא\u0004 \u0005[בדרך]\u0006 של \u0003נרש אזלי\u0004 \u0005[הלכתי].\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: \"מה לי לשקר\" במקום עדים לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006 כלומר, אין הטענה הזו של מיגו, מתוך שהיה יכול לשקר ולא שיקר, מועילה אלא כשאין עדות ודאית לגבי העובדות, אבל כאן, כיון שברור לנו שבדרך של נהר פקוד יש מים, אין לסמוך על דבריו, למרות הטיעון של \"מה לי לשקר\". ואם כן גם כאן אנו יכולים לומר שכיון שאנו יודעים שהנשים שנשבו ודאי נבעלו, אין סומכים על האשה מכוח מיגו.","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003ודאי איכא\u0004 \u0005[יש]\u0006 \u0003עדים\u0004 שיכולים להעיד \u0003דאיכא מיא\u0004 \u0005[שיש מים]\u0006 בדרך הזו, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 באשה האומרת לא נחבאתי ולא נטמאתי, האם \u0003ודאי איטמי\u0004 \u0005[נטמאה]?\u0006 הלא רק \u0003חששא\u0004 \u0005[חשש]\u0006 \u0003הוא ובמקום\u0004 של \u0003חששא\u0004 \u0005[חשש]\u0006 בלבד — \u0003אמרינן\u0004 \u0005[אנו אומרים],\u0006 סומכים על הנימוק של \"מה לי לשקר\".","שנינו במשנה ש\u0003אם יש עדים\u0004 שלא נטמאו נשי העיר על ידי החיילים, \u0003אפילו\u0004 היו אותם עדים \u0003עבד ואפילו שפחה — נאמנין.\u0004 ושואלים: \u0003ואפילו שפחה דידה\u0004 \u0005[שלה]\u0006 \u0003מהימנא\u0004 \u0005[נאמנת]?\u0006 \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 ממה ששנינו: מי שגירש את אשתו על תנאי, ועדיין לא התקיים התנאי, \u0003לא תתייחד\u0004 האשה \u0003עמו אלא על פי עדים,\u0004 שיש לחשוש שמא יבוא עליה ואם אחר־כך יתקיים התנאי נמצא שהיתה כבר מגורשת כשבא עליה, והגט נפסל.","\u0003ואפילו על פי עבד ועל פי שפחה\u0004 מותר לה להתייחד כי הם מספיקים לזה, \u0003חוץ משפחתה.\u0004 וטעם הדבר: \u0003מפני שלבה גס בשפחתה,\u0004 שמפני שרגילה בה וקרובה אליה, לא תימנע מלהיבעל אף ששפחתה נמצאת שם. משמע ששפחתה שלה אינה נאמנת לומר שלא נבעלה! \u0003אמר רב פפי:\u0004 יש לחלק, כי \u0003בשבויה הקילו.\u0004 כיון שכל האיסור אינו אלא מפני חשש, הקילו חכמים בדיני שבויה, וסמכו אפילו על עדות שפחה שלה.","\u0003רב פפא אמר,\u0004 יש לתרץ באופן אחר: \u0003הא\u0004 \u0005[זה]\u0006 שאין השפחה נאמנת ואפילו בשבויה, הרי זה דווקא \u0003בשפחה דידה\u0004 \u0005[שלה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרו שאפילו על פי שפחה, הרי זה \u0003בשפחה דידיה\u0004 \u0005[שלו],\u0006 שלענין זה היא נאמנת.","ותוהים: וכי \u0003שפחה דידה\u0004 \u0005[שלה]\u0006 \u0003לא מהימנא\u0004 \u0005[אינה נאמנת]?\u0006 \u0003הא קתני\u0004 \u0005[הרי שנה]\u0006 \u0003אין אדם מעיד על עצמו,\u0004 ומכאן נדייק: רק הוא עצמו בלבד אינו נאמן \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שפחה דידה\u0004 \u0005[שלה]\u0006 \u0003מהימנא\u0004 \u0005[נאמנת]!\u0006 ודוחים: אפשר לומר כי \u0003שפחתה נמי\u0004 \u0005[גם כן]\u0006 \u0003כעצמה דמי\u0004 \u0005[נחשבת].\u0006","\u0003רב אשי אמר: הא והא\u0004 \u0005[זה וזה]\u0006 מדובר \u0003בשפחה דידה\u0004 \u0005[שלה],\u0006 \u0003ו\u0004יש להבדיל בין הדינים; \u0003שפחה מיחזא חזיא ושתקה\u0004 \u0005[רואה ושותקת],\u0006 אבל אינה מעידה שקר. ולכן, \u0003התם\u0004 \u0005[שם]\u0006 בענין גט ש\u0003שתיקתה\u0004 של השפחה \u0003מתירתה,\u0004 שגם אם תשתוק ולא תספר שראתה שנבעלה — מותרת האשה על פי הגט, לכן \u0003לא מהימנא\u0004 \u0005[אין\u0006 השפחה \u0005נאמנת]\u0006 שמא ראתה שנבעלה ולא סיפרה. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 ש\u0003שתיקתה אוסרתה,\u0004 שכל עוד אינה מעידה עליה שהיא טהורה, הרי היא בחזקת בעולה — \u0003מהימנא\u0004 \u0005[נאמנת].\u0006","ושואלים: \u0003השתא נמי אתיא ומשקרא\u0004 \u0005[עכשיו גם כן תבוא ותשקר]\u0006 לטובת גבירתה! ומשיבים: \u0003תרתי\u0004 \u0005[שתי]\u0006 עבירות היא \u0003לא עבדה\u0004 \u0005[תעשה],\u0006 שגם להעלים את האמת, וגם לספר שקר, לזה אין אנו חוששים. ולכן אם באה וסיפרה שגבירתה לא נטמאה — הריהי נאמנת. ומביאים ראיה לדבר שאין חוששים להעלמת העובדות ולשקר יחד.","\u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003מרי בר איסק, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003חנא בר איסק, אתא ליה אחא\u0004 \u0005[בא לו אח]\u0006 \u0003מבי חוזאה\u0004 שהוא מחוז רחוק מן הישוב היהודי העיקרי בבבל, כלומר, בא אדם וטען שהוא אחיו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פלוג\u0004 \u0005[חלוק]\u0006 \u0003לי\u0004 חלק \u0003בנכסי דאבא\u0004 \u0005[אבינו\u0006 שמת\u0005]!\u0006 שבהיותו צעיר נטלו אביו והביאו לבי חוזאה וגדלו שם, ומת שם אביו, וחזר זה לתבוע חלקו בירושת האב. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא ידענא לך\u0004 \u0005[איני מכיר אותך].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 אותו אח \u0005לפני]\u0006 \u0003רב חסדא\u0004 לטעון. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003שפיר קאמר לך\u0004 \u0005[יפה אמר לך],\u0006 כלומר, טענה זו יש לה ביסוס, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויכר יוסף את אחיו והם לא הכרהו\"\u0004 (בראשית מב, ח), \u0003מלמד שיצא\u0004 יוסף מארץ כנען \u0003בלא חתימת זקן ובא\u0004 כשפגשו אותו \u0003בחתימת זקן,\u0004 ולכן לא הכירוהו. ואם כן יש בסיס לטענתו שאינו מכיר אותך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003זיל אייתי סהדי דאחוה את\u0004 \u0005[לך הבא עדים שאחיו אתה]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אית\u0004 \u0005[יש]\u0006 \u0003לי סהדי\u0004 \u0005[עדים],\u0006 \u0003ומסתפינו מיניה, דגברא אלמא\u0004 \u0005[ו\u0006הם \u0005מפחדים ממנו, שאדם אלים]\u0006 \u0003הוא\u0004 ולכן לא יעידו לטובתי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא \u0003לדידיה\u0004 \u0005[לו],\u0006 לנתבע: \u0003זיל אייתינהו את דלאו אחוך\u0004 \u0005[לך הבא אתה\u0006 עדים \u0005שלא אחיך]\u0006 \u0003הוא. אמר ליה\u0004 \u0005[לו]\u0006 הנתבע: וכי \u0003דינא הכי\u0004 \u0005[הדין כך]?\u0006 הלא \u0003המוציא מחבירו עליו הראיה\u0004 וזה שרוצה להוציא ממני חלק מירושת האב, צריך להוכיח את דבריו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003הכי דאיננא לך ולכולהו אלמי חברך\u0004 \u0005[כך אני דן אותך ואת כל האלימים חבריך],\u0006 שאני הופך את חובת הראיה עליך. והרי יש לחשוש \u0003השתא נמי אתו ומשקרי\u0004 \u0005[עכשיו גם כן יבואו\u0006 העדים \u0005וישקרו\u0006 מפני הפחד ממנו\u0005],\u0006 אלא שיש לומר: \u0003תרתי\u0004 \u0005[שתי\u0006 עבירות\u0005]\u0006 \u0003לא עבדי\u0004 \u0005[יעשו];\u0006 גם להעלים את האמת וגם לשקר. הרי שסומכים על נימוק זה ואפילו במקום שחוששים לעדות שקר.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שדבר זה, עדות השפחה, תלוי במחלוקת \u0005תנאים],\u0006 ששנינו: \u0003זו\u0004 ה\u0003עדות\u0004 שהשבויה לא נטמאה — \u0003איש ואשה, תינוק ותינוקת, אביה ואמה, ואחיה ואחותה,\u0004 כל אלו נאמנים בה, \u0003אבל לא בנה ובתה\u0004 ו\u0003לא עבדה ושפחתה. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003הכל נאמנין להעיד\u0004 על השבויה, \u0003חוץ מהימנה\u0004 \u0005[ממנה,\u0006 היא עצמה\u0005]\u0006 \u0003ובעלה.\u0004","ומעירים: לפי פירושם של \u0003רב פפי ו\u0004של \u0003רב אשי תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 ודאי \u0003היא,\u0004 שהרי מפורש שיש ברייתא האומרת שלא הכל נאמנים להעיד עליה. אלא שיש עוד לברר האם זו שאמר \u0003רב פפא\u0004 שיש לחלק בין שפחה שלה ושלו, \u0003מי לימא תנאי\u0004 \u0005[האם\u0006 יש \u0005לומר\u0006 שמחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 האם שפחה שלה נאמנת או שנאמר שאין מחלוקת בין הברייתות, וברייתא אחת מדברת בשפחה שלו וברייתא שניה בשפחה שלה.","ודוחים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003רב פפא\u0004 שאין סתירה מכאן לדבריו, \u0003כי תניא\u0004 \u0005[כאשר שנויה]\u0006 הברייתא \u0003ההיא\u0004 שאומרת שהכל נאמנים להעיד ואפילו שפחתה, מדובר \u0003במסיחה לפי תומה\u0004 שמתוך דבריה שמדברת לתומה מתברר הענין. אבל לעדות אין שפחתה נאמנת.","ומסופר: \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר: רב חנן קרטיגנאה\u0004 \u0005[\u0006מהעיר \u0005קרטגו]\u0006 \u0003משתעי\u0004 \u0005[היה מספר]:\u0006 \u0003מעשה בא לפני ר' יהושע בן לוי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003ר' יהושע בן לוי מישתעי\u0004 \u0005[היה מספר]:\u0006 \u0003מעשה בא לפני רבי באדם אחד, שהיה מסיח לפי תומו, ואמר: אני ואמי נשבינו לבין הגויים.\u0004 כאשר \u0003יצאתי לשאוב מים — דעתי על אמי,\u0004 וכאשר יצאתי \u0003ללקט עצים — דעתי על אמי,\u0004 ולא נפרדתי ממנה כלל. \u0003והשיאה רבי לכהונה על פיו\u0004 של הבן. שלא נתכוון כלל להעיד שלא נתייחדה, אלא כיון שאמר זאת לפי תומו — הרי הוא נאמן, אפילו שבדרך כלל הוא פסול להעיד לה משום קרוב. ובכגון זה גם שפחתה נאמנת.","\u0003אמר ר' זכריה בן הקצב\u0004 הכהן, בלשון שבועה: \u0003המעון הזה\u0004 (מעון השכינה)! \u0003לא זזה ידה\u0004 של אשתי \u0003מתוך ידי משעה שנכנסו גויים לירושלים ועד שיצאו,\u0004 ויודע אני בה שלא אנסוה וטהורה היא. \u0003אמרו לו:\u0004 אף על פי כן, \u0003אין אדם מעיד על עצמו,\u0004 וכיון שכלל הוא שאשתו כגופו, לכן אין עדותך מתקבלת, ואשתך אסורה לך.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003ואף על פי כן,\u0004 למרות שאסרו את אשתו עליו מפני שכהן היה, לא גירש אותה, אלא \u0003ייחד לה בית בחצרו\u0004 שתגור בו, אבל הקפיד שלא להתייחד עמה, \u0003וכשהיא יוצאה\u0004 מן הבית \u0003יוצאה בראש בניה\u0004 והילדים מבדילים בינה ובינו, \u0003וכשהיא נכנסת\u0004 לבית \u0003נכנסת בסוף בניה,\u0004 כך שלעולם לא היו שניהם ביחידות.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אביי: מהו לעשות בגרושה כן?\u0004 האם כהן שגירש את אשתו יוכל לסמוך על כך שתגור בחצירו ושהילדים יהיו נמצאים תמיד במקום באופן שלא יתייחדו? וצדדי השאלה: \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 בר' זכריה בן הקצב, הותר הדבר משום ש\u0003בשבויה הקילו,\u0004 שהרי עיקר האיסור אינו אלא משום חשש בלבד, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בגרושה שאסורה לכהן מן התורה — \u0003לא, או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003המגרש את אשתו — לא תנשא\u0004 האשה לאדם אחר \u0003בשכונתו,\u0004 ותגור שם, שיש לחשוש שמפני הקירבה שהיתה ביניהם יבואו לידי עבירה."],["\u0003ואם היה כהן — לא תדור עמו ב\u0004אותו \u0003מבוי,\u0004 ואפילו כשלא נישאה, שהרי היא אסורה עליו לעולם. אבל אם הוא ישראל — מותר לה לדור באותו מבוי בו הוא דר. \u0003אם היה כפר קטן,\u0004 איך הוא נידון? \u0003זה היה מעשה\u0004 בגרושה שנישאה בכפר קטן ונשאלו חכמים על כך \u0003ואמרו: כפר קטן נידון כשכונה.\u0004","אגב כך שואלים, \u0003מי נדחה מפני מי,\u0004 כלומר, מי מהם צריך לעזוב את המקום? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003היא נדחית מפניו,\u0004 וצריכה לעבור למקום אחר, \u0003ואין הוא נדחה מפניה. ואם היתה חצר שלה — הוא נדחה מפניה.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003היתה חצר של שניהם מהו,\u0004 מי מהם נדחה? ומביאים פתרון, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שנאמר בברייתא: \u0003היא נדחית מפניו.\u0004 ונברר: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בחצר שלו — פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שהיא צריכה להידחות! \u0003ואלא\u0004 תאמר שמדובר \u0003בחצר שלה, והתניא\u0004 \u0005[והרי\u0006 \u0005שנינו בברייתא\u0006\u0005]\u0006 \u0003אם היתה חצר שלה — הוא נדחה מפניה. אלא לאו כי האי גוונא\u0004 \u0005[האם לא כמו כגון זה],\u0006 כאשר החצר היא של שניהם. ודוחים: לא, \u0003דלמא דאגיר מיגר\u0004 \u0005[שמא\u0006 מדובר כאשר הוא \u0005שכר\u0006 את החצר\u0005]\u0006 שגם אז היא נדחית מפניו, אבל במקום שהוא של שניהם — אין לנו פתרון.","ושואלים: אם כן, \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה,\u0006 על שאלה זו\u0005]\u0006 הלכה למעשה? ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון ממה שנאמר: \u0003\"הנה ה' מטלטלך טלטלה גבר\"\u0004 (ישעיהו כב, יז) \u0003ואמר רב:\u0004 מכאן למדים כי \u0003טלטולי דגברא קשין מדאיתתא\u0004 \u0005[טלטולי גבר קשים מ\u0006טלטולי \u0005אשה]\u0006 ולכן האשה היא שנדחית.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 כהן שגירש את אשתו, ובעודה אשתו \u0003לוה הימנה בנכסי אביה,\u0004 כלומר, בנכסי מלוג שהיו לה בירושה — מאחר שנתגרשה \u0003אינה נפרעת\u0004 ממנו \u0003אלא על ידי\u0004 אדם \u0003אחר\u0004 ולא במישרין, כדי שלא יהיה ביניהם כל משא־ומתן. \u0003אמר רב ששת: ואי אתו לקמן לדינא\u0004 \u0005[ואם\u0006 שניהם \u0005באים לפנינו לדין]\u0006 כאשר הסתכסכו במשא־ומתן שביניהם, \u0003לא מזדקקינן להו\u0004 \u0005[אין אנו נזקקים להם]\u0006 לדון בעניינם, משום שעברו עבירה בעצם קיום המשא־ומתן. \u0003רב פפא אמר: שמותי משמתינן להו\u0004 \u0005[אנו מנדים אותם]\u0006 על עבירה זו. \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: נגודי נמי מנגדינן להו\u0004 \u0005[אנו גם כן מלקים אותם].\u0006 \u0003אמר רב נחמן: תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003ב\"אבל רבתי\"\u0004 (מסכת העוסקת בעיקרה בדיני אבילות): \u0003במה דברים אמורים — שנתגרשה מן הנשואין, אבל כשנתגרשה מן האירוסין — נפרעת\u0004 גם \u0003על ידי עצמה,\u0004 ומדוע — \u0003שאין לבו גס\u0004 (רגיל) \u0003בה,\u0004 ואין לחשוש שיבואו לידי עבירה.","מסופר: \u0003ההוא ארוס וארוסתו דאתו לקמיה\u0004 \u0005[שבאו\u0006 לדין \u0005לפני]\u0006 \u0003רבא\u0004 לאחר שנתגרשו. \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב אדא בר מתנא קמיה\u0004 \u0005[לפניו]\u0006 בשעת הדין. \u0003אוקי\u0004 \u0005[העמיד]\u0006 \u0003רבא שלוחא בינתייהו\u0004 \u0005[שליח\u0006 שלו \u0005ביניהם],\u0006 שלא יהיו יחד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר מתנא: והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן: תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003ב\"אבל רבתי\"\u0004 שאם נתגרשה מן האירוסין אין חוששים לכך! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קא חזינן דקא גייסי בהדדי\u0004 \u0005[אנו רואים ש\u0006לבם \u0005גס זה בזה],\u0006 וכיון שיש ביניהם קירבה יתירה, צריך להפרידם ביותר.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בנוסח אחר: \u0003לא אוקי\u0004 \u0005[העמיד]\u0006 \u0003רבא שליח בינתייהו\u0004 \u0005[ביניהם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רב אדא בר מתנא: ניקום מר שלוחא בינתייהו\u0004 \u0005[יעמיד אדוני שליח ביניהם],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב נחמן: תנא ב\"אבל רבתי\"\u0004 שבארוסה אין חשש! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הני מילי, היכא דלא גייסי בהדדי\u0004 \u0005[דברים אלה\u0006 אמורים, דווקא \u0005במקום שאין\u0006 לבם \u0005גס זה בזה],\u0006 \u0003אבל הני\u0004 \u0005[אלה] —\u0006 \u0003קא חזינא להו דגייסי בהדדי\u0004 \u0005[אנו רואים אותם ש\u0006לבם \u0005גס זה בזה]\u0006 ויש להקפיד להפריד ביניהם.","\u0003ואלו נאמנין להעיד בגודלן\u0004 (בהיותם גדולים) \u0003מה שראו בקוטנן\u0004 (כשהיו קטנים): \u0003נאמן אדם לומר \"זה כתב ידו של אבא\"\u0004 ולקיים בכך את השטר, אף שמת אביו בעודו קטן ולא ראה את כתב היד הזה כשהוא גדול, או \u0003\"זה כתב ידו של רבי\",\u0004 או \u0003\"זה כתב ידו של אחי\".\u0004","וכן נאמן הוא לומר: \u0003\"זכור הייתי בפלונית ש\u0004כאשר נישאה \u0003יצאה בהינומא וראשה פרוע\u0004 כדרך הבתולות \u0003\",\u0004 וכתובתה מאתים ככתובת בתולה. או \u0003\"שהיה איש פלוני\u0004 בעודו קטן \u0003יוצא מבית הספר\u0004 בו למדתי גם אני כדי \u0003לטבול,\u0004 כדי שיוכל \u0003לאכול בתרומה\",\u0004 שבזה ראיה שהוא כהן. או \u0003\"שהיה חולק עמנו\u0004 תרומה \u0003על הגורן\". ו\u0004כן יכול הוא להעיד ש\u0003\"המקום הזה בית הפרס\",\u0004 שהוא מקום שיש בו ספק טומאה, שהיה בו קבר וחרשו אותו והתפזרו שם העצמות. \u0003ו\u0004מעיד כמו כן ש\u0003\"עד כאן היינו באין בשבת\"\u0004 ונדע שזהו תחום השבת.","על דברים אלה הוא נאמן, \u0003אבל אין אדם נאמן לומר \"דרך היה לפלוני במקום הזה\",\u0004 או \u0003\"מעמד ומספד היה לפלוני במקום הזה\"\u0004 והמקום שייך איפוא לאותו אדם, שבעדות של דיני ממונות ממש אינו נאמן.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 בענין נאמנות אדם להעיד על כתב היד שראה כשהיה קטן — \u0003והוא שיש גדול עמו,\u0004 שיש עד אחר, מבוגר, המעיד גם הוא שמכיר את כתב היד, ואז מצטרפות שתי העדויות.","על הפרטים שנזכרו במשנה לגבי כתב היד מעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו כולם, שיש חידוש בכל אחד מהם. \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק ב\u0003אביו —\u0004 היינו אומרים שנאמן עליו \u0003משום דשכיח גביה\u0004 \u0005[ש\u0006הוא \u0005מצוי אצלו]\u0006 ובקי בכתב ידו, \u0003אבל\u0004 להעיד על כתב יד \u0003רבו — לא.\u0004 ולהיפך, \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק ב\u0003רבו —\u0004 היינו אומרים שנאמן \u0003משום דאית ליה אימתיה דרביה\u0004 \u0005[שיש לו אימת רבו]\u0006 ולכן שם לב, והשגיח יפה בכתבו, \u0003אבל אביו — לא.\u0004","\u0003ואי אשמעינן הני תרתי\u0004 \u0005[ואם היה משמיע לנו\u0006 רק את \u0005שני אלה],\u0006 אביו ורבו, היינו אומרים: \u0003אביו\u0004 נאמן עליו — מפני \u0003דשכיח גביה\u0004 \u0005[שמצוי אצלו],\u0006 \u0003ורבו\u0004 נאמן עליו — משום \u0003דאית ליה אימתיה\u0004 \u0005[שיש לו אימה],\u0006 \u0003אבל אחיו דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003לא הא\u0004 \u0005[זה]\u0006 \u0003ולא הא\u0004 \u0005[זה] —\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהיה נאמן, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שנאמן. והטעם בזה — \u0003כיון\u0004 שעצם הצורך של \u0003קיום שטרות\u0004 כולו אינו אלא \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 כי מדין תורה עדים החתומים על השטר משמשים הוכחה לאמיתותו, וצריך עדות כדי לפסול את השטר ולא כדי לקיימו, על כן \u0003הימנוהו רבנן בדרבנן\u0004 \u0005[האמינו לו חכמים ב\u0006עדות לקיום השטר שהיא רק \u0005מ\u0006דברי \u0005סופרים].\u0006","שנינו במשנה שנאמן לומר \u0003\"זכור הייתי בפלונית שיצאה בהינומא וראשה פרוע\". מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שנאמן בדבר — \u0003כיון\u0004 ש\u0003רוב\u0004 ה\u0003נשים\u0004 כשהן \u0003בתולות\u0004 הן \u0003נישאות,\u0004 הרי יש לסתם אשה חזקה שנישאה כשהיא בתולה, ולכן מה שמעיד על כך, אף שמעיד על מה שראה בקטנותו, רק \u0003גלוי מלתא\u0004 \u0005[דבר]\u0006 \u0003בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא\u0004 ולא עדות של ממש, ולכן נאמן.","עוד שנינו במשנה, שנאמן לומר \u0003שהיה איש פלוני יוצא מבית הספר לטבול לאכול בתרומה.\u0004 ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003עבד כהן הוא,\u0004 שאף הוא מותר לאכול בתרומה? ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 דבר זה \u0003ל\u0004שיטת \u0003ר' יהושע בן לוי.\u0004 ש\u0003אמר ר' יהושע בן לוי: אסור לאדם שילמד את עבדו תורה.\u0004 ולכן, כיון שהיה בבית הספר — הרי זו הוכחה שאינו עבד, ואם אכל בתרומה הרי שכהן הוא.","ושואלים: \u0003ולא\u0004 (האם אסור לעבד ללמוד)? \u0003והתניא\u0004 \u0005[והרי\u0006 \u0005שנינו בברייתא\u0006\u0005]:\u0006 עבד ש\u0003לוה הימנו\u0004 ממנו \u0003רבו\u0004 כסף, \u0003או שעשאו רבו\u0004"],["\u0003אפוטרופוס\u0004 (ממונה על נכסיו), \u0003או שהניח תפילין בפני רבו, או שקרא שלשה פסוקים בבית הכנסת — הרי זה לא יצא לחירות.\u0004 שאף שהעבד נראה בכל אלה נוהג מנהג בן חורין, אין זו הוכחה שהוא בן חורין, וייתכן שעדיין הוא עבד. ולענייננו נלמד מכאן, שייתכן שעבד למד תורה עד שידע לקרוא בבית הכנסת, ובודאי למד בבית הספר! ודוחים: \u0003התם דאיקרי\u0004 \u0005[שם\u0006 מדובר \u0005שקרא]\u0006 ה\u0003עבד מדעתו,\u0004 וייתכן שהעבד למד מעצמו לקרוא. \u0003כי קאמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 — הרי זה דווקא באופן \u0003דקא נהיג ביה\u0004 \u0005[שהוא נוהג בו]\u0006 \u0003מנהג בנים,\u0004 ששולח אותו לבית הספר, ואין נוהגים כך בעבדים.","מה שאמרו במשנה שנאמן להעיד על זכרון ילדות שהלך פלוני \u0003לטבול לאכול בתרומה,\u0004 מסבירים כי הוא נאמן דווקא \u0003בתרומה דרבנן\u0004 \u0005[ש\u0006מדברי \u0005חכמים],\u0006 שבתרומה שהיא רק מדברי סופרים, האמינו חכמים לעדותו ורשאי לחלוק בתרומה זו. עוד שנינו במשנה, שנאמן להעיד \u0003שהיה\u0004 פלוני \u0003חולק עמנו על הגורן.\u0004 ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003עבד כהן הוא?\u0004 ולכן רשאי לחלוק בתרומה! ועונים: חייבים לומר כי \u0003תנן כמאן דאמר\u0004 \u0005[שנינו\u0006 איפוא במשנה \u0005כ\u0006דעת \u0005מי שאומר]\u0006 ש\u0003אין חולקין תרומה לעבד\u0004 בגורן \u0003אלא אם כן רבו עמו\u0004 ולכן זה שחלקו לו תרומה לבד, ודאי אינו עבד כהן אלא כהן. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 ביחס לוולדות: בן כהן ובן שפחה שנתערבו בלידתם, אם בא אחד מהם לחלוק בגורן לבדו — אין חולקים לו, כיון שיתכן שהוא בן השפחה, ו\u0003אין חולקין תרומה לעבד, אלא אם כן רבו עמו,\u0004 אלו \u0003דברי ר' יהודה. ר' יוסי אומר: יכול הוא,\u0004 כל אחד מהם, לבוא ולקחת תרומה, \u0003שיאמר: אם כהן אני — תנו לי בשביל עצמי, ואם עבד כהן אני — תנו לי בשביל רבי.\u0004 ומסבירים את טעמי השיטות: \u0003במקומו של ר' יהודה היו מעלין מתרומה ליוחסין,\u0004 ומשום כך אסר לתת תרומה בפרהסיה לעבד כהן (אלא אם כן רבו עמו) שמא יסמכו על כך להעיד עליו שכהן הוא. ואילו \u0003במקומו של ר' יוסי לא היו מעלין מתרומה ליוחסין,\u0004 ולכן לא חשש אם נותנים לו תרומה גם אם אין רבו עמו.","","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אלעזר בר' יוסי: מימי לא העדתי\u0004 (לא נזדמן לי להעיד) בבית דין. \u0003פעם אחת\u0004 בלבד \u0003העדתי והעלו עבד לכהונה על פי.\u0004 ותוהים: \u0003העלו\u0004 ממש \u0003סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר?! \u0003השתא\u0004 \u0005[עכשיו\u0006 הרי\u0005]\u0006 \u0003ומה בהמתן של צדיקים אין הקדוש ברוך הוא מביא תקלה על ידם,\u0004 כמסופר בחמורו של ר' פנחס בן יאיר שלא אכל טבל (חולין ז, א), ה\u0003צדיקים עצמם לא כל שכן\u0004 שאין תקלה באה על ידם!","ומסבירים: \u0003אלא,\u0004 יש לתקן ולגרוס: \u0003בקשו להעלות עבד לכהונה על פי,\u0004 ולבסוף לא העלו. ומסבירים כיצד אירע הדבר: \u0003חזא באתריה\u0004 \u0005[ראה במקומו]\u0006 של \u0003ר' יוסי\u0004 שאותו עבד חלק בתרומה בגורן, \u0003ואזל ואסהיד באתריה\u0004 \u0005[והלך והעיד במקומו]\u0006 של \u0003ר' יהודה\u0004 על עובדה זו, אלא שבאותו מקום שימשה זאת הוכחה לענין יוחסין, שהרי במקום זה חולקים לעבד רק בנוכחות רבו, ולפיכך לא ידעו שהוא עבד, ולכן כמעט אירעה תקלה על ידו. עוד שנינו במשנה שנאמן להעיד בגדלותו \u0003שהמקום הזה בית הפרס הוא\u0004 (מקום שיש בו חשש טומאה, כגון שהיה שם קבר ונחרש ונתפזרו העצמות בכל השדה). ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר, הלא כשראה זאת היה קטן? — משום שטומאת \u0003בית הפרס\u0004 היא רק \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005סופרים].\u0006 ש\u0003אמר רב יהודה אמר שמואל: מנפח אדם\u0004 ב\u0003בית הפרס והולך,\u0004 כלומר, מותר לאדם ללכת בתוך בית הפרס ולנפוח בפיו לפני הליכתו בעפר, כדי לבדוק אם יש לפניו עצם קטנה מן המת, ואינו צריך לחשוש עוד לטומאה. \u0003ו\u0004כן \u0003רב יהודה בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יהודה אמר: בית הפרס שנידש,\u0004 שעברו ודרסו בו אנשים — \u0003טהור,\u0004 ואין חוששים עוד לטומאה. \u0003מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003אי אפשר לעצם כשעורה\u0004 (שבגלל האפשרות שנמצאת העצם שם, המקום טמא) \u0003שלא נידש ברגל\u0004 ונתמעט משיעורו. ומזה שסומכים על דברים כגון אלה לטהר את בית הפרס, הרי זו הוכחה שטומאת בית הפרס אינה מן התורה, אלא רק חשש מדברי סופרים, ולכן די אף בעדות כזו של קטן והגדיל כדי לנהוג במקום זה כבית הפרס. \u0003ו\u0004כן נאמן להעיד בגדלותו ש\u0003עד כאן היינו באין בשבת.\u0004 ומסבירים: \u0003קסבר\u0004 \u0005[סבור]\u0006 תנא זה שאיסור \u0003תחומין,\u0004 שאסור לצאת חוץ לתחום בשבת, הוא רק איסור \u0003דרבנן\u0004 \u0005[מ\u0006דברי \u0005סופרים]\u0006 בלבד, ולכן האמינוהו חכמים בדבריהם. ועוד שנינו: \u0003אין נאמן לומר \"דרך היה לפלוני במקום הזה\",\u0004 או \u0003\"מעמד ומספד היה לפלוני במקום הזה\".\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אינו נאמן — משום ש\u0003אפוקי ממונא לא מפקינן\u0004 \u0005[להוציא ממון\u0006 מאדם על פי עדות זו \u0005אין מוציאים].\u0006","","","","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נאמן התינוק לומר\u0004 בהיותו גדול: \u0003כך אמר לי אבא\u0004 כשהייתי קטן: \u0003\"משפחה זו טהורה, משפחה זו טמאה\".\u0004 ותחילה מבררים את הלשון: \u0003טהורה וטמאה סלקא דעתך\u0004 \u0005[עולה על דעתך],\u0006 וכי ענין של טהרה וטומאה יש במשפחה? \u0003אלא\u0004 הכוונה היא כי \u0003משפחה זו כשרה, ומשפחה זו פסולה.\u0004 \u0003ו\u0004כן נאמן להעיד \u0003\"שאכלנו בקצצה של בת פלוני לפלוני\",\u0004 כאשר יבואר. \u0003ו\"שהיינו מוליכים חלה ומתנות לפלוני כהן\".\u0004 ונאמן להעיד בזה דווקא \u0003על ידי עצמו,\u0004 כלומר, שהוא אומר שהוא עצמו היה מוליך תרומה, \u0003אבל לא על ידי אחר,\u0004 שמעיד שראה שאחרים הוליכו תרומה לאותו אדם. שבמה שאירע בו הוא יודע את הדברים בודאות, אבל לגבי אחרים אין עדותו של הקטן מספיקה. \u0003ו\u0004בכל העדויות הללו \u0003כולן, אם היה גוי ונתגייר,\u0004 או \u0003עבד ונשתחרר — אין נאמנים\u0004 על מה שראו כשלא היו כשרים להעיד. \u0003ואין נאמן לומר \"דרך היה לפלוני במקום הזה\", \"מעמד ומספד היה לפלוני במקום הזה\". ר' יוחנן בן ברוקא אומר: נאמנים.\u0004","","ושואלים: \u0003ר' יוחנן בן ברוקא אהייא\u0004 \u0005[על איזו],\u0006 לאיזה ענין הוא מתייחס? \u0003אילימא אסיפא\u0004 \u0005[אם תאמר\u0006 שהוא חולק \u0005על סופה]\u0006 של הברייתא, שאין נאמנות לקטן להעיד על דרך של פלוני, תמוה הוא: הלא \u0003אפוקי ממונא\u0004 \u0005[הוצאת ממון]\u0006 \u0003הוא,\u0004 וכיצד נאמנים להעיד על כך? \u0003אלא\u0004 ודאי \u0003ארישא\u0004 \u0005[על ראשה]\u0006 של הברייתא הוא חולק. שנאמר \u0003וכולם, אם היה גוי ונתגייר, עבד ונשתחרר — אין נאמנין. ר' יוחנן בן ברוקא אומר:\u0004 אף הם \u0003נאמנין.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 באיזה עקרון \u0005נחלקו]?\u0006 ומסבירים: ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר: כיון\u0004 ש\u0003גוי הוא, לא הוה דייק\u0004 \u0005[היה מדייק],\u0006 שבהיותו גוי לא היה הדבר נוגע לו, ואין לסמוך עליו שדקדק בהם בשעתו. \u0003ור' יוחנן בן ברוקא סבר: כיון דדעתיה לאיגיורי\u0004 \u0005[שדעתו\u0006 היתה \u0005להתגייר],\u0006 \u0003מידק הוה דייק\u0004 \u0005[מדייק היה]\u0006 גם בדברים אלה, שהתעניין בדברים הנוגעים ליהודים ודקדק בהם.","ועוד מסבירים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003\"קצצה\"\u0004 זו שהזכרנו? — \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003כיצד קצצה? אחד מן האחין שנשא אשה שאינה הוגנת לו,\u0004 כלומר, אשה שיש בה פסול משפחה — \u0003באין בני משפחה ומביאין חבית מלאה פירות ושוברין אותה באמצע רחבה,\u0004 כדי לפרסם את הדבר לרבים, \u0003ואומרים: אחינו בית ישראל שמעו! אחינו פלוני נשא אשה שאינה הוגנת לו, ומתייראים אנו שמא יתערב זרעו בזרעינו,\u0004 וכדי להבליט את הדבר \u0003בואו וקחו לכם דוגמא לדורות,\u0004 כלומר, סימן שיהיה לדורות הבאים \u0003שלא יתערב זרעו בזרעינו,\u0004 וכשמתאסף קהל גדול לקחת פירות מתפרסם הדבר. \u0003וזו היא קצצה שהתינוק נאמן להעיד עליה.\u0004",""],["\u0003אלו נערות שיש להן קנס\u0004 חמישים שקל כסף הניתן לאביהן אם נאנסו: \u0003הבא\u0004 באונס \u0003על הממזרת,\u0004 או \u0003על הנתינה\u0004 (בת ממשפחות הגבעונים, שהם נתונים לעבודת המזבח והעדה), או שבא \u0003על הכותית\u0004 (שומרונית), וכן \u0003הבא על הגיורת,\u0004 או \u0003על השבויה,\u0004 או \u0003על השפחה,\u0004 ובתנאי \u0003שנפדו\u0004 (השבויות), \u0003או שנתגיירו\u0004 (הגיורות), או \u0003שנשתחררו\u0004 (השפחות), כשהיו \u0003פחותות מבנות שלש שנים ויום אחד\u0004 ומאז הן בחזקת בתולות שלימות.","וכן \u0003הבא\u0004 באונס \u0003על אחותו,\u0004 או \u0003על אחות אביו,\u0004 או \u0003על אחות אמו,\u0004 או \u0003על אחות אשתו,\u0004 או \u0003על אשת אחיו\u0004 לאחר שנתגרשה מאחיו, או \u0003על אשת אחי אביו\u0004 לאחר שנתגרשה מאחי אביו, או \u0003על הנדה — יש להם קנס,\u0004 כי \u0003אף על פי ש\u0004כל אלה (אחותו וכו') \u0003הן ב\u0004עונש של \u0003הכרת,\u0004 שכל הבא עליהן במזיד חייב כרת, אבל \u0003אין בהן מיתת בית דין,\u0004 והואיל שאין בהן מיתת בית דין לא נפטר האונס מתשלום הקנס.","ותוהים: וכי \u0003הני\u0004 \u0005[אלה]\u0006 ה\u0003נערות,\u0004 ה\u0003פסולות — אית להו\u0004 \u0005[יש להן]\u0006 \u0003קנס,\u0004 ואילו ל\u0003כשירות — לא?!\u0004 שהרי במשנתנו מנה רק נערות שיש בהן פסול מצד זה או אחר! ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אלו נערות פסולות שיש להם קנס.\u0004 כלומר, אין זו רשימה שכוללת את כל הנערות, אלא אפילו מתוך הפסולות יש כאלה שיש להן קנס, והן מנויות ברשימה זו: \u0003הבא על הממזרת ועל הנתינה ועל הכותית\u0004 וכו'.","שנינו במשנה \"נערות\", משמע: \u0003נערה — אין\u0004 \u0005[כן]\u0006 חייב בקנס אם בא עליה, אבל אם בא על ה\u0003קטנה — לא,\u0004 איננו משלם קנס. \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן שאין חייבים בקנס אלא על הנערה ולא על הקטנה?","\u0003אמר רב יהודה אמר רב:\u0004 שיטת \u0003ר' מאיר היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003קטנה, מבת יום אחד ועד שתביא שתי שערות — יש לה מכר,\u0004 כלומר, אביה רשאי למכור אותה לאמה, כאמור בתורה שיש לאב רשות למכור את בתו לאמה. \u0003ואין לה קנס\u0004 אם נאנסה. \u0003ומשתביא שתי שערות ועד שתיבגר — יש לה קנס,\u0004 שבגיל זה היא קרויה נערה, ובתורה נאמר דין אונס ומפתה בנערה דווקא. \u0003ו\u0004אז \u0003אין לה מכר,\u0004 שכיון שהביאה שתי שערות כבר יצאה מרשות אביה ואינה יכולה להימכר עוד, אלו \u0003דברי ר' מאיר. שהיה ר' מאיר אומר\u0004 כלל: \u0003כל מקום שיש מכר,\u0004 כלומר, שיש זכות לאב למכור — \u0003אין קנס, וכל מקום שיש קנס — אין מכר.\u0004","\u0003וחכמים אומרים:\u0004 אינו כן, אלא \u0003קטנה מבת שלש שנים ויום אחד ועד שתיבגר — יש לה קנס.\u0004 ותוהים: האם \u0003קנס — אין\u0004 \u0005[כן],\u0006 \u0003מכר — לא?!\u0004 האם חולקים הם על זה שרשאי האב למכור אותה? ומתקנים, \u0003אימא\u0004 \u0005[אמור]:\u0006"],["\u0003אף קנס במקום מכר,\u0004 כלומר, לא רק שיש לה מכר, אלא מבת שלוש עד הבגרות יש לה גם קנס.","לאחר בירור דיוקי הלשון, פונים לעסוק בגוף המשנה שיש בה רשימה של נערות פסולות, שלכולן חייב לשלם קנס אם אנסן. שואלים: \u0003והני בני קנסא נינהו\u0004 \u0005[ואלה\u0006 הנערות הפסולות הללו \u0005בנות קנס הן]?\u0006 \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003איקרי\u0004 \u0005[אקרא]\u0006 \u0003כאן\u0004 את הכתוב האמור באונס: \u0003\"ולו תהיה לאשה\"\u0004 (דברים כב, כט), שמכאן למדו שמדובר כאן רק ב\u0003אשה הראויה לו,\u0004 ואם אנס אדם אשה האסורה לו — אינו חייב לשאת אותה, ושמא יהא מטעם זה פטור באלה גם מקנס! \u0003אמר ריש לקיש,\u0004 נאמר בכתוב: \"כי ימצא איש נערה\" (דברים כב, כח), ונאמר: \"ונתן האיש השוכב עימה לאבי הנערה\" (דברים כב, כט), והרי זה כאילו חזר על אותו ביטוי שלוש פעמים \u0003\"נערה\", \"נערה\"\u0004 (שבתוך המלה \"הנערה\"), וגם ה־ה' היתירה של \u0003\"הנערה\",\u0004 משלושה אלה אנחנו למדים: \u0003חד לגופיה\u0004 \u0005[אחד\u0006 ללמד \u0005לגופו],\u0006 לעצם הענין, ובנערה כשירה. \u0003וחד לאתויי\u0004 \u0005[ואחד להביא,\u0006 להוסיף\u0005],\u0006 גם \u0003חייבי לאוין,\u0004 שאף אם יש חיוב לאו בביאתו על הנערה הזו ואינו רשאי לשאתה — מכל מקום אינו נפטר מהקנס. \u0003וחד לאתויי\u0004 \u0005[ואחד להביא,\u0006 להוסיף\u0005]\u0006 אפילו נערה שהיא \u0003חייבי כריתות,\u0004 שגם מי שאנסה חייב בקנס.","\u0003רב פפא אמר:\u0004 דבר זה נלמד מדין מפתה האמור בספר שמות, שנאמר שם: \"וכי יפתה איש בתולה\" (שמות כב, טו), וכן: \"כסף ישקול כמוהר הבתולות\" (שמות כב, טז), אם כן יש \u0003\"בתולה\" \"בתולת\" \"הבתולת\": חד לגופיה\u0004 \u0005[אחד לגופו],\u0006 לעצם ההלכה, \u0003וחד לאתויי\u0004 \u0005[ואחד להביא]\u0006 \u0003חייבי לאוין, וחד לאתויי\u0004 \u0005[ואחד להביא]\u0006 \u0003חייבי כריתות.\u0004","ושואלים: \u0003ורב פפא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כריש לקיש\u0004 ומדוע הוצרך ללימוד אחר? ומשיבים: את הריבוי \u0003ההוא\u0004 של \"נערה\" \"הנערה\", \u0003מיבעי ליה\u0004 \u0005[\u0006הוא \u0005צריך]\u0006 \u0003ל\u0004למוד ממנו אותה הלכה שקבע \u0003אביי\u0004 בענין זה. ש\u0003אמר אביי: בא עליה\u0004 על נערה, \u0003ומתה\u0004 לפני שהעמידו האב בדין — \u0003פטור\u0004 מלשלם קנס, \u0003שנאמר: \"ונתן לאבי הנערה\"\u0004 (דברים כב, כט) וממה שאמר \"לאבי הנערה\" ולא \"לאביה\" הכוונה להדגיש: \u0003לאבי נערה, ולא לאבי מתה,\u0004 שאין משלם קנס אלא בחיי הנערה.","ושואלים עוד: \u0003וריש לקיש מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרב פפא,\u0004 ללמוד מהריבוי \"בתולה\" \"בתולות\"? ומשיבים: הריבוי \u0003ההוא מיבעי ליה\u0004 \u0005[צריך,\u0006 נדרש \u0005לו]\u0006 \u0003לגזירה שוה.\u0004 כיצד? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005],\u0006 נאמר במפתה: \u0003\"כסף ישקל כמהר הבתולת\",\u0004 מכאן אנחנו למדים \u0003שיהא זה\u0004 סכום הקנס במפתה \u0003כמוהר הבתולות,\u0004 כלומר, חמישים שקל, כאמור בפרשה של אונס שנותן כשנושאה לאשה. \u0003ומוהר הבתולות כזה.\u0004 מכאן אנחנו למדים הן לענין הסכום המדוייק של הקנס והן לגבי מוהר הבתולות, ואם כן אי אפשר ללמוד מכאן דברים אחרים. ושואלים: \u0003וריש לקיש נמי מיבעי ליה\u0004 \u0005[גם כן\u0006 הרי \u0005צריך לו]\u0006 \u0003ל\u0004למוד מן הפסוק אותו דבר שלמד \u0003אביי,\u0004 שאינו נותן לאבי המתה, \u0003ו\u0004כן \u0003רב פפא נמי מיבעי ליה\u0004 \u0005[גם כן צריך לו]\u0006 את הפסוק שהוא למד ממנו \u0003לגזירה שוה!\u0004","\u0003אלא\u0004 יש לומר כך: \u0003שיתא קראי כתיבי\u0004 \u0005[ששה כתובים נאמרו]\u0006 ומכולם אנו למדים. כיצד? נאמר בפרשיות של אונס ומפתה \u0003\"נערה\" \"נערה\" \"הנערה\" \"בתולה\" \"בתולת\" \"הבתולת\", תרי — לגופייהו\u0004 \u0005[שניים לעצמם],\u0006 כלומר, לצורך משמעות הדברים באונס ובמפתה. \u0003חד\u0004 \u0005[אחד]\u0006 (\"הנערה\") — \u0003ל\u0004מה שאמר \u0003אביי, וחד\u0004 \u0005[ואחד]\u0006 (\"הבתולות\") — \u0003לגזירה שוה\u0004 לגבי מוהר הבתולות. \u0003אייתרו ליה תרי\u0004 \u0005[נשארו להם\u0006 עוד \u0005שני\u0006 כתובים\u0005];\u0006 \u0003חד\u0004 \u0005[אחד] —\u0006 \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003חייבי לאוין, וחד\u0004 \u0005[ואחד] —\u0006 \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003חייבי כריתות.\u0004 וריש לקיש ורב פפא לא נחלקו, אלא מדברי שניהם משלימים מדרש זה.","ומעירים: משנתנו האומרת כי יש קנס לממזרת ולאחותו, באה \u0003לאפוקי מהאי תנא\u0004 \u0005[להוציא מ\u0006דברי \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005],\u0006 נאמר: \u0003\"ולו תהיה לאשה\"\u0004 (דברים כב, כט), \u0003שמעון התימני אומר: אשה שיש בה הויה\u0004 (קידושין). כלומר, דין זה נאמר דווקא באשה שיכול להיות לו בה קידושין. ואם היתה אסורה עליו באיסור כרת, שאז אין קידושין תופסים בה — ממילא לא חלים עליה כל דיני נערה אנוסה. \u0003ר' שמעון בן מנסיא אומר: אשה הראויה לקיימה\u0004 ואינו צריך לגרשה מחמת הפסול שבה.","ותחילה מבררים \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם],\u0006 בין שיטת שמעון התימני ושיטת ר' שמעון בן מנסיא, למעשה? ומשיבים: \u0003אמר ר' זירא:\u0004 לגבי \u0003ממזרת ונתינה\u0004 ושאר איסורי לאוין \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005].\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי דווקא לאשה ש\u0003יש בה הויה,\u0004 וזהו הצד הקובע — \u0003הא נמי\u0004 \u0005[זו גם כן]\u0006 \u0003יש בה הויה.\u0004 שאם מקדש אדם מישראל ממזרת או נתינה, אף שאסור לו לעשות כן, מכל מקום יש בה \"הויה\", והקידושין חלים. ואילו \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003ראויה לקיימה, הא\u0004 \u0005[זו]\u0006 \u0003אינה ראויה לקיימה\u0004 כי הוא חייב לגרש אותה.","ושואלים, \u0003ול\u0004דעת \u0003ר' עקיבא\u0004 ש\u0003אמר: אין קידושין תופסין בחייבי לאוין,\u0004 אם כן \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 שלדעתו אף בממזרת אין הויה! ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 למעשה לגבי \u0003אלמנה\u0004 שנבעלה באונס \u0003לכהן גדול,\u0004 ו\u0003כ\u0004שיטת \u0003ר' סימאי, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003ר' סימאי אומר: מן הכל,\u0004 מכל הוולדות שנולדו בביאות אסורות \u0003עושה ר' עקיבא ממזרין, חוץ\u0004 מוולד הנולד \u0003מ\u0004נישואי \u0003אלמנה לכהן גדול.\u0004 ומדוע? \u0003שהרי אמרה\u0004 ה\u0003תורה:\u0004 \"אלמנה וגרושה... את אלה \u0003לא יקח... ולא יחלל\u0004 זרעו בעמיו\" (ויקרא כא, יד-טו), ומכאן אנו למדים: \u0003חילולין הוא עושה,\u0004 שאם בא על נשים אלו הילדים הנולדים נקראים חללים, אבל \u0003אין\u0004 הוא \u0003עושה\u0004 בכך \u0003ממזרין,\u0004 ומכאן שאף קידושין תופסין בהן ויש בהן הויה.","ושואלים: \u0003ו\u0004מה נאמר \u0003ל\u0004פי דברי \u0003ר' ישבב,\u0004 ש\u0003אמר: בואו ונצוח על עקיבא בן יוסף\u0004 שמרבה ממזרים, מפני \u0003שהיה אומר: כל שאין לו ביאה בישראל,\u0004 שכל ביאה שיש בה איסור (ואף אלמנה לכהן גדול) — \u0003הולד ממזר\u0004 לר' עקיבא. אם כן לשיטה זו \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין האומר שיש בה הויה ובין האומר שחייב בקנס רק בזו שראויה לקיימה? שהרי לדברי ר' ישבב בשיטת ר' עקיבא אפילו אלמנה לכהן גדול אינה בת הויה. ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לגבי"],["\u0003חייבי עשה,\u0004 כגוי \u0003מצרי ואדומי.\u0004 כלומר, אם אנס גיורת מצרית או אדומית בדור הראשון או השני או השלישי לגירותם, שאף לדעת ר' ישבב אין הוולד ממזר, ויש לו הויה, והמחלוקת היא האם במקרה כזה יש קנס, אף כי אסור לו לקיימה.","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004דעת \u0003ר' ישבב, אי לאפוקי מטעמא\u0004 \u0005[אם להוציא מטעמו]\u0006 של \u0003ר' סימאי קאתי שפיר\u0004 \u0005[בא־יפה],\u0006 כלומר, אם דברי ר' ישבב מתייחסים לדברי ר' סימאי, שר' סימאי סבור שמן הכל עושה ר' עקיבא ממזרים חוץ מאלמנה לכהן גדול, ור' ישבב חולק על דבריו ולדבריו אפשר לפרש שלדעתו ר' עקיבא סבור שיש ממזרות (ואין הויה) אפילו בחיוב לאוין של כהונה אף שבחייבי עשה אין ממזרים, ואם כן יש לומר שנחלקו שמעון התימני ור' שמעון בן מנסיא בחייבי עשה. \u0003אלא אי טעמא דנפשיה קאמר\u0004 \u0005[אם טעם של עצמו הוא אומר]\u0006 ואין דבריו מתייחסים לדברי ר' סימאי, הרי משמעות דבריו היא כללית יותר ש\u0003כל שאין לו ביאה בישראל הולד ממזר\u0004 בכל מקום שיש איסור כלשהו בביאה, \u0003ו\u0004אם כן — בכלל זה \u0003אפילו חייבי עשה\u0004 (כגיורת מצרית או אדומית). ולשיטה זו, לדעת ר' עקיבא, בכל מקום שיש איסור ביאה, אין בו דין הויה וקידושין, ואם כן \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 בין שמעון התימני ור' שמעון בן מנסיא\u0005]?\u0006","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 למעשה לגבי \u0003בעולה\u0004 שאנס אותה \u0003כהן גדול.\u0004 ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה],\u0006 הרי גם בזו יש איסור עשה (שהרי הוא, הכהן הגדול, עובר על מה שאמרה התורה \"כי אם בתולה מעמיו יקח אשה\") ואם אומרים שלר' עקיבא אין קידושין תופסים באיסורי עשה, מה שונה איסור זה? ומשיבים: \u0003דהוה ליה\u0004 \u0005[שהרי זהו]\u0006 \u0003עשה שאינו שוה בכל,\u0004 כי מאחר שאיסור עשה זה הוא רק בכהן הגדול ולא בכל ישראל, אם כן יש בו שני צדדים להקל; הראשון, שהוא רק איסור עשה ולא לאו, והשני, שאינו שוה בכל, ובזה אפילו ר' ישבב מודה שר' עקיבא אינו עושה ממזרים, והנישואין תופסים, כלומר, שיש בהם הויה, אך האשה אינה ראויה לקיימה, ובזה החילוק בין ר' שמעון בן מנסיא ושמעון התימני.","\u0003אמר רב חסדא: הכל מודים בבא\u0004 באונס \u0003על הנדה שמשלם קנס.\u0004 והטעם: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שמשלם קנס רק אם \u0003יש בה הויה — הא נמי\u0004 \u0005[זו גם כן]\u0006 \u0003יש בה הויה,\u0004 שהלא אם מקדש את הנדה, הקידושין תופסים. \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שמשלם קנס רק אם היא אשה \u0003ראויה לקיימה — הא נמי\u0004 \u0005[זו גם כן]\u0006 \u0003ראויה לקיימה,\u0004 שהרי כל אשת איש היא נדה מזמן לזמן ונישואיה אינם בטלים.","מעירים, שמשנתנו שמחייבת קנס את הבא על אחותו, באה \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' נחוניא בן הקנה. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' נחוניא בן הקנה היה עושה את יום הכפורים כשבת ל\u0004דין \u0003תשלומין.\u0004 כיצד? \u0003מה\u0004 כאשר חילל \u0003שבת\u0004 ותוך כדי כך גרם נזק לאחר — הריהו \u0003מתחייב בנפשו ופטור מן התשלומין,\u0004 לפי הכלל שאדם אינו יכול להידון בשני עונשים, ונידון בעונש החמור יותר, שהוא בענייננו, עונש מוות, \u0003אף\u0004 המחלל \u0003יום הכפורים\u0004 הריהו \u0003מתחייב בנפשו,\u0004 כיון שיש כאן איסור כרת, שהוא עונש מוות בידי שמים \u0003ו\u0004לכן \u0003פטור מן התשלומין.\u0004","ולדברי ר' נחוניא, הבא על אחותו צריך להיות פטור מן הקנס, שהרי הוא מתחייב בעונש כרת, ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' נחוניא בן הקנה? אמר אביי: נאמר \"אסון\" בידי אדם\u0004 (\"ואם אסון יהיה ונתתה נפש תחת נפש\". שמות כא, כג), \u0003ונאמר \"אסון\" בידי שמים\u0004 (\"לא ירד בני עמכם... וקראהו אסון בדרך\". בראשית מב, לח), \u0003מה \"אסון\" האמור בידי אדם\u0004 אם הרג אדם והתחייב מיתה \u0003פטור מן התשלומין, אף \"אסון\" האמור בידי שמים — פטור מן התשלומין.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אדא בר אהבה: ממאי\u0004 \u0005[ממה]\u0006 יודע אתה \u0003דכי קא מזהר להו\u0004 \u0005[שכאשר מזהיר אותם]\u0006 \u0003יעקב לבניה\u0004 \u0005[את בניו]\u0006 \u0003על צינים ופחים\u0004 (צינה וחום) ש\u0003בידי שמים נינהו\u0004 \u0005[הם]\u0006 אזהרותיו? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003על\u0004 דברים כגון \u0003אריא וגנבי\u0004 \u0005[אריה וגנבים]\u0006 שאסונות ש\u0003בידי אדם נינהו\u0004 \u0005[הם]\u0006 הוא מזהירם?! ודוחים: דבר זה אי אפשר לומר, כי \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003יעקב אהא אזהר\u0004 \u0005[על זה,\u0006 על אסונות שבידי אדם, \u0005הזהיר]\u0006 ואילו \u0003אהא\u0004 \u0005[על זה],\u0006 על אסונות שבידי שמים, \u0003לא אזהר\u0004 \u0005[הזהיר]?\u0006 ודאי ש\u0003יעקב על כל מילי\u0004 \u0005[דבר]\u0006 \u0003אזהר\u0004 \u0005[הזהיר],\u0006 שהרי חשש מפני כל אסון שהוא, ולא מאסון מסוג מסויים דווקא.","לגופו של דבר שואלים: \u0003ו\u0004כי \u0003צינים פחים בידי שמים נינהו\u0004 \u0005[הם]?\u0006 \u0003והתניא\u0004 \u0005[והרי\u0006 \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003הכל בידי שמים חוץ מצינים פחים, שנאמר: \"צנים פחים בדרך עקש שומר נפשו ירחק מהם\"\u0004 (משלי כב, ה), משמע שצינים ופחים הם מפגעים שבידי אדם ובידו להימנע מהם! \u0003ותו\u0004 \u0005[ועוד]\u0006 האם \u0003אריא וגנבי\u0004 \u0005[אריה וגנבים]\u0006 נזקים שבאים רק \u0003בידי אדם נינהו\u0004 \u0005[הם]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יוסף וכן תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 בברייתא: \u0003מיום שחרב בית המקדש, אף על פי שבטלו סנהדרין — ארבע מיתות\u0004 בית דין \u0003לא בטלו.\u0004 ותוהים על הלשון: \u0003לא בטלו?!\u0004 איך אפשר לומר שארבע מיתות בית דין לא בטלו? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בטלו להו\u0004 \u0005[להם],\u0006 שודאי אין בימינו סנהדרין ומיתות בית דין! \u0003אלא\u0004 כך צריך לומר:"],["\u0003דין\u0004 (עונש) \u0003ארבע מיתות לא בטלו.\u0004 כיצד? \u0003מי שנתחייב סקילה,\u0004 כיון שאין בית דין שיענישנו בסקילה כדין, הריהו נידון מידי שמים בעונש מעין סקילה — \u0003או נופל מן הגג, או חיה דורסתו.\u0004 שכך דין הנסקלים שתחילה מפילים אותם ממקום גבוה, ואחר כך משליכים עליהם אבנים. \u0003ומי שנתחייב שריפה — או נופל\u0004 ונשרף \u0003בדליקה, או נחש מכישו,\u0004 וארס הנחש גורם לו יסורי מיתה מעין אלה של שריפה. \u0003ומי שנתחייב הריגה\u0004 בסייף — \u0003או נמסר למלכות\u0004 שהורגת בסייף, \u0003או ליסטים\u0004 (שודדים) \u0003באין עליו\u0004 והורגים אותו. \u0003ומי שנתחייב חנק — או טובע בנהר\u0004 ונחנק בטביעתו, \u0003או מת בסרונכי\u0004 (במחלת האסכרה). ובכל אופן רואים שצינים ופחים הם נזקים שבידי אדם ואריה וגנבים הם בידי שמים, ושלא כפי שהובן בתחילה?! \u0003אלא, איפוך\u0004 \u0005[הפוך]\u0006 את סדר הדברים: \u0003אריא וגנבי\u0004 \u0005[אריה וגנבים]\u0006 הם נזקים שבאים \u0003בידי שמים,\u0004 ואילו \u0003צינים ופחים\u0004 הם \u0003בידי אדם.\u0004 עד כאן הבאנו שיטה אחת להסברת טעמו של ר' נחוניא בן הקנה, שאמר שכל העושה מעשה ביום הכיפורים שבעטיו הוא מתחייב שני עונשים, כרת וממון, אף בכך (כמו במתחייב מיתת בית־דין וממון) אין דנים אותו אלא בחמור שביניהם ואינו משלם.","ואילו \u0003רבא אמר: טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' נחוניא בן הקנה מהכא\u0004 \u0005[מכאן]:\u0006 נאמר שהנותן מזרעו למולך חייב סקילה, \u0003\"ואם העלם יעלימו עם הארץ את עיניהם מן האיש ההוא בתתו מזרעו למלך\u0004 לבלתי המית אותו. \u0003ושמתי אני את פני באיש ההוא ובמשפחתו והכרתי אתו\"\u0004 (ויקרא כ, ד-ה), \u0003אמרה\u0004 ה\u0003תורה\u0004 בפסוק זה: \u0003כרת שלי\u0004 הרי הוא \u0003כמיתה שלכם,\u0004 מיתת בית־דין\u0003.\u0004 ומכאן נלמד גם לענין אחר: \u0003מה מיתה שלכם,\u0004 מי שנתחייב בה — \u0003פטור מן התשלומין. אף כרת שלי,\u0004 מי שנתחייב בו — \u0003פטור מן התשלומין.\u0004","ושואלים: \u0003מאי איכא\u0004 \u0005[מה יש\u0006 הבדל\u0005]\u0006 הלכה למעשה \u0003בין רבא לאביי\u0004 בפירוש מקור דברי ר' נחוניא בן הקנה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 בדין \u0003זר\u0004 (מי שאינו כהן) \u0003שאכל תרומה\u0004 במזיד, שחייב מיתה בידי שמים ולא כרת — \u0003ל\u0004דעת \u0003אביי פטור\u0004 מלשלם עבורה לכהן, משום שזר שאכל תרומה עונשו מיתה בידי שמים, ולדעת אביי כל עונשי מיתה בידי שמים נחשבים כעונשים בידי אדם, וכל שנתחייב בכל סוג של מיתה בידי שמים, הרי זה כחייב מיתה בידי אדם, ופטור מן התשלומין. \u0003ולרבא\u0004 הסבור שדין זה נלמד מדין כרת המפורש בכתוב, כיון שבזר שאכל תרומה אין עונש כרת, יהיה \u0003חייב\u0004 לשלם על מה שאכל.","ושואלים: \u0003ו\u0004האם אמנם \u0003ל\u0004דעת \u0003אביי\u0004 זר שאכל תרומה \u0003פטור?! והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא: מודה ר' נחוניא בן הקנה ב\u0004מי ש\u0003גונב חלבו של חבירו ואכלו, שהוא חייב\u0004 לשלם לו עבור החלב, למרות שחייב כרת, ומדוע — \u0003שכבר נתחייב בגניבה קודם שבא לידי איסור חלב. אלמא\u0004 \u0005[מכאן]\u0006 \u0003דמעידנא דאגביה קנייה\u0004 \u0005[שמזמן שהגביהו\u0006 את החלב הזה כדי לגונבו \u0005קנה אותו],\u0006 שיש לו בו קנין כדי לחייבו באחריות עליו, ומתחייב בתשלומים. אבל \u0003מתחייב בנפשו לא הוה\u0004 \u0005[איננו]\u0006 \u0003עד דאכיל ליה\u0004 \u0005[ש\u0006הוא \u0005אוכל אותו],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בזר שאכל תרומה, הלא \u0003בעידנא דאגביה, קנייה\u0004 \u0005[בזמן שהגביהה, קנה אותה]\u0006 והריהו מתחייב בתשלום עבורה, ואולם \u0003מתחייב בנפשו לא הוי\u0004 \u0005[איננו]\u0006 \u0003עד דאכיל ליה\u0004 \u0005[ש\u0006הוא \u0005אוכל אותה]!\u0006 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003כגון שתחב לו חבירו\u0004 את התרומה \u0003לתוך פיו,\u0004 שהקונה לא עשה בה פעולת הגבהה כלל ולא קנאה, וחיובי התשלומים והמיתה באים כאחת.","ומקשים: \u0003סוף סוף כיון דלעסיה\u0004 \u0005[שלעסה]\u0006 את התרומה הזו בפיו \u0003קנייה\u0004 \u0005[קנה אותה]\u0006 ונתחייב בתשלום, אבל \u0003מתחייב בנפשו לא הוי\u0004 \u0005[איננו]\u0006 \u0003עד דבלעה\u0004 \u0005[ש\u0006הוא \u0005בולע אותה],\u0006 וכיון ששתי העבירות לא בוצעו באותו זמן עצמו, יהא חייב גם בתשלומים! ומשיבים: צריך לומר שמדובר \u0003כגון שתחב לו לתוך בית הבליעה,\u0004 שלא היתה התרומה כלל בתוך פיו ובזמן הבליעה עבירות הגניבה והאכילה נעשו כאחת. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דמצי לאהדורה\u0004 \u0005[אם\u0006 זה באופן \u0005ש\u0006הוא \u0005יכול להחזירה],\u0006 להוציא ולהקיא את התרומה בלי שתיפסד — \u0003ניהדר\u0004 \u0005[שיחזיר]\u0006 אותה כשהיא עדיין בבית הבליעה ולא יתחייב בתשלומים, וכיון שלא הוציא מתחייב בתשלומים קודם שיתחייב בעונש מיתה. \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא מצי לאהדורה\u0004 \u0005[יכול להחזירה]\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב\u0004 מיתה? והרי אנוס הוא, שהרי הוא לא עשה את המעשה אלא החבר הוא שתחב בגרונו! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא כגון \u0003דמצי לאהדורה\u0004 \u0005[ש\u0006הוא \u0005יכול להחזירה]\u0006 \u0003על ידי הדחק,\u0004 שאם יעשה מאמץ, יוכל להוציא את התרומה.","\u0003רב פפא אמר: כגון שתחב לו חבירו משקין של תרומה לתוך פיו,\u0004 שאז, ברגע שנכנס הדבר לתוך פיו, נמאס משתיה נוספת, ונחשב שמעשה הקנייה וגם הנאתו היו בבת אחת. \u0003רב אשי אמר:\u0004 אפשר לפרש זאת \u0003בזר שאכל תרומה משלו,\u0004 שהיתה שייכת לו, כגון שזר זה ירש תרומה מקרובו הכהן, או קנה מכהן את הזכות הקניינית שיש בתרומה, שלא היה כאן איסור גניבה, אבל יש איסור מיתה, על אכילתה, ואף באותה שעה שהוא אוכל תרומה משלו,"],["\u0003וקרע שיראין\u0004 (משי) \u0003של חבירו.\u0004 והשאלה היא, האם ברגע זה כשהוא מתחייב מיתה בידי שמים על אכילת התרומה הוא גם נפטר מחיובי ממון שנתחייב באותו רגע עצמו.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של הלכה זו שהזכרנו \u0003אמר רב חסדא:\u0004 אף שאמר ר' נחוניא בן הקנה כי העושה מעשה המחייבו בכרת ובתשלומים נפטר מן התשלומים מדין קים ליה בדרבה מיניה, מכל מקום \u0003מודה ר' נחוניא בן הקנה בגונב חלבו של חבירו ואכלו שהוא חייב\u0004 בתשלומים, מפני \u0003שכבר נתחייב בגנבה קודם שיבא לידי איסור חלב.\u0004 ומעירים: \u0003לימא פליגא\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005חלוקה]\u0006 הלכה זו על שיטתו של \u0003ר' אבין.\u0004 ש\u0003אמר ר' אבין: הזורק חץ\u0004 בשבת \u0003מתחילת ארבע\u0004 אמות \u0003לסוף ארבע\u0004 אמות ברשות הרבים, ועשה איפוא מלאכה שחייבים עליה מיתת בית־דין, \u0003וקרע\u0004 החץ \u0003שיראין בהליכתו\u0004 — הריהו \u0003פטור\u0004 מתשלום על קריעת השיראין, משום שהתחייב בעונש החמור יותר על חילול שבת, למרות שקריעת השיראין נעשתה לפני שנגמרה המלאכה שחייבים עליה בשבת, שהרי עדיין לא נח החץ. והטעם הוא: \u0003שעקירה צורך הנחה היא,\u0004 שכיון שמלאכה זו של טלטול בשבת מוגדרת על ידי עקירתו של החפץ ממקומו והנחתו במקום אחר, הרי משעה שירה את החץ, גם כשמהלך החץ באוויר, הרי הוא חלק ממהלך ביצוע אותה העבירה עצמה של חילול שבת במזיד, שמתחייב עליה בנפשו. ואם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לעניין הגונב חלב ואכלו, נאמר כי ה\u0003הגבהה\u0004 של החלב שנעשתה בזמן הגניבה, \u0003צורך אכילה היא,\u0004 ואם כן אפשר לומר שהיתה כאן פעולה אחת נמשכת ולא שתי פעולות נפרדות, וממילא יפטר מן התשלומים!","ודוחים: \u0003הכי השתא\u0004 \u0005[איך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם],\u0006 בזריקת החץ, \u0003אי אפשר להנחה בלא עקירה,\u0004 שאין ההנחה נחשבת לכשעצמה למלאכה בלא שתהיה עקירה קודם לכן, ואם כן העקירה וההנחה הן יחידה אחת. ואולם \u0003הכא\u0004 \u0005[כאן],\u0006 בגנב חלב ואכלו, הלא \u0003אפשר לאכילה בלא הגבהה,\u0004 שלמרות שבדרך כלל מגביהים לפני האכילה אבל אין הדבר מחוייב מעצמו, \u0003דאי בעי, גחין ואכיל\u0004 \u0005[שאם\u0006 היה \u0005רוצה,\u0006 היה \u0005מתכופף ואוכל]\u0006 בלי להגביה. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש לחלק באופן אחר: \u0003התם\u0004 \u0005[שם]\u0006 ביריית החץ \u0003אי בעי לאהדורה\u0004 \u0005[אם\u0006 היה \u0005רוצה להחזירו,\u0006 את החץ\u0005]\u0006 לאחר שירה אותו, \u0003לא מצי מהדר לה\u0004 \u0005[\u0006היה \u0005יכול להחזירו],\u0006 ולפיכך העקירה וההנחה הן יחידה אחת. ואולם \u0003הכא\u0004 \u0005[כאן] —\u0006 \u0003מצי מהדר לה\u0004 \u0005[\u0006היה \u0005יכול להחזירו],\u0006 את החלב לאחר שהגביהו.","ושואלים: \u0003מאי איכא\u0004 \u0005[מה יש,\u0006 מה ההבדל\u0005]\u0006 \u0003בין האי לישנא\u0004 \u0005[לשון זו]\u0006 \u0003להאי לישנא\u0004 \u0005[ללשון זו]?\u0006 כלומר, מה ההבדל למעשה אם מסבירים באופן זה או אחר את ההבדל בין אכילת חלב של חבירו ליריית חץ בשבת וגרימת נזק. ואומרים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 למעשה לגבי \u0003המעביר סכין ברשות הרבים וקרע שיראין בהליכתו. להך לישנא דאמרת\u0004 \u0005[ל\u0006פי \u0005אותה לשון שאמרת]\u0006 ש\u0003אי אפשר להנחה בלא עקירה\u0004 — אם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 כשמעביר את הסכין \u0003אי אפשר\u0004 מבחינת ההגדרה ההלכתית \u0003להנחה בלא עקירה,\u0004 ששני החלקים הללו קשורים זה בזה ולפיכך בנזק הנגרם על ידי הסכין בהליכתו יהיה פטור. אבל \u0003להך לישנא דאמרת\u0004 \u0005[לפי אותה לשון שאמרת]\u0006 שפטור ביריית חץ מן הנזק שגרם לפי ש\u0003לא מצי מהדר לה\u0004 \u0005[\u0006ש\u0005איננו יכול להחזירו,\u0006 את החץ\u0005],\u0006 \u0003הכא מצי מהדר לה\u0004 \u0005[כאן יכול להחזירה,\u0006 את הסכין\u0005],\u0006 ולפי הבחנה זו אין הדבר דומה ליריית חץ ויהיה חייב על הנזק הנגרם מהסכין.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של הלכה זו ש\u0003אמר ר' אבין: הזורק חץ מתחלת ארבע לסוף ארבע וקרע שיראין בהליכתו — פטור\u0004 מלשלם לבעליהם, \u0003שעקירה צורך הנחה היא, מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב ביבי בר אביי\u0004 ממה ששנינו: \u0003הגונב כיס\u0004 (ארנק) \u0003בשבת — חייב\u0004 לשלם את הגניבה, מפני \u0003שכבר נתחייב בגניבה קודם שיבא לידי איסור סקילה.\u0004 שכן, כשהגביה את החפץ התחייב משום גניבה, אבל משום חילול שבת של איסור טלטול מרשות לרשות, לא התחייב עד שהוציאו לרשות הרבים, ואם כן קדם איסור גניבה ונתחייב עליו. ואם לא הגביה את הכיס אלא \u0003היה מגרר\u0004 (גורר) אותו על גבי הארץ \u0003ויוצא\u0004 לרשות הרבים, \u0003מגרר ויוצא,\u0004 ואז מתחייב משום גניבה רק בשעה שהוציא את הכיס מרשות בעליו לרשות הרבים, ובאותה שעה חל גם חיוב מלאכת הוצאה לענין שבת, ולכן \u0003פטור, שהרי איסור שבת וגניבה באין כאחד.\u0004","ויש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 נאמר כך, שאם הגביהו ברשות הבעלים וקנאו, חייב? \u0003הכא נמי לימא\u0004 \u0005[כאן גם כן נאמר]\u0006 \u0003הגבהה\u0004 שהיא העקירה שהיתה במלאכה זו, הלא \u0003צורך הוצאה היא\u0004 שלא ייתכן איסור הוצאה בשבת בלי העקירה, שבמקרה זה היא הגבהת החפץ, ואם כן עבירת הגניבה נעשתה תוך כדי מלאכת שבת! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003כגון שהגביהו\u0004 את הכיס לא כדי להוציאו מרשות הבעלים לרשות הרבים, אלא \u0003על מנת להצניעו\u0004 (להחביאו) במקומו באותה רשות, \u0003ונמלך עליו\u0004 אחר כך \u0003והוציאו,\u0004 שההגבהה לא היתה לצורך הוצאה ולפיכך חייב על הגניבה.","ומקשים: \u0003וכי האי גוונא מי\u0004 \u0005[וכגון זה,\u0006 כאשר שינה את דעתו באמצע \u0005האם]\u0006 הוא \u0003חייב\u0004 משום הוצאה בשבת? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב סימון אמר ר' אמי אמר ר' יוחנן: המפנה חפצים מזוית לזוית\u0004 בביתו בשבת, \u0003ונמלך עליהם\u0004 לאחר שעקרם \u0003והוציאן\u0004 לרשות הרבים — \u0003פטור,\u0004 מפני \u0003שלא היתה עקירה משעה ראשונה לכך,\u0004 לשם הוצאה מרשות לרשות. ואף כאן נאמר, שכיון שלא התכוון להגביה את הכיס הזה כדי להוציאו, אין כאן חיוב שבת כלל!","ומתקנים: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 שהגביהו \u0003על מנת להצניעו, אלא אימא\u0004 \u0005[אמור]\u0006 שהגביהו \u0003על מנת להוציאו,\u0004 ואף־על־פי־כן אין הדברים שווים, כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כשעמד\u0004 בתוך החצר לפני שהוציא את הכיס. שהיתה פה הגבהה אחרת של גניבה ולא של הוצאה בשבת, שכשעמד באותו רשות התבטלה אותה עקירה לגבי איסור הוצאה. אך כבר התחייב בגניבה עם עקירת (הגבהת) החפץ בראשונה וכשעקר שוב ממקומו התחילה עקירה אחרת, ורק כשהוציא את החפץ לרשות הרבים חייב עליה משום מלאכת הוצאה בשבת.","ושואלים: \u0003עמד למאי\u0004 \u0005[ל\u0006שם \u0005מה]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שעמד כדי \u0003לכתף,\u0004 ליישר את המשא על כתיפו — הלא \u0003אורחיה הוא\u0004 \u0005[דרכו היא],\u0006 ועמידה כזו איננה נחשבת הפסקה, אלא המשך של פעולת ההוצאה! \u0003אלא\u0004 צריך אתה לפרש שמדובר \u0003בעומד לפוש\u0004 (לנוח), וכשעקר ממקומו ויצא, היתה זו תחילת פעולה אחרת. ונדייק מכאן: \u0003אבל\u0004 אם עמד \u0003לכתף מאי\u0004 \u0005[מה]\u0006 יהיה הדין לשיטה זו?"],["\u0003פטור.\u0004 אולם אם אתה אומר כן, \u0003אדתני\u0004 \u0005[עד\u0006 שהוא \u0005שונה]\u0006 בהמשך הברייתא \u0003\"היה מגרר ויוצא מגרר ויוצא פטור\", נפלוג וניתני בדידה\u0004 \u0005[שיחלק וישנה בתוכה]\u0006 חלוקה פנימית דקה יותר, והיא: \u0003במה דברים אמורים\u0004 שכשעומד הרי זה כהפסקה ואין קנין החפץ ומלאכת שבת נעשים כאחת ולכן חייב בתשלום — \u0003בעומד לפוש, אבל\u0004 העומד \u0003לכתף — פטור.\u0004","\u0003אלא\u0004 חוזרים מהתירוץ האחרון ואומרים: \u0003הא מני\u0004 \u0005[\u0006הלכה \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003בן עזאי היא,\u0004 ש\u0003אמר: מהלך כעומד דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 וכאשר אדם מהלך תמיד, הריהו עומד בכל פעם, ומפסיק על ידי כך בין פעולת העקירה וההנחה, ונמצא שעל העקירה הראשונה אינו מתחייב משום שבת. ושואלים: אם כן לשיטה זו \u0003אבל זורק\u0004 את החפץ לרשות אחרת \u0003מאי\u0004 \u0005[מה]\u0006 יהיה דינו — \u0003פטור\u0004 מתשלומים, שעקירה צורך הוצאה היתה ונמצא מתחייב בגניבת החפץ ומוציא מרשות אחת לחברתה כאחת — אם כן \u0003ניפלוג וניתני בדידה\u0004 \u0005[שיחלוק וישנה בה עצמה]:\u0006 \u0003במה דברים אמורים\u0004 שחייב משום גניבה — \u0003במהלך,\u0004 שמפסיק את מלאכת ההוצאה, ואין שתי הפעולות באות כאחת, \u0003אבל זורק — פטור\u0004 מן התשלומים, שכן חיוב שבת וחיובו בגניבה נעשו כאחת!","ומשיבים: אמנם דין זה נכון הוא לשיטה זו, אלא ש\u0003מגרר ויוצא איצטריכא ליה\u0004 \u0005[הוצרך לו],\u0006 שיש בכך חידוש אחר, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003אין דרך הוצאה בכך,\u0004 שאין זו הדרך הרגילה להוציא על ידי גרירה, ומאחר שעשה מלאכה שלא כדרכה, שלא באופן שרגילים לעשותה, לא תיחשב איפוא כמלאכה גמורה ואינו חייב עליה מיתה. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם זו דרך הוצאה.","\u0003ו\u0004מבררים: \u0003במאי\u0004 \u0005[ובמה]\u0006 מדובר פה? \u0003אי ברברבי\u0004 \u0005[אם ב\u0006משאות \u0005גדולים,\u0006 בכיס גדול\u0005]\u0006 — הרי בודאי \u0003אורחיה\u0004 \u0005[דרכו]\u0006 \u0003הוא\u0004 להוציאו בגרירה ואין חידוש בדבר. \u0003אי בזוטרי\u0004 \u0005[אם בקטנים] —\u0006 ודאי \u0003לאו אורחיה\u0004 \u0005[לא דרכו]\u0006 \u0003הוא,\u0004 ואם הוציא בגרירה, ודאי אינו חייב על כך. \u0003אלא\u0004 מדובר כאן \u0003במיצעי\u0004 \u0005[באמצעיים,\u0006 בממוצעים\u0005],\u0006 והחידוש הוא, שלמרות שלא תמיד מוציאים אותם כך, כיון שפעמים עושים כן, אנו אומרים שדרך הוצאה בכך, וחייב בהוצאתן משום חילול שבת ופטור מגניבה.","ועוד מבררים באותה הלכה: \u0003ודאפקיה להיכא\u0004 \u0005[ושהוציאו,\u0006 את הכיס, \u0005להיכן]?\u0006 \u0003אי דאפקיה\u0004 \u0005[אם שהוציאו]\u0006 מרשות הבעלים \u0003לרשות הרבים\u0004 — אמנם \u0003איסור שבת איכא\u0004 \u0005[יש\u0006 כאן\u0005],\u0006 שהרי הוציא חפץ מרשות היחיד לרשות הרבים, אבל \u0003איסור גניבה ליכא\u0004 \u0005[אין],\u0006 שהרי הוציא אותו לרשות הרבים, ואין אדם קונה חפץ במשיכה לרשות הרבים, ואם כן עדיין לא נקנה לו החפץ ולא חל איסור גניבה. \u0003אי דאפקיה\u0004 \u0005[אם שהוציאו,\u0006 את הכיס\u0005]\u0006 מרשות יחיד אחת \u0003לרשות היחיד\u0004 של עצמו — \u0003איסור גניבה איכא\u0004 \u0005[יש],\u0006 שכן חצירו קונה לו, אבל \u0003איסור שבת ליכא\u0004 \u0005[אין],\u0006 שכן אין איסור הוצאה מן התורה מרשות היחיד אלא לרשות הרבים! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דאפקיה\u0004 \u0005[שהוציאו]\u0006 \u0003לצידי רשות הרבים.\u0004 שסמוך לרשות הרבים יש שטח השייך לבתים הסמוכים ואינו נבדל מהם במחיצה גבוהה אלא ביתידות קטנות וכדומה.","\u0003ו\u0004שואלים: \u0003כמאן\u0004 \u0005[וכ\u0006דעת \u0005מי]\u0006 אומרים הסבר זה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004שיטת \u0003ר' אליעזר\u0004 ש\u0003אמר\u0004 ש\u0003צידי רשות הרבים כרשות הרבים דמו\u0004 \u0005[\u0006הם \u0005נחשבים] —\u0006 הרי \u0003איסור שבת איכא\u0004 \u0005[יש\u0006 כאן\u0005]\u0006 בהוצאה לצידי רשות הרבים, אבל \u0003איסור גניבה ליכא\u0004 \u0005[אין],\u0006 שהרי בהוצאה לרשות הרבים אין החפץ נקנה לו! \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהוא \u0003כ\u0004שיטת \u0003רבנן דאמרי\u0004 \u0005[חכמים\u0006 \u0005שאומרים]\u0006 ש\u0003צידי רשות הרבים לאו\u0004 \u0005[לא]\u0006 \u0003כרשות הרבים דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 אם כן \u0003איסור גניבה איכא\u0004 \u0005[יש],\u0006 \u0003איסור שבת ליכא\u0004 \u0005[אין]!\u0006","ומשיבים: \u0003לעולם\u0004 תפרש שהוא \u0003כר' אליעזר, וכי\u0004 \u0005[וכאשר]\u0006 \u0003אמר ר' אליעזר\u0004 כי \u0003צידי רשות הרבים כרשות הרבים דמו\u0004 \u0005[\u0006הם \u0005נחשבים] —\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003לענין חיובא\u0004 \u0005[חיוב]\u0006 \u0003שבת\u0004 בלבד, וטעמו של דבר — \u0003דזימנין דדחקי\u0004 \u0005[שפעמים שדוחקים]\u0006 \u0003רבים ועיילי להתם\u0004 \u0005[ונכנסים לשם],\u0006 וכיון שהמקום פתוח לרשות הרבים, והרבים לפעמים נמצאים בו — נחשב הוא כרשות הרבים לענין שבת. \u0003אבל לענין מיקנא\u0004 \u0005[קנין\u0006 בו\u0005]\u0006 — \u0003קני\u0004 \u0005[\u0006הוא \u0005קונה].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003דהא לא שכיחי\u0004 \u0005[שהרי אין מצויים]\u0006 שם \u0003רבים,\u0004 ובמקום שאין רבים מצויים בו, יכול לקנות.","\u0003רב אשי אמר:\u0004 אפשר לפרש באופן אחר, שמה שאמרנו שמגרר ויוצא פטור, מדובר באופן שאכן לא הגביהו ברשות היחיד, אלא שגררו מרשות היחיד לרשות הרבים, ו\u0003כגון שצירף\u0004 (חיבר) \u0003ידו\u0004 השניה \u0003למטה משלשה\u0004 טפחים מן הקרקע \u0003וקיבלו\u0004 (קיבל את הכיס) מן היד הראשונה מיד כשהוציאו לרשות הרבים. וכשיטת \u0003רבא,\u0004 ש\u0003אמר רבא: ידו של אדם חשובה לו\u0004 לענין הנחה בשבת \u0003כ\u0004מקום שיש בו \u0003ארבעה על ארבעה\u0004 טפחים, ולכן נחשב הדבר כהנחה ברשות הרבים לענין שבת, וכיון שהניח את הכיס בידו, הרי ידו נחשבת עבורו כרשותו הפרטית לענין קנין, ונקנתה לו באותה שעה גם הגניבה. \u0003רב אחא מתני הכי\u0004 \u0005[היה שונה\u0006 את כל הענין הזה \u0005כך]\u0006 כפי הנוסח שלמדנו.","\u0003רבינא מתני\u0004 \u0005[היה שונה]\u0006 בנוסח אחר: \u0003לעולם\u0004 תפרש \u0003דאפקיה\u0004 \u0005[שהוציאו,\u0006 את החפץ\u0005],\u0006 \u0003לרשות הרבים, וברשות הרבים נמי\u0004 \u0005[גם כן]\u0006 \u0003קנה\u0004 את הגניבה לעצמו על ידי שהוציאו מרשות הבעלים, ואין צורך שיביאנה לרשות עצמו. ומעירים: \u0003ותרוייהו בדיוקא דהא מתניתין קמיפלגי\u0004 \u0005[ושניהם,\u0006 רב אחא ורבינא, \u0005בדיוק\u0006 הדברים \u0005של משנה זו\u0006 הם \u0005חלוקים].\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 מי שגנב בעל חיים מחבירו, ו\u0003היה מושכו ויוצא ומת ברשות בעלים — פטור\u0004 הגנב מלשלם, שהרי עדיין לא נקנתה לו הגניבה, ואינו חייב על מיתתה שאירעה באונס. \u0003הגביהו או שהוציאו מרשות בעלים,\u0004 שאז נקנתה לו הגניבה \u0003ומת — חייב\u0004 לשלם, שהרי ברשות הגנב מתה.","ובכך נחלקו: \u0003רבינא דייק מרישא\u0004 \u0005[מראשה,\u0006 מתחילתה של המשנה\u0005],\u0006 ו\u0003רב אחא דייק מסיפא\u0004 \u0005[מסופה].\u0006 כיצד? \u0003רבינא דייק מרישא\u0004 \u0005[מראשה],\u0006 ששנינו: \u0003היה מושכו ויוצא ומת ברשות בעלים — פטור.\u0004 ודייק כך: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003מת ברשות\u0004 ה\u0003בעלים, הא\u0004 \u0005[הרי]\u0006 אם \u0003הוציאו מרשות\u0004 ה\u0003בעלים ומת — חייב,\u0004 לפי שעצם הוצאתו מרשות הבעלים, ואפילו הוציאו לרשות הרבים, מקנה לגנב את החפץ, ומתחייב עליו. \u0003רב אחא דייק מסיפא\u0004 \u0005[מסופה],\u0006 ששנינו: \u0003הגביהו או שהוציאו,\u0004 ונדייק: \u0003הוצאה דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003הגבהה, מה הגבהה\u0004 היא מעשה קנין שעל ידה \u0003אתי לרשותיה\u0004 \u0005[הגיעה\u0006 הגניבה \u0005לרשותו],\u0006 \u0003אף הוצאה נמי דאתי לרשותיה\u0004 \u0005[גם כן\u0006 כ\u0005שהגיעה לרשותו]\u0006 ורק אז נקנה לו החפץ.","ומעירים: אם כן, \u0003לרב אחא קשיא רישא\u0004 \u0005[קשה\u0006 הדיוק של \u0005ההתחלה],\u0006 ו\u0003לרבינא קשיא סיפא\u0004 \u0005[קשה\u0006 הדיוק של \u0005הסוף]!\u0006 ומתרצים: \u0003רישא\u0004 \u0005[\u0006דיוק \u0005תחילת\u0006 המשנה\u0005]\u0006 \u0003לרב אחא לא קשיא\u0004 \u0005[אינו קשה]\u0006 ומדוע? — שהוא מפרש: כל \u0003כמה\u0004 ש\u0003לא אתי לרשותיה\u0004 \u0005[הגיע\u0006 הדבר ממש \u0005לרשותו],\u0006 גם אם יצא מרשות הבעלים, עדיין \u0003רשות בעלים קרינא ביה\u0004 \u0005[אנו קוראים בו,\u0006 אותו\u0005].\u0006 \u0003סיפא\u0004 \u0005[הסוף]\u0006 \u0003לרבינא\u0004 גם כן \u0003לא קשיא\u0004 \u0005[קשה]\u0006 כי הדיוק הזה של רב אחא ש\u0003הוצאה דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003הגבהה — לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 ולכן יש לפרש במשנה שההוצאה בלבד מרשות הבעלים מקנה לו את החפץ.","שנינו במשנה: \u0003הבא על אחותו ועל אחות אביו כו'\u0004 הרי הוא חייב עליהן קנס. \u0003ורמינהו\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במסכת מכות, \u0003אלו הן הלוקין: הבא על אחותו, ו\u0004כן הבא \u0003על אחות אביו, ו\u0004כן הבא \u0003על אחות אמו, ו\u0004כן הבא \u0003על אחות אשתו,\u0004 או \u0003על אשת אחיו,\u0004 או \u0003על אשת אחי אביו,\u0004 או \u0003על הנדה.\u0004 שהבא על אחת מאלה במזיד, לוקה."],["\u0003וקיימא לן\u0004 \u0005[ומוחזק לנו,\u0006 יודעים אנו\u0005]\u0006 ש\u0003אינו לוקה ומשלם,\u0004 ואם לוקה על אונס אחותו, מדוע אם כן משלם גם קנס על כך? \u0003אמר עולא: לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003כאן\u0004 במשנה שלנו מדובר שבא על \u0003אחותו נערה\u0004 שמשלם עליה קנס ולכן אינו לוקה, ואילו \u0003כאן\u0004 במסכת מכות מדובר \u0003ב\u0004מקרה שבא על \u0003אחותו בוגרת\u0004 שאינו משלם קנס, ולכן לוקה.","ושואלים: וכשבא באונס על \u0003אחותו\u0004 ה\u0003בוגרת נמי\u0004 \u0005[גם כן]\u0006 אף שאינו משלם קנס \u0003הא איכא\u0004 \u0005[הרי יש]\u0006 תשלומי \u0003בושת ופגם\u0004 שהם חיובי ממון ולא קנס, ואף שם צריך לשלם ולא ללקות! ומשיבים: מדובר שם \u0003בשוטה\u0004 שאין לה בושת, ואף אין משלם פגם, מפני שעצם היותה שוטה הוא פגם גדול כל כך שאין אחריו פגם נוסף. ומקשים: \u0003והא איכא צערא\u0004 \u0005[והרי יש\u0006 תשלום \u0005צער]\u0006 שמשלם אפילו לשוטה על שהכאיב לה בביאת אונס! ומשיבים: מדובר שם \u0003במפותה,\u0004 שאינה מקבלת עבור צער, שהרי מרצונה נבעלה.","ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שבאת,\u0006 שהגעת \u0005לכך]\u0006 להסבר זה שמדובר במפותה, \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר שם ב\u0003אחותו\u0004 ה\u0003נערה,\u0004 ובכל זאת אינו משלם קנס, כי מדובר \u0003ביתומה\u0004 שכל התשלומים שחייב לה מגיעים לה ולא לאביה, \u0003ו\u0004כן ב\u0003מפותה,\u0004 שכיון שהיתה מפותה, שעשתה מדעתה, אין כאן חיוב תשלומים כלל, ולכן יש עליו חיוב מלקות.","ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן שסבור]\u0006 \u0003עולא\u0004 כי \u0003כל היכא דאיכא\u0004 \u0005[מקום שיש]\u0006 חיוב גם של \u0003ממון ו\u0004גם של \u0003מלקות — ממונא\u0004 \u0005[ממון]\u0006 הוא ש\u0003משלם\u0004 אבל \u0003מילקא לא לקי\u0004 \u0005[ללקות, אינו לוקה],\u0006 ולכן הבא על אחותו נערה, משלם קנס ואינו לוקה. ושואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003לעולא הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 ומשיבים: \u0003גמר\u0004 \u0005[למד]\u0006 \u0003מ\u0004דין ה\u0003חובל בחבירו; מה חובל בחבירו דאיכא\u0004 \u0005[שיש]\u0006 גם עונש \u0003ממון\u0004 עבור החבלה, \u0003ו\u0004גם \u0003מלקות\u0004 שעבר על לאו מן התורה (\"פן יוסיף להכותו\". דברים כה, ג), וההלכה היא כי \u0003ממונא\u0004 \u0005[ממון]\u0006 הוא \u0003משלם,\u0004 אבל \u0003מילקא לא לקי\u0004 \u0005[ללקות, אינו לוקה],\u0006 ומכאן נלמד הכלל: \u0003אף כל היכא דאיכא\u0004 \u0005[מקום שיש]\u0006 חיוב \u0003ממון ומלקות — ממונא\u0004 \u0005[ממון]\u0006 \u0003משלם, מילקא לא לקי\u0004 \u0005[ללקות, אינו לוקה].\u0006","ומקשים: \u0003מה לחובל בחבירו\u0004 שאי אפשר ללמוד ממנו הלכה כללית שמשלם ממון — לפי שחיוב הממון שבחובל הוא חיוב חמור, \u0003שכן חייב בחמשה דברים\u0004 (נזק, צער, ריפוי, שבת, בושת) ואין ללמוד מכאן למקרים אחרים שיהא חייב לשלם ממון. ומצד שני: \u0003ואי ממונא לקולא\u0004 \u0005[ואם\u0006 תאמר שעונש \u0005ממון\u0006 הוא עונש \u0005קל]\u0006 יותר ממלקות, ושמא נלמד מחובל שתמיד נותנים את העונש הקל ממון ולא מלקות — אין ללמוד מחובל בחבירו הלכה כללית להקל שישלם בכל מקום ממון, משום שעבירה זו של החובל בחבירו יש בה צד קל, \u0003שכן\u0004 איסור חבלה אינו איסור בכל מקרה, שהרי \u0003הותר מכללו בבית דין,\u0004 שהרי מלקים וחובלים בבית דין את החייבים מלקות, ואין ללמוד מכאן לאיסורים אחרים שאין להם צד היתר.","\u0003אלא\u0004 חוזרים מלימוד זה ואומרים כי \u0003גמר\u0004 \u0005[למד]\u0006 \u0003מעדים זוממין; מה עדים זוממין דאיכא\u0004 \u0005[שיש]\u0006 גם חיוב \u0003ממון\u0004 אם זממו לחייבו ממון בעדותם, \u0003ו\u0004גם \u0003מלקות\u0004 (שעברו על מצות לא תעשה של \"לא תענה ברעך עד שקר\". שמות כ, יג), ואנו יודעים כי דינם של עדים זוממים שרצו לחייב ממון הוא — \u0003ממונא\u0004 \u0005[ממון]\u0006 \u0003משלם, מילקא לא לקי\u0004 \u0005[ללקות, אינו לוקה],\u0006 ומכאן נלמד \u0003אף כל היכא\u0004 \u0005[מקום]\u0006 \u0003דאיכא\u0004 \u0005[שיש]\u0006 חיוב \u0003ממון ומלקות\u0004 יחד — \u0003ממונא\u0004 \u0005[ממון]\u0006 \u0003משלם, מילקא לא לקי\u0004 \u0005[ללקות, אינו לוקה].\u0006","ודוחים: \u0003מה לעדים זוממין\u0004 שהתורה החמירה בדינם, \u0003שכן אינן צריכים התראה,\u0004 כי כרגיל אין האדם נענש אלא אם כן התרו בו תחילה שלא יעבור, וכיון שהחמירה בהם התורה בפרט זה, החמירה גם שיחוייבו לשלם ממון החמור ולא יפטרו במלקות בלבד. \u0003ו\u0004מצד שני, \u0003אי ממונא לקולא\u0004 \u0005[אם\u0006 תאמר שנתינת \u0005ממון\u0006 בדרך כלל \u0005להקל]\u0006 \u0003הוא\u0004 יותר ממלקות, שהרי אפשר לומר שיש באיסורם של העדים הזוממים צד קל, \u0003שכן לא עשו מעשה\u0004 בגופם אלא רק בדיבור בלבד, ושמא מקילים בהם מטעם זה שישלמו רק ממון הקל, אבל במקרים אחרים שנעשה בהם מעשה, יש להחמיר ולחייב מלקות!","\u0003אלא\u0004 יש לומר כי \u0003גמר מתרוייהו\u0004 \u0005[למד משניהם\u0006 יחד\u0005],\u0006 ובדרך זו: \u0003מה הצד השוה שבהן,\u0004 בחובל בחבירו ועדים זוממים, \u0003דאיכא\u0004 \u0005[שיש]\u0006 באותה עבירה חיוב \u0003ממון ומלקות,\u0004 ובשניהם \u0003ממונא\u0004 \u0005[ממון]\u0006 \u0003משלם, מילקא לא לקי\u0004 \u0005[ללקות, אינו לוקה],\u0006 \u0003אף כל היכא דאיכא\u0004 \u0005[מקום שיש]\u0006 חיוב \u0003ממון ומלקות, ממונא\u0004 \u0005[ממון]\u0006 \u0003משלם, מילקא לא לקי\u0004 \u0005[ללקות, אינו לוקה].\u0006 ודוחים: \u0003מה להצד השוה שבהן — שכן יש בהן צד חמור\u0004 שאינו קיים בכל העבירות, שכן החובל חייב בחמישה מיני תשלומים, ועדים זוממים אין בהם התראה, \u0003ואי ממונא לקולא\u0004 \u0005[ואם\u0006 צד \u0005ממון להקל]\u0006 \u0003הוא,\u0004 אפשר לחלק ביניהם לשאר איסורי תורה — \u0003שכן יש בהן צד הקל\u0004 בעונשם, שהחובל — הותר מכללו, ועדים זוממים — לא עשו מעשה, ולפיכך נידונים בעונש קל, ואין ללמוד מהם הלכה כללית."],["\u0003אלא\u0004 יש לומר כי \u0003עולא\u0004 בגזירה שווה של \u0003\"תחת\" \"תחת\" גמר\u0004 \u0005[למד];\u0006 \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בענין אונס: \u0003\"תחת אשר ענה\"\u0004 (דברים כב, כט), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בענין חבלה: \u0003\"עין תחת עין\"\u0004 (שמות כא, כד), \u0003מה התם\u0004 \u0005[שם]\u0006 בענין חבלה \u0003ממונא\u0004 \u0005[ממון]\u0006 \u0003משלם, מילקא לא לקי\u0004 \u0005[ללקות, אינו לוקה],\u0006 \u0003אף כל היכא דאיכא ממונא\u0004 \u0005[מקום שיש\u0006 חיוב \u0005ממון]\u0006 \u0003ומלקות — ממונא\u0004 \u0005[ממון]\u0006 \u0003משלם, מילקא לא לקי\u0004 \u0005[ללקות, אינו לוקה].\u0006","\u0003ר' יוחנן אמר\u0004 הסבר אחר לסתירה בין המשנה שלנו המחייבת קנס באחותו, והמשנה במסכת מכות שנאמר בה שלוקים על כך ובשל כך אינו חייב בקנס: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר בשני המקומות בבא על \u0003אחותו נערה,\u0004 אלא \u0003כאן\u0004 במשנה במסכת מכות מדובר \u0003שהתרו בו\u0004 ולכן חייב מלקות, ומתוך שלוקה — אינו משלם קנס. ואילו \u0003כאן,\u0004 במשנתנו, מדובר באופן \u0003שלא התרו בו,\u0004 וכיון שאין מלקות ללא התראה מוקדמת — הריהו משלם ממון.","ומכאן מסיקים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005סבור]\u0006 \u0003ר' יוחנן\u0004 כי \u0003כל היכא דאיכא\u0004 \u0005[מקום שיש]\u0006 באותה עבירה גם עונש \u0003ממון ו\u0004גם עונש \u0003מלקות ואתרו ביה\u0004 \u0005[והתרו בו] —\u0006 \u0003מילקא לקי\u0004 \u0005[ללקות, לוקה],\u0006 \u0003ממונא\u0004 \u0005[ממון]\u0006 \u0003לא משלם.\u0004 ושואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003לר' יוחנן הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 ומסבירים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין מי שנתחייב מלקות בבית דין: \u0003\"כדי רשעתו\"\u0004 (דברים כה, ב), ומכאן אנחנו למדים: \u0003משום רשעה אחת אתה מחייבו,\u0004 כלומר, אתה מעניש אדם בעונש אחד \u0003ואי\u0004 \u0005[ואין]\u0006 \u0003אתה מחייבו משום שתי רשעיות. וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 לפסוק זה נאמר \u0003\"ארבעים יכנו\"\u0004 (דברים כה, ג), ומכאן למדים שאם מתחייב אדם בשני עונשים, מלקות וממון, הרי מענישים אותו רק באחד מהם — שלוקה ואינו משלם ממון.","ומקשים: \u0003והרי חובל בחבירו דאיכא\u0004 \u0005[שיש]\u0006 גם \u0003ממון ו\u0004גם \u0003מלקות,\u0004 ממון בשל החבלה ומלקות בשל האיסור להכות את חבירו (\"פן יוסיף להכותו\". דברים כה, ג) ובכל זאת \u0003ממונא\u0004 \u0005[ממון]\u0006 \u0003משלם, מילקא לא לקי\u0004 \u0005[ללקות, אינו לוקה]!\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שמשלם ואינו לוקה, הרי זה דווקא \u0003היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא אתרו ביה\u0004 \u0005[התרו בו],\u0006 \u0003אבל\u0004 אם \u0003אתרו ביה\u0004 \u0005[התרו בו]\u0006 לפני שהיכה את חבירו — \u0003מילקא לקי\u0004 \u0005[ללקות, לוקה],\u0006 \u0003ממונא\u0004 \u0005[ממון]\u0006 \u0003לא משלם\u0004 — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אמי אמר ר' יוחנן:\u0004 אם \u0003הכהו\u0004 את חבירו \u0003הכאה שאין בה שוה פרוטה,\u0004 כלומר, שאין התשלום עליה מגיע לשווה פרוטה — \u0003לוקה.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003לא אתרו ביה\u0004 \u0005[התרו בו]\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לוקה?\u0004 שהרי אין לוקים בלי התראה מוקדמת. \u0003אלא פשיטא דאתרו ביה\u0004 \u0005[פשוט\u0006 שמדובר \u0005שהתרו בו],\u0006 \u0003וטעמא\u0004 \u0005[והטעם,\u0006 דווקא\u0005],\u0006 שלוקה — משום \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה\u0004 בתשלום עבירה זו \u0003שוה פרוטה,\u0004 שזה סכום הממון הקטן ביותר שאין חיוב תשלומים על סכום זה, \u0003הא אית\u0004 \u0005[הרי\u0006 אם \u0005יש]\u0006 \u0003בה שוה פרוטה — ממונא\u0004 \u0005[ממון]\u0006 \u0003משלם, מילקא לא לקי\u0004 \u0005[ללקות, אינו לוקה]\u0006 למרות שהתרו בו!","ומשיבים: אפשר לומר \u0003כ\u0004פי ש\u0003אמר ר' אילעא\u0004 בענין עדים זוממים: \u0003בפירוש ריבתה תורה עדים זוממין לתשלומין,\u0004 שיש ריבוי לשון מיוחד בתורה שעדים זוממים שרצו לחייב אדם בממון משלמים ואינם לוקים — \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בחבלה, \u0003בפירוש ריבתה תורה חובל בחבירו לתשלומין.\u0004 ושואלים: \u0003והיכא איתמר\u0004 \u0005[והיכן נאמר]\u0006 דבר זה של \u0003ר' אילעא? ומשיבים, אהא\u0004 \u0005[על זה],\u0006 ששנינו: באו עדים ואמרו \u0003\"מעידין אנו את איש פלוני שחייב לחבירו מאתים זוז\", ונמצאו\u0004 העדים \u0003זוממין\u0004 — הרי הם \u0003לוקין ומשלמין, שלא השם\u0004 (הגורם, הסיבה) \u0003המביאן לידי מכות מביאן לידי תשלומין,\u0004 שהרי העדים לוקים משום שעברו על \"לא תענה ברעך עד שקר\", ומשלמים משום \"ועשיתם לו כאשר זמם\", אלו \u0003דברי ר' מאיר. וחכמים אומרים: כל המשלם אינו לוקה.\u0004","ושאלו שם: \u0003ונימא\u0004 \u0005[ונאמר]\u0006 להיפך: \u0003כל הלוקה אינו משלם! אמר ר' אילעא: בפירוש ריבתה תורה עדים זוממין לתשלומין\u0004 דווקא. ושואלים: \u0003היכן ריבתה תורה?\u0004 ומסבירים: \u0003מכדי כתיב\u0004 \u0005[הרי נאמר]\u0006 בפרשת עדים זוממים: \u0003\"ועשיתם לו כאשר זמם לעשות לאחיו\"\u0004 (דברים יט, יט), ואם כן, מה שנאמר הלאה (דברים יט, כא) בפירוט העונש \u0003\"יד ביד\" למה לי?\u0004 — הרי זה בא לרמוז: \u0003דבר הניתן מיד ליד, ומאי ניהו\u0004 \u0005[ומהו זה] —\u0006 \u0003ממון.\u0004 ומכאן אנו למדים שהחיוב הראשון שחל על עדים זוממים הוא חיוב ממון, ולא חיוב המלקות.","אם כן אפשר לומר כי \u0003חובל בחבירו נמי\u0004 \u0005[גם כן],\u0006 \u0003מכדי כתיב\u0004 \u0005[הלא נאמר]:\u0006 \u0003\"\u0004ואיש כי יתן מום בעמיתו \u0003כאשר עשה כן יעשה לו\"\u0004 (ויקרא כד, יט), אם כן, \u0003\"\u0004כאשר יתן מום באדם \u0003כן ינתן בו\"\u0004 (ויקרא כד, כ) \u0003למה לי?\u0004 — הרי זה בא ללמדנו: \u0003דבר שיש בו נתינה, ומאי ניהו\u0004 \u0005[ומהו זה] —\u0006 \u0003ממון.\u0004","ושואלים: \u0003ור' יוחנן: מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כעולא\u0004 הלומד מגזירה שווה שבכל מקום שיש חיוב ממון ומלקות — משלם ממון ואינו לוקה? ומשיבים: \u0003אם כן\u0004 אתה אומר, \u0003בטלת\u0004 את איסור לא תעשה שיש בו חיוב מלקות של \u0003\"ערות אחותך... לא תגלה\"\u0004 (ויקרא יח, ט), שהרי לשיטה זו יוצא הוא בתשלום קנס, ונפטר מן המלקות."],["\u0003חובל בחבירו נמי\u0004 \u0005[גם כן],\u0006 \u0003אם כן\u0004 שמשלם ואינו לוקה, \u0003בטלת\u0004 את דברי הכתוב \u0003\"\u0004ארבעים יכנו \u0003לא יסיף פן יסיף\"\u0004 (דברים כה, ג)! וכן לגבי \u0003עדים זוממין נמי\u0004 \u0005[גם כן],\u0006 \u0003אם כן בטלת \"והיה אם בן הכות הרשע\"\u0004 (דברים כה, ב)! \u0003אלא\u0004 יש לומר: ב\u0003עדים זוממין אפשר לקיומה\u0004 \u0005[לקיימה],\u0006 את המלקות שיש בלאו זה \u0003בבן גרושה ובן חלוצה\u0004 שאין בו תשלום ממון. שאם העידו על כהן שהוא בן גרושה או בן חלוצה ונמצאו זוממים — מלקים אותם. \u0003חובל בחבירו נמי\u0004 \u0005[גם כן]\u0006 \u0003איכא לקיומה\u0004 \u0005[יש\u0006 מקום \u0005לקיימה]\u0006 \u0003כגון שהכהו הכאה שאין בה שוה פרוטה,\u0004 וכיון שאינו משלם — לוקה.","ומקשים: אם כן \u0003אחותו נמי\u0004 \u0005[גם כן]\u0006 \u0003איכא לקיומה\u0004 \u0005[יש\u0006 מקום \u0005לקיימה]\u0006 \u0003ב\u0004בא על \u0003אחותו\u0004 ה\u0003בוגרת\u0004 שאין בה קנס, ולוקה? ואם כן, לא נתבטל חיוב המלקות שבלאו זה! ומשיבים: \u0003אמר לך\u0004 \u0005[יכול היה\u0006 \u0005לומר לך]\u0006 \u0003ר' יוחנן\u0004 תירוץ אחר מדוע אינו סובר כעולא; \u0003האי\u0004 \u0005[\u0006הכתוב \u0005הזה]\u0006 \u0003\"תחת אשר ענה\"\u0004 (דברים כב, כט) אינו מופנה לגזירה שווה, אלא \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004כמו זה שאמר \u0003אביי.\u0004 ש\u0003אמר אביי, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ונתן האיש השוכב עמה... חמישים כסף... \u0003תחת אשר ענה\"\u0004 (דברים כב, כט), והכוונה היא: \u0003האי\u0004 \u0005[\u0006סכום \u0005זה]\u0006 של חמישים כסף, הוא \u0003\"תחת אשר ענה\"\u0004 בלבד, \u0003מכלל דאיכא\u0004 \u0005[מכאן שיש]\u0006 גם תשלומי \u0003בושת ופגם\u0004 שהוא משלם יתר על הקנס.","ושואלים: \u0003ועולא\u0004 שהשתמש בכתוב זה לגזירה שווה, מניין לו הלכה זו של אביי? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 דבר זה \u0003מ\u0004מה שאמר \u0003רבא\u0004 באותו ענין. ש\u0003אמר רבא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ונתן האיש השכב עמה לאבי הנערה חמשים כסף\"\u0004 (דברים כב, כט), והוא מדייק מיתור הלשון \"השוכב עמה\", כי תמורת \u0003הנאת שכיבה\u0004 משלם \u0003חמשים\u0004 שקל כסף, והוא הקנס, \u0003מכלל דאיכא\u0004 \u0005[מכאן שיש]\u0006 עוד תשלום \u0003בושת ופגם\u0004 שהוא משלם נוסף לכך.","\u0003ר' אליעזר אומר:\u0004 הטעם שבגללו \u0003עדים זוממין ממונא משלמי ומילקא לא לקי\u0004 \u0005[ממון משלמים וללקות אינם לוקים],\u0006 הוא \u0003משום דלאו\u0004 \u0005[שלא]\u0006 \u0003בני התראה נינהו\u0004 \u0005[הם],\u0006 וכיון שאין מתרים בהם, אף אין לוקים על הלאו הזה. \u0003אמר רבא: תדע\u0004 שאינם בני התראה, כי למעשה אי אפשר להתרות בהם. שכן \u0003ניתרי בהו אימת\u0004 \u0005[מתי נתרה בהם]?\u0006 אם \u0003ניתרי בהו מעיקרא\u0004 \u0005[נתרה בהם מתחילה],\u0006 זמן מסויים לפני שהם באים להעיד — \u0003אמרי\u0004 \u0005[יאמרו]:\u0006 \u0003אישתלין\u0004 \u0005[שכחנו]\u0006 את ההתראה, ונמצא שלא היתה להתראה משמעות, שהרי ההתראה באה כדי להיות בטוחים שאדם עובר עבירה בזדון ובידיעה. ואם \u0003ניתרי בהו\u0004 \u0005[נתרה בהם]\u0006 \u0003בשעת מעשה,\u0004 בשעת העדות — \u0003פרשי\u0004 \u0005[יפרשו]\u0006 \u0003ולא מסהדי\u0004 \u0005[יעידו]\u0006 כלל, ואפילו אמת, כי שמא יבהלו מחמת התראה זו, ויחליטו שמוטב להם לשתוק. ואם \u0003ניתרי בהו\u0004 \u0005[נתרה בהם]\u0006 \u0003לבסוף,\u0004 לאחר שהעידו — \u0003מאי דהוה הוה\u0004 \u0005[מה שהיה היה],\u0006 ואין התראה לאחר מעשה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003אביי: וניתרי בהו\u0004 \u0005[ונתרה בהם]\u0006 \u0003בתוך כדי דבור\u0004 מיד בסיום דבריהם. וכיון שההתראה בתוך כדי דיבור לעדותם, יכולים הם עדיין לחזור בהם או לשנות עדותם, ואין זו התראה הבאה לאחר מעשה? \u0003מתקיף לה רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא\u0004 בדרך אחרת: \u0003וניתרי בהו מעיקרא\u0004 \u0005[ונתרה בהם מתחילה]\u0006 לפני שהתחילו להעיד \u0003ונרמז בהו רמוזי\u0004 \u0005[ונרמוז להם רמזים]\u0006 בשעת עדותם, שייזכרו בהתראה, ולא יוכלו לומר ששכחו אותה?","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר אביי: לאו מילתא היא דאמרי\u0004 \u0005[אין זה דבר\u0006 מה \u0005שאמרתי],\u0006 כלומר, מה שאמרתי אינו נימוק אמיתי, ואכן אין עדים זוממים צריכים התראה כדי לעונשם, והנימוק לכך הוא: \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר ש\u0003עדים זוממין צריכין התראה,\u0004 אם כן נצטרך לומר \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא מתרינן בהו\u0004 \u0005[מתרים אנו בהם]\u0006 \u0003לא קטלינן להו\u0004 \u0005[אין\u0006 יכולים \u0005להרוג אותם],\u0006 אולם: \u0003מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 כזה, \u0003דאינהו בעו קטיל\u0004 \u0005[שהם רצו להרוג\u0006 את האדם שהעלילו עליו\u0005]\u0006 \u0003בלי התראה,\u0004 שהרי כל עדותם בשקר היתה, \u0003ואינהו בעו\u0004 \u0005[והם צריכים]\u0006 \u0003התראה? הא בעינן\u0004 \u0005[הרי צריכים אנו]\u0006 שיתקיים בהם \u0003\"ועשיתם לו כאשר זמם לעשות לאחיו\"\u0004 (דברים יט, יט) \u0003וליכא\u0004 \u0005[ואין כאן].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב סמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב ירמיה: אלא מעתה,\u0004 לפי שיקול זה, עדים זוממים שהעלילו על אחד שהוא \u0003בן גרושה\u0004 או \u0003בן חלוצה,\u0004 ש\u0003לא\u0004 מן הכתוב \u0003מ\"כאשר זמם\" קא מיתרבי\u0004 \u0005[הם מתרבים],\u0006 כלומר, שהם אינם נענשים משום שכתוב \"כאשר זמם\" — שהרי אין עושים להם כאשר זממו לעשות לאחיהם, ואינם לוקים אלא מפני שעברו על \"לא תענה ברעך עד שקר\", ואם כן \u0003ליבעי\u0004 \u0005[יצטרכו]\u0006 \u0003התראה!\u0004 ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"משפט אחד יהיה לכם\"\u0004 (ויקרא כד, כב), ללמד: צריך שיהיה \u0003משפט השוה לכולכם,\u0004 כלומר, הואיל ובדרך כלל אין עדים זוממים צריכים התראה, אף במקרה מיוחד זה (שזממו לעשותו בן גרושה או בן חלוצה) אינם צריכים התראה.","\u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר: חובל בחבירו נמי\u0004 \u0005[גם כן]\u0006 מה שאמרו כי \u0003ממונא\u0004 \u0005[ממון]\u0006 \u0003משלם ומילקא לא לקי\u0004 \u0005[וללקות, אינו לוקה],\u0006 יש לכך ראיה לא מגזירה שווה, אלא \u0003מהכא\u0004 \u0005[מכאן],\u0006 ממה שנאמר: \u0003\"וכי ינצו אנשים ונגפו אשה הרה ויצאו ילדיה\u0004 ולא יהיה אסון ענוש יענש כאשר ישית עליו בעל האשה...\u0003\"\u0004 (שמות כא, כב), \u0003ואמר ר' אלעזר: במצות\u0004 (בקטטה) \u0003שבמיתה הכתוב מדבר.\u0004 שמדובר שם באנשים שניסו להכות זה את זה עד מוות, והראייה שכך הוא — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואם אסון יהיה ונתתה נפש תחת נפש\"\u0004 (שמות כא, כג).","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003לא אתרו ביה\u0004 \u0005[התרו בו]\u0006 מתחילה שלא יהרוג את חבירו, ושאם יהרוג — ייהרג, אם כן \u0003אמאי מיקטיל\u0004 \u0005[מדוע ייהרג]\u0006 גם כאשר גרם למוות? \u0003אלא פשיטא דאתרו ביה\u0004 \u0005[פשוט שהתרו בו],\u0006 והכלל הוא: \u0003ומותרה לדבר חמור, הוי\u0004 \u0005[הריהו]\u0006 נחשב \u0003מותרה לדבר הקל.\u0004 שההתראה שהתרו בהם לא להרוג נפש כוללת בתוכה לא רק רציחה, אלא גם שאר חבלות, ולכן הם נחשבים כמותרים גם לעניין החבלה והנזק שגרמו לאשה, \u0003ו\u0004בכל זאת \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"ולא יהיה אסון ענוש יענש\"\u0004 (שמות כא, כב), משמע שמשלמים ממון ואינם לוקים, אף על פי שהיו מותרים גם לענין איסור חבלה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על ההוכחה הזו, \u0003רב אשי,\u0004 ראשית לגבי ההנחה הראשונה: \u0003ממאי\u0004 \u0005[ממה\u0006 מניין\u0005]\u0006 יודע אתה ש\u0003מותרה לדבר חמור הוי\u0004 \u0005[הריהו]\u0006 \u0003מותרה לדבר הקל? דלמא לא הוי\u0004 \u0005[שמא אינו]\u0006 נחשב למותרה?! ועוד, גם \u0003אם תמצא\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 שמותרה לדבר חמור \u0003הוי\u0004 \u0005[הריהו]\u0006 מותרה גם לדבר קל, יש לשאול: \u0003ממאי\u0004 \u0005[ממה]\u0006 יודע אתה ש\u0003מיתה\u0004 היא \u0003חמורה\u0004 ממלקות?"],["\u0003דלמא\u0004 \u0005[שמא]\u0006 עונש \u0003מלקות חמור\u0004 יותר? שהרי \u0003אמר רב: אילמלי\u0004 \u0005[אילו]\u0006 \u0003נגדוה\u0004 \u0005[היו מכים]\u0006 את \u0003חנניה מישאל ועזריה\u0004 כדי שיעבדו עבודה זרה ולא היו משליכים אותם לכבשן האש — \u0003פלחו לצלמא\u0004 \u0005[\u0006היו \u0005עובדים לצלם],\u0006 הרי שמכות קשות ממוות! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב סמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אסי לרב אשי: ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב סמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אשי לרב אשי: ולא שני לך\u0004 \u0005[ו\u0006כי \u0005אין שונה לך,\u0006 אינך מבדיל\u0005]\u0006 \u0003בין הכאה שיש לה קצבה\u0004 ומספר כמו זו של ארבעים המלקות כעונש הכתוב בתורה, \u0003להכאה שאין לה קצבה?\u0004 שודאי עונש מלקות שבתורה קל ממוות, ומה שאמר רב בעניינם חנניה מישאל ועזריה, הריהו במלקות שאין להן שיעור, שהן קשות יותר ממוות.","על עיקר הראיה מדין זה לענין כל תשלומים של חבלה \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יעקב מנהר פקוד: הניחא לרבנן\u0004 \u0005[זה נוח ל\u0006שיטת \u0005חכמים]\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 שמה שנאמר בכתוב \"ונתתה נפש תחת נפש\" (שמות כא, כג), הוא \u0003נפש ממש,\u0004 שאם גרם למות האשה — ממיתים אותו. \u0003אלא ל\u0004שיטת \u0003רבי\u0004 ש\u0003אמר\u0004 שכיון שלא נתכוונו לפגוע באשה, אינם חייבים מיתה כלל, אלא משלמים \u0003ממון,\u0004 כופר נפש, על שגרמו לה מיתה, \u0003מאי איכא למימר\u0004 \u0005[מה\u0006 אם כן \u0005יש לומר]?\u0006 שכן לפי שיטה זו אפשר לומר שלא היתה כאן כל התראה לענין מלקות, ולא נתחייבו אלא ממון כדין מזיק.","\u0003אלא אמר רב יעקב מנהר פקוד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא:\u0004 יש לחזור בנו ממה שאמרנו, והראיה היא \u0003מהכא\u0004 \u0005[מכאן],\u0006 שמכתוב אחר למדים הוכחה לדבר, שנאמר במי שהיכה את חבירו באבן או באגרוף ולא הרגו מיד אלא נפל למשכב, \u0003\"אם יקום והתהלך בחוץ על משענתו ונקה המכה\"\u0004 (שמות כא, יט), ולכאורה הכתוב הזה מיותר, \u0003וכי תעלה על דעתך שזה\u0004 (המוכה) \u0003מהלך בשוק, וזה\u0004 (המכה) \u0003נהרג\u0004 בגללו כרוצח? \u0003אלא מלמד\u0004 כתוב זה \u0003שחובשין\u0004 (אוסרים) \u0003אותו\u0004 את המכה במשך הזמן שהמוכה חולה, \u0003ואי מית\u0004 \u0005[ואם מת]\u0006 אחר כך מחמת המכה — \u0003קטלינן ליה\u0004 \u0005[הורגים אנו אותו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא מית\u0004 \u0005[מת] —\u0006 \"ונקה המכה\" ויוצא מן המאסר, אלא שחייב לשלם לו, כאמור \u0003\"שבתו יתן ורפא ירפא\"\u0004 (שמות כא, יט).","ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003לא אתרו ביה\u0004 \u0005[התרו בו]\u0006 מתחילה — \u0003אמאי מיקטיל\u0004 \u0005[מדוע ייהרג\u0006 המכה\u0005]\u0006 אם מת המוכה, הרי בלא התראה אין הורגים! \u0003אלא פשיטא דאתרו ביה\u0004 \u0005[פשוט שהתרו בו]\u0006 \u0003ומותרה לדבר חמור\u0004 שהתרו בו שאם יהרוג ייענש עונש מוות, הריהו \u0003מותרה\u0004 גם \u0003לדבר הקל\u0004 לחבלה שעונשה מלקות, \u0003ואמר רחמנא\u0004 \u0005[ואמרה תורה]\u0006 \u0003\"שבתו יתן ורפא ירפא\".\u0004 הרי שאינו לוקה על החבלה (למרות ההתראה) אלא משלם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: ממאי\u0004 \u0005[ממה\u0006 מניין\u0005]\u0006 יודע אתה ש\u0003מותרה לדבר חמור הוי\u0004 \u0005[הריהו]\u0006 \u0003מותרה לדבר הקל? דלמא לא הוי\u0004 \u0005[שמא אינו]!\u0006 \u0003ואם תמצא\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003הוי\u0004 \u0005[הריהו]\u0006 מותרה, \u0003ממאי\u0004 \u0005[ממה]\u0006 יודע אתה ש\u0003מיתה חמורה? דלמא\u0004 \u0005[שמא]\u0006 עונש \u0003מלקות חמור\u0004 ממנה? שהרי \u0003אמר רב: אילמלי נגדוה\u0004 \u0005[אילו היו מכים]\u0006 את \u0003חנניה מישאל ועזריה\u0004 כדי שיעבדו עבודה זרה, \u0003פלחו לצלמא\u0004 \u0005[\u0006היו \u0005עובדים לצלם]!\u0006","ועל כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב סמא בריה דרב אסי לרב אשי ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב סמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אשי לרב אשי: ולא שני לך\u0004 \u0005[ו\u0006כי \u0005אינו שונה לך]\u0006 \u0003בין הכאה שיש לה קצבה להכאה שאין לה קצבה?\u0004","על עיקר הוכחה זו, שמשלם ואינו לוקה, \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב מרי: ממאי\u0004 \u0005[ממה\u0006 מניין\u0005]\u0006 יודע אתה שמדובר כאן במי שהיכה את חבירו \u0003במזיד,\u0004 ומה שנאמר \"ונקה המכה\" (שמות כא, יט) כוונתו \u0003\"ונקה\" מקטלא\u0004 \u0005[מ\u0006עונש \u0005מוות]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר פה במכה חבירו \u0003בשוגג,\u0004 וכוונת הכתוב \u0003\"ונקה\"\u0004 — שנפטר \u0003מגלות?\u0004 וכיון שלא היתה כאן התראה (שהרי היה הדבר בשוגג), אינו לוקה, ומשלם ממון? ואם כן אין להוכיח מכאן שהחובל משלם ואינו לוקה. ומסכמים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 ואין הוכחה לדבר.","\u0003ריש לקיש אמר\u0004 הסבר אחר לסתירה בין המשנה שלנו, האומרת שמשלם קנס כאשר בא על אחותו באונס, והמשנה במסכת מכות שנאמר בה שחייב מלקות: \u0003הא מני\u0004 \u0005[זו,\u0006 משנתנו, כשיטת \u0005מי היא]\u0006 — שיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר\u0004 שבכל מעשה שמתחייב בעטיו מלקות וממון, אין אומרים קם ליה בדרבה מיניה, אלא \u0003לוקה ומשלם.\u0004 ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 אתה מפרש שמשנתנו כדעת \u0003ר' מאיר\u0004 היא — \u0003אפילו\u0004 בא על \u0003בתו\u0004 באונס \u0003נמי\u0004 \u0005[גם כן]\u0006 ישלם קנס! והרי במשנה נמנו רק אלו שבאו על חייבי לאוין וכריתות, ולא חייבי מיתה בידי אדם!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003ר' מאיר\u0004 הלכה זו של \u0003לוקה ומשלם אית ליה\u0004 \u0005[יש לו],\u0006 אבל את ההלכה של \u0003מת ומשלם לית ליה\u0004 \u0005[אין לו],\u0006 \u0003ולא\u0004 \u0005[ו\u0006האם \u0005אינו]\u0006 סבור שמת ומשלם? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003גנב\u0004 בהמה של אחר \u0003וטבח\u0004 אותה \u0003בשבת,\u0004 או \u0003גנב וטבח לעבודה זרה,\u0004 או \u0003גנב שור הנסקל\u0004 (שור שנידון להיסקל, ואסור בהנאה, ואם כן אין לו בעצם כל ערך) \u0003וטבחו\u0004 — הרי על כל אלה \u0003משלם תשלומי ארבעה וחמשה\u0004 לבעלים, ככל מי שגנב בהמת חבירו וטבחה, אלו \u0003דברי ר' מאיר, וחכמים פוטרין\u0004 מתשלומים, משום שבמעשהו נתחייב בעונש מיתה (על שחיטה בשבת או שחיטה לעבודה זרה) ונפטר מתשלום ממון. משמע שר' מאיר סבור שאף־על־פי שמתחייב בנפשו, חייב גם בתשלומים!","קושיה זו דוחים: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 על ברייתא זו, \u0003אמר ר' יעקב אמר ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים],\u0006 מוסרים הלכה זו באופן אחר: \u0003אמר ר' ירמיה אמר ר' שמעון בן לקיש,\u0004 ש\u0003ר' אבין ור' אילעא וכל חבורתא\u0004 \u0005[החבורה]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן אמרי\u0004 \u0005[אומרים]:\u0006 שם מדובר \u0003בטובח על ידי אחר,\u0004 כלומר, לא הגנב עצמו טבח, אלא שלוחו הוא שטבח בשבת או טבח לעבודה זרה על פי הוראתו. ולפי הסבר זה, הגנב הוא שמשלם תשלומים אלה והוא לא נתחייב כלל בעונש מוות, שהרי את העבירה עשה שלוחו, ואין מכאן כל ראיה לשיטת ר' מאיר בזה.","תחילה, מבררים הסבר זה של ר' יוחנן לגופו: \u0003וכי זה חוטא וזה מתחייב?\u0004 וכי אפשר לומר שאדם זה, השליח, חטא בטביחה, והאחר (הגנב) יהיה מתחייב בתשלומי ארבעה וחמשה, והרי כלל הוא שאין שליח לדבר עבירה? ומשיבים: יש כאן דין מיוחד, ש\u0003אמר רבא, אמר רחמנא\u0004 \u0005[אמרה תורה]:\u0006 \u0003\"\u0004כי יגנוב איש שור או שה\u0003 וטבחו או מכרו\"\u0004 (שמות כא, לז) — \u0003מה מכירה\u0004 נעשית \u0003על ידי אחר,\u0004 שהרי אין מכירה בלי שיהיה מישהו אחר קונה, והגנב מתחייב אף שהיה אחר שותף עמו בעבירה, \u0003אף טביחה\u0004 מתחייב עליה \u0003על ידי אחר.\u0004 ואם כן גזירת הכתוב היא שלמרות שכרגיל אין שליח לדבר עבירה, מכל מקום כאן מתחייב אדם גם על ידי חבירו.","\u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]\u0006 הוכחה אחרת לדין זה שבטביחה מתחייב על ידי שליח, שנאמר: \"וטבחו או מכרו\" — \u0003\"או\"\u0004 זה בא \u0003לרבות את השליח. דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה תנא\u0004 \u0005[שנה]\u0006 ראיה אחרת, לפי שנאמר שם: \"ישלם תחת השור... תחת השה\" — \u0003\"תחת\"\u0004 בא \u0003לרבות את השליח.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך],\u0006 על הסבר זה, \u0003מר זוטרא\u0004 מצד אחר: \u0003מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 ש\u0003אילו עבד איהו\u0004 \u0005[היה עושה\u0006 אותו \u0005הוא\u0006 עצמו\u0005]\u0006 \u0003לא מיחייב\u0004 \u0005[\u0006היה \u0005מתחייב],\u0006 \u0003ועביד\u0004 \u0005[ועושה]\u0006 אותו \u0003שליח ומחייב\u0004 \u0005[ו\u0006הוא \u0005מתחייב]?\u0006 שהרי אילו היה הוא עצמו טובח בשבת — היה פטור מתשלומים, וכשעושה זאת שליחו — הוא מתחייב! ומשיבים: \u0003איהו\u0004 \u0005[הוא]\u0006 נפטר, \u0003לאו\u0004 \u0005[לא]\u0006 \u0003משום דלא מיחייב\u0004 \u0005[שאינו מתחייב]\u0006 על עצם הטביחה, \u0003אלא משום דקם ליה בדרבה מיניה\u0004 \u0005[שעומד לו,\u0006 די לו, \u0005ב\u0006עונש \u0005בגדול ממנו]\u0006 שהוא עונש מיתה על חילול השבת, ואז למרות שחל עליו בעצם חיוב, אי אפשר להיפרע ממנו בפועל. אבל כשעושה על ידי שליח, כיון שלא חל עליו עונש מיתה — החיוב שחל עליו ניתן עכשיו לתשלומים.","ושואלים מעתה על הסברו של ר' יוחנן לעיקר ההלכה, \u0003אי\u0004 \u0005[אם]\u0006 מדובר כאן \u0003בטובח על ידי אחר,\u0004 יש מקום לתמיהה הפוכה: \u0003מאי טעמייהו דרבנן דפטרי\u0004 \u0005[מה טעמם של חכמים שפוטרים]?\u0006 שהרי הוא עצמו לא עשה עבירה שיש בה חיוב מיתה, ושלוחו שעשה את מעשה הטביחה הוא שהתחייב בנפשו, ומדוע לא יתחייב השולח (הגנב) בתשלומים? ומשיבים: \u0003מאן\u0004 \u0005[מי הם]\u0006 \u0003חכמים\u0004 אלה החולקים על ר' מאיר —"],["\u0003ר' שמעון היא,\u0004 ש\u0003אמר: שחיטה שאינה ראויה,\u0004 כלומר, שחיטה שאינה מכשירה את הבשר לאכילה — \u0003לא שמה שחיטה\u0004 אינה נחשבת שחיטה לכל ענין, ולכן מה שטבח — אינו נחשב. ושואלים: \u0003התינח\u0004 \u0005[נניח]\u0006 לענין \u0003עבודה זרה ושור הנסקל,\u0004 שכיון ששחיטתם אינה מכשירה אותם לאכילה, הרי היא שחיטה שאינה ראויה. \u0003אלא שחיטת שבת\u0004 — הלא \u0003שחיטה ראויה היא! דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003השוחט בשבת וביום הכפורים, אף על פי שמתחייב בנפשו\u0004 משום חילול שבת — \u0003שחיטתו כשרה\u0004 וראויה לאכילה!","ודוחים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 בברייתא שאנו דנים בה \u0003כר' יוחנן הסנדלר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003המבשל בשבת,\u0004 אם בישל \u0003בשוגג — יאכל, במזיד — לא יאכל\u0004 הוא עצמו כלל מתבשיל זה שעשה באיסור, אלו \u0003דברי ר' מאיר. ר' יהודה אומר: בשוגג — יאכל למוצאי שבת\u0004 שקנסוהו, אף שבישל בשוגג, שלא יהנה מיד מן המבושל באיסור, \u0003במזיד — לא יאכל\u0004 ממנו \u0003עולמית. ר' יוחנן הסנדלר אומר: בשוגג — יאכל\u0004 התבשיל \u0003למוצאי שבת לאחרים ולא לו, במזיד — לא יאכל עולמית, לא לו ולא ל\u0004יהודים \u0003אחרים.\u0004 הרי שלשיטת ר' יוחנן הסנדלר דבר שנעשה בחילול שבת במזיד, אינו ראוי לאכילה, וממילא גם שחיטה בשבת היא שחיטה שאינה ראויה.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוחנן הסנדלר?\u0004 ומסבירים: \u0003כדדריש ר' חייא אפיתחא דבי נשיאה\u0004 \u0005[כפי\u0006 \u0005שדרש ר' חייא על פתחו של בית הנשיא],\u0006 נאמר: \u0003\"ושמרתם את השבת כי קדש היא לכם\u0004 מחלליה מות יומת\u0003\"\u0004 (שמות לא, יד) ולומדים: \u0003מה קודש\u0004 (שהוקדש לבית המקדש) \u0003אסור באכילה — אף מעשה\u0004 שנעשה בחילול \u0003שבת אסורין באכילה\u0004 לעולם. ומקשים: \u0003אי\u0004 \u0005[אם\u0006 כן\u0005]\u0006 אולי נלמד באופן אחר: \u0003מה קודש אסור בהנאה — אף מעשה שבת אסור בהנאה!\u0004 ומשיבים, \u0003תלמוד לומר: \"\u0004קודש היא \u0003לכם\"\u0004 (שמות לא, יד) — כוונתו \u0003שלכם יהא\u0004 להנאה.","ושואלים עוד: אם השווינו מלאכת שבת לקודש, \u0003יכול אפילו\u0004 אם עשה \u0003בשוגג\u0004 יהיו מעשה שבת אסורים באכילה כקודש? — \u0003תלמוד לומר: \"מחלליה מות יומת\"\u0004 (שמות לא, יד), לומר: \u0003במזיד אמרתי לך,\u0004 שהרי מדובר כאן בעבודה שיש עליה עונש מיתה \u0003ולא בשוגג,\u0004 שאין חיוב מיתה בשוגג.","ומעירים: \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בשאלה זו \u0003רב אחא ורבינא, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: מעשה שבת\u0004 אסור \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר\u0004 שאסור רק \u0003דרבנן\u0004 \u0005[מדברי חכמים].\u0006 \u0003מאן דאמר דאורייתא\u0004 \u0005[מי שאומר ש\u0006הוא \u0005מן התורה] —\u0006 \u0003כדאמרן\u0004 \u0005[כפי שאמרנו]\u0006 בדרשה זו מן המקרא. ו\u0003מאן דאמר דרבנן\u0004 \u0005[\u0006ו\u0005מי שאומר ש\u0006הוא \u0005מדברי חכמים],\u0006 הרי הוא מדייק באופן אחר: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"קדש היא\",\u0004 ובא הכתוב למעט: \u0003היא\u0004 עצמה, \u0003קודש, ואין מעשיה קודש\u0004 ומותרים מן התורה באכילה.","ושואלים: \u0003ולמאן דאמר דרבנן, מאי טעמייהו דרבנן דפטרי\u0004 \u0005[ול\u0006דעת \u0005מי שאומר\u0006 שמעשה שבת אסורים רק \u0005מדברי חכמים, מה טעמם של\u0006 אותם \u0005חכמים שפוטרים]\u0006 את מי שגנב וטבח בשבת? ומשיבים: \u0003כי קא פטרי רבנן\u0004 \u0005[כאשר פוטרים חכמים]\u0006 הרי זה \u0003אשארא\u0004 \u0005[על השאר]\u0006 על המקרים האחרים: השוחט שור הנסקל והשוחט לעבודה זרה.","ועוד שואלים על דברי ר' מאיר המחייב בטובח לעבודה זרה: \u0003טובח לעבודה זרה, כיון\u0004 ש\u0003שחט ביה פורתא\u0004 \u0005[בה מעט]\u0006 בתחילת מעשה השחיטה הלא \u0003איתסר ליה\u0004 \u0005[נאסרה לו]\u0006 הבהמה בהנאה משום תקרובת עבודה זרה, \u0003אידך כי קא טבח לאו דמריה קא טבח\u0004 \u0005[השאר כאשר\u0006 הוא גומר \u0005לטבוח,\u0006 לשחוט, \u0005לא\u0006 את \u0005של בעליו\u0006 הוא \u0005טובח]\u0006 שהרי חל על הבהמה הזו איסור הנאה, והופקעה מרשות הבעלים? \u0003אמר רבא:\u0004 מדובר שם \u0003באומר\u0004 בשעת שחיטה זו שרק \u0003בגמר זביחה\u0004 \u0005[שחיטה]\u0006 \u0003הוא עובדה\u0004 לעבודה זרה, ואם כן אין האיסור חל מתחילת השחיטה, אלא רק בסופה.","ועוד שואלים על שיטת ר' מאיר: \u0003שור הנסקל לאו דידיה\u0004 \u0005[לא\u0006 את \u0005שלו],\u0006 של הבעלים, \u0003הוא דקטבח\u0004 \u0005[שטובח]!\u0006 שהרי הוא אסור בהנאה מזמן שנגמר דינו לסקילה! \u0003אמר רבה: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שמסרו\u0004 הבעלים את השור \u0003לשומר, והזיק\u0004 השור \u0003בבית\u0004 ה\u0003שומר, ונגמר דיניה\u0004 \u0005[דינו]\u0006 \u0003בבית שומר\u0004 לסקילה, \u0003וגנבו גנב מבית\u0004 ה\u0003שומר\u0004 וטבחו.","\u0003ו\u0004צריכים להוסיף כי \u0003ר' מאיר סבר לה\u0004 \u0005[סבור]\u0006 \u0003כ\u0004שיטת \u0003ר' יעקב וסבר לה\u0004 \u0005[וסבור]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון.\u0004 וכיצד? \u0003סבר לה כר' יעקב —\u0004 ש\u0003אמר: אף משנגמר דינו\u0004 של השור, אם \u0003החזירו שומר לבעליו — מוחזר,\u0004 ואין הבעלים יכולים לומר שהשור הזה איננו שוה כעת מאומה משום שנידון לסקילה — שהרי בגופו של השור לא נעשה כל שינוי. \u0003ו\u0004מצד שני \u0003סבר לה\u0004 ר' מאיר \u0003כר' שמעון,\u0004 ש\u0003אמר: דבר הגורם לממון — כממון דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 שאף דבר זה כשלעצמו אין לו ערך, כיון שחסרונו גורם להפסד ממון — הרי זה כדבר של ממון. ואף כאן, אף ששור הנסקל הזה שנאסר בהנאה אין לו ערך לעצמו, מכל מקום אם הוא שחוט — שוב אין השומר יכול להחזירו, ומתחייב בממון בתמורתו, לכן חייב הגנב לשלם לשומר אף שגנב שור הנסקל, שהרי לגבי השומר נחשב הוא כממון. עד כאן הוסברו הדברים לפי ההנחה שהטביחה נעשתה על ידי אחר.","\u0003רבה אמר:\u0004 יש לפרש ש\u0003לעולם\u0004 מדובר \u0003בטובח על ידי עצמו,\u0004 שטובח את השור או את השה בעצמו,"],["\u0003ור' מאיר\u0004 את ההלכה של \u0003לוקה ומשלם אית ליה\u0004 \u0005[יש לו,\u0006 הוא מקבל\u0005],\u0006 אבל את ההלכה של \u0003מת ומשלם לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005],\u0006 \u0003ושאני הני\u0004 \u0005[ושונים\u0006 דינים \u0005אלה],\u0006 משום ש\u0003חידוש הוא שחידשה תורה בקנס, אף על גב דמיקטיל\u0004 \u0005[\u0006ש\u0005אף על פי ש\u0006הוא \u0005נהרג]\u0006 בכל זאת הוא \u0003משלם. ואזדא\u0004 \u0005[והולך]\u0006 \u0003רבה\u0004 בענין זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 ש\u0003אמר רבה: היה\u0004 ברשותו \u0003גדי גנוב לו\u0004 זה מכבר, שגנבו קודם לכן, \u0003וטבחו\u0004 (שחטו) \u0003בשבת\u0004 — הריהו \u0003חייב\u0004 ארבעה וחמישה משום טובח, מפני \u0003שכבר נתחייב בגניבה קודם שיבא לידי איסור שבת.\u0004 ולמרות שהטביחה היתה בשבת — חייב, כיון שתשלומי ארבעה וחמישה על מעשה הטביחה הם קנס ואין המיתה פוטרתו מחיוב קנס. אולם אם \u0003גנב וטבח בשבת\u0004 עצמה — \u0003פטור, שאם אין\u0004 עליו חיוב תשלום משום ה\u0003גניבה,\u0004 שהרי נתחייב מיתה משום שבת, והמיתה פוטרתו מחיוב תשלום הגניבה שהינו חיוב ממון מעיקר הדין, ולא קנס, וממילא \u0003אין\u0004 גם חיוב תשלום ארבעה וחמישה על ה\u0003טביחה\u0004 (שחיטה) \u0003ואין\u0004 חיוב על \u0003מכירה\u0004 אף שהוא קנס. שכיון שאינו משלם את הקרן, הרי שאין מתקיימים בכך דברי הכתוב \"חמישה בקר ישלם תחת השור וארבע צאן תחת השה\" (שמות כא, לז), שהרי אינו משלם ארבעה וחמישה, אלא שלושה וארבעה בלבד.","\u0003ו\u0004עוד \u0003אמר רבה: היה גדי גנוב לו וטבחו במחתרת,\u0004 שחתר בבית כדי להוציאו משם — אף שדין מוות עליו, שהרי אם מצאו בעל הבית בבואו במחתרת והרגו אינו חייב עליו, בכל זאת \u0003חייב\u0004 ככל טובח ומוכר, משום \u0003שכבר נתחייב בגניבה קודם שיבא לידי איסור מחתרת.\u0004 אבל אם \u0003גנב וטבח\u0004 (שחט) \u0003במחתרת\u0004 — \u0003פטור,\u0004 כיון שמותר לבעל הבית להורגו שם, נמצא שחייב בעונש חמור יותר. ואף שתשלומי ארבעה וחמישה הינם קנס ואין המיתה פוטרתו מהם, מכל מקום נפטר מהם, משום \u0003שאם אין\u0004 חיוב תשלום בשל ה\u0003גניבה, אין\u0004 גם תשלום בשל ה\u0003טביחה ואין\u0004 גם חיוב בשל ה\u0003מכירה.\u0004 ומדברי רבה אלו יש ראיה שעל תשלומי קנס כטביחה ומכירה חייב גם כאשר מתחייב בעונש חמור של מיתה.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שיאמר רבה את דבריו גם לענין גניבה בשבת וגם לענין מחתרת. \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק בענין \u0003שבת,\u0004 היינו אומרים: \u0003משום\u0004 שהיא חמורה ש\u0003איסורה איסור עולם,\u0004 וכל אימת שיעידוהו שעבר על איסור זה, על בית הדין להמיתו, ולכן כאשר מתחייב בה, פטור מן התשלומים, \u0003אבל מחתרת,\u0004 ש\u0003איסור שעה הוא,\u0004 שהרי החיוב בנפשו של הבא במחתרת איננו איסור קבוע, אלא רק בשעה ובמקום שהוא בא לגנוב שם, ואם כבר יצא מן המחתרת — אסור להורגו, ואם כן \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ייפטר בגלל זה מחובת הממון. ולהיפך: \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק בענין \u0003מחתרת,\u0004 היינו אומרים: \u0003משום\u0004 ש\u0003מחתרתו זו היא התראתו.\u0004 כלומר, עצם העובדה שהוא נכנס לשם או חותר שם — הרי זה מעשה המקביל להתראה שמתרים בעובר עבירה במזיד, שבודאי בא להרוג אם לא יתנו לו את הממון, ולכן נפטר בקבלת העונש החמור, \u0003אבל שבת, דבעיא\u0004 \u0005[שצריכה]\u0006 עוד \u0003התראה\u0004 — אין עונשה חמור כל כך, ואם כן \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהיה פטור בגללה, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר.","\u0003אמר רב פפא: היתה פרה גנובה לו\u0004 זה מכבר, \u0003וטבחה\u0004 (שחטה) \u0003בשבת — חייב\u0004 לשלם חמש פרות, משום \u0003שכבר נתחייב בגניבה קודם שיבא לידי איסור שבת.\u0004 אבל אם \u0003היתה פרה שאולה לו, וטבחה בשבת — פטור\u0004 מלהחזיר דמי פרה אחרת. שהרי אינו נעשה גנב עליה אלא משעת שחיטתה, ובאותה שעה הרי מתחייב מיתה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 וכי \u0003רב פפא\u0004 דין \u0003פרה אתא לאשמועינן\u0004 \u0005[בא להשמיע לנו]?!\u0006 כלומר, מה הוסיף רב פפא על דברי רבה? וכי ייתכן שרבה אמר הלכה בגדי ורב פפא אמר אותה ההלכה בפרה? שהרי לכאורה העקרון אחד הוא — שאם בשעת הגניבה היה חייב לשלם, הוא מוסיף ומתחייב גם על טביחה למרות שיש בה איסור מיתה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003רב פפא\u0004 לענין \u0003שאולה אתא לאשמועינן\u0004 \u0005[בא להשמיע לנו]\u0006 חידוש; \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 \u0003הואיל ואמר רב פפא\u0004 כי \u0003משעת משיכה\u0004 של הפרה לרשותו של השואל \u0003הוא דאתחייב ליה\u0004 \u0005[שהתחייב לו]\u0006 השואל \u0003במזונותיה\u0004 של הפרה, \u0003הכא נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003משעת שאלה אתחייב\u0004 \u0005[התחייב]\u0006 \u0003באונסיה,\u0004 שנעשה כקניינו לענין שהוא משלם על כל מקרה אונס שקורה לה אחר כך, ואפילו טבח בשבת יתחייב על שעת השאלה. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהחיוב בתשלומי אונסים חל רק משעה שהיה האונס בפועל, ואם היה בשבת נפטר.","\u0003אמר רבא:\u0004 בנים ש\u0003הניח להן אביהן פרה שאולה — משתמשין בה כל ימי שאלתה,\u0004 שזכות השאילה נמשכת אף שהשואל עצמו כבר מת, ואם \u0003מתה — אין חייבין באונסה,\u0004 שכיון שלא הם היו השואלים, לא חל עליהם חיוב באונסים. וכן אם \u0003כסבורין\u0004 היו שהפרה הזו \u0003של אביהם היא וטבחוה ואכלוה — משלמין דמי בשר בזול.\u0004 שמשלמים רק מה שנהנו, ולא את כל הנזק שנגרם לבעלים. אבל אם \u0003הניח להן אביהן אחריות נכסים,\u0004 שהניח להם נכסים שיש להם אחריות והשעבוד חל איפוא על הנכסים עוד בחייו — \u0003חייבין לשלם\u0004 את כל הנזק.","ומעירים: \u0003איכא דמתני לה ארישא ואיכא דמתני לה אסיפא\u0004 \u0005[יש ש\u0006היה \u0005שונה\u0006 את הפיסקה האחרונה \u0005הזו על ראשה\u0006 של ההלכה, \u0005ויש ש\u0006היה \u0005שונה אותה על סופה].\u0006 ומסבירים: \u0003מאן דמתני לה ארישא\u0004 \u0005[מי ש\u0006היה \u0005שונה אותה על ראשה],\u0006 שבזמן שיש אחריות נכסים חייבים בכל אונס שאירע לפרה השאולה — \u0003כל שכן\u0004 שהלכה זו שייכת \u0003אסיפא\u0004 \u0005[על סופה],\u0006 שמאחר שהם עצמם שחטוה, ודאי חייבים לשלם הכל. \u0003ו\u0004אם כן \u0003פליגא\u0004 \u0005[חלוקה]\u0006 דעה זו על \u0003רב פפא,\u0004 שהרי הבסיס לשיטה זו הוא שחיוב השואל באונסים חל משעת השאילה. \u0003ומאן דמתני לה אסיפא\u0004 \u0005[ומי ששונה אותה על סופה]\u0006 כשטבחו ואכלו, \u0003אבל ארישא\u0004 \u0005[על ראשה]\u0006 שמתה באונס \u0003לא,\u0004 אינו שונה אותה, שאף הוא סבור שחיוב האונסים אינו חל משעת המשיכה אלא רק בשעה שאירע האונס, \u0003ו\u0004אם כן \u0003היינו\u0004 \u0005[זהו]\u0006 כמו בדינו של \u0003רב פפא.\u0004","כאמור, שיטת משנתנו המחייבת את הבא על אחותו באונס בתשלום קנס, אף שבשל כך נתחייב מלקות, הוסברה איפוא בכמה דרכים. ר' יוחנן מעמיד את המשנה באופן שלא התרו בו, ולכן אינו לוקה. וכיון שאינו לוקה — משלם. וריש לקיש מעמיד את המשנה כשיטת ר' מאיר הסובר שכל העושה מעשה המחייב מלקות וממון, לוקה ומשלם. ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 כי \u0003ר' יוחנן לא אמר כריש לקיש\u0004 ולא פירש את משנתנו לדעת ר' מאיר, משום \u0003דקא מוקים לה כרבנן\u0004 \u0005[ש\u0006הוא \u0005מעמיד אותה כ\u0006דעת \u0005חכמים]\u0006 החולקים על ר' מאיר, ועדיף בעיניו שסתם משנה תהיה כהלכה, \u0003אלא ריש לקיש מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' יוחנן?\u0004 ומשיבים: כיון שר' יוחנן מסביר שמדובר במקרה שלא התרו בו, \u0003אמר לך\u0004 \u0005[\u0006היה יכול ריש לקיש \u0005לומר לך]:\u0006 \u0003כיון\u0004 ש\u0003אילו אתרו ביה\u0004 \u0005[\u0006היו \u0005מתרים בו]\u0006 היה \u0003פטור\u0004 מתשלומים — \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא אתרו ביה\u0004 \u0005[התרו בו]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור.\u0004","\u0003ואזדו לטעמייהו\u0004 \u0005[והולכים\u0006 הם \u0005לטעמם,\u0006 לשיטתם\u0005].\u0006 \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: חייבי מיתות שוגגין,\u0004 מי שעבר עבירה שחייב עליה מיתה, אלא שעשה אותה בשוגג, או \u0003חייבי מלקיות שוגגין ודבר אחר,\u0004 כלומר, שנוסף לכך היה בעבירה זו גם חיוב ממון — \u0003ר' יוחנן אמר: חייב,\u0004 מאחר שהעבירה נעשתה בשגגה ולא קיבל עליה עונש חמור. \u0003וריש לקיש אמר: פטור.\u0004 וטעמיהם — \u0003ר' יוחנן אמר חייב\u0004 — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לא אתרו ביה\u0004 \u0005[התרו בו]\u0006 בעבירה זו שעונשה מיתה, ובשוגג עשאה. \u0003ריש לקיש אמר פטור\u0004 — \u0003כיון\u0004 ש\u0003אילו אתרו ביה\u0004 \u0005[התרו בו]\u0006 היה \u0003פטור\u0004 מלשלם, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא אתרו ביה\u0004 \u0005[התרו בו]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ריש לקיש לר' יוחנן\u0004 מן הכתוב בשני אנשים שרבו זה עם זה, ותוך כדי כך פגעו באשה הרה וגרמו לה להפיל, שנאמר: \u0003\"ולא יהיה אסון ענוש יענש\u0004 כאשר ישית עליו בעל האשה\u0003\"\u0004 (שמות כא, כב),"],["\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ש\"אסון\" משמעו \u0003אסון ממש,\u0004 שמתה האשה ואז אינו משלם ממון כלל, ואפילו כשלא התרו בו, שהרי היה הדבר בשוגג, ושלא כשיטת ר' יוחנן! ודוחים: \u0003לא,\u0004 אפשר לומר שהכוונה היא \u0003דין אסון,\u0004 דבר שיש בו דין של אסון. כלומר, חיוב מיתת בית דין בעדים והתראה, רק אז פטור המכה מתשלומים, אבל כשלא היה דין אסון, כגון שמתה האשה ולא התרו במכה — חייב בתשלומים. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש:\u0004 נאמר \u0003\"ולא יהיה אסון ענוש יענש\"\u0004 (שמות כא, כב), \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא \u0003דין אסון?\u0004 ודוחים: \u0003לא,\u0004 הכוונה היא \u0003אסון ממש.\u0004","\u0003אמר רבא: ומי איכא למאן דאמר\u0004 \u0005[והאם יש מי שאומר]\u0006 שאותם עושי מעשה במזיד שבגללו הינם \u0003חייבי מיתות,\u0004 אם עשו זאת \u0003שוגגין, חייבים\u0004 בתשלומים? \u0003והא תנא דבי\u0004 \u0005[והרי שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה:\u0004 נאמר דין \u0003מכה אדם ו\u0004נאמר דין \u0003מכה בהמה,\u0004 והכתוב מקיש אותם זה לזה באומרו \"ומכה בהמה ישלמנה ומכה אדם יומת\" (ויקרא כד, כא), ללמדנו:","\u0003מה מכה בהמה לא חילקת בו, בין בשוגג בין במזיד, בין מתכוין לשאין מתכוין, בין דרך ירידה לדרך עלייה\u0004 שבכל אחד מהאופנים הללו אין אתה בא \u0003לפוטרו\u0004 מתשלום \u0003ממון, אלא לחייבו ממון,\u0004 שכל אדם המזיק רכוש של חבירו צריך בכל מקרה לשלם — \u0003אף מכה אדם לא תחלוק בו בין\u0004 אם עשה זאת \u0003בשוגג, בין במזיד, בין מתכוין\u0004 להרוג \u0003לשאין מתכוין, בין\u0004 שהיתה מכת מוות \u0003דרך ירידה לדרך עלייה\u0004 (למרות שלענין גלות חייב רק המכה בדרך ירידה) — \u0003לחייבו ממון,\u0004 כשבאותה שעה שהרג אדם גרם להפסד ממון, \u0003אלא לפוטרו ממון.\u0004 וההשוואה בין מכה אדם למכה בהמה היא איפוא ששני הדינים הללו הם מוחלטים, שבדיני נזקי ממון בכל מקרה יש חיוב תשלומים, ובדיני מיתה בכל מקרה פטור מן התשלומים.","\u0003אלא,\u0004 יש לחזור בנו ממה שאמרנו, ו\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר: חייבי מיתות שוגגין כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שהם \u0003פטורין,\u0004 כפי שלמדנו מדברי תנא דבי חזקיה. \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חלוקים],\u0006 הרי זה \u0003בחייבי מלקות שוגגין ודבר אחר,\u0004 וכגון שעשו בשוגג עבירה שחייבים עליה מלקות אילו היתה נעשית במזיד, וגם התחייבו ממון. \u0003ר' יוחנן אמר: חייב,\u0004 ומדוע — \u0003חייבי מיתות איתקוש\u0004 \u0005[הוקשו,\u0006 הושוו\u0005]\u0006 לדיני ממונות כפי הדרשה שלמעלה, ולמדנו שהם פטורים מממון בכל מקרה, אף כשהם שוגגים ואינם בחיוב מיתה, אבל \u0003חייבי מלקיות לא איתקוש\u0004 \u0005[הוקשו,\u0006 הושוו\u0005],\u0006 ולכן, כשאין מלקות ממש — משלם. \u0003ריש לקיש אמר: פטור,\u0004 כי \u0003בפירוש ריבתה תורה\u0004 להשוות \u0003חייבי מלקיות כחייבי מיתות.\u0004","ושואלים: \u0003היכן ריבתה תורה\u0004 דבר זה? \u0003אמר אביי: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר מגזירה שווה \u0003\"רשע\" \"רשע\";\u0004 שבמקום אחד נאמר \"אשר הוא רשע למות\" (במדבר לה, לא), ונאמר \"אם בן הכות הרשע\" (דברים כה, ב), הרי שמשווה הכתוב חייבי מלקות לחייבי מיתה. \u0003רבא אמר אתיא\u0004 \u0005[בא\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה של \u0003\"מכה\" \"מכה\". אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא:\u0004 על \u0003הי\u0004 \u0005[איזה]\u0006 \u0003\"מכה\"\u0004 אתה מדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 להשוואה של \u0003\"ומכה בהמה ישלמנה ומכה אדם יומת\"\u0004 (ויקרא כד, כא) — הלא \u0003האי בקטלא כתיב\u0004 \u0005[\u0006\"מכה אדם\" \u0005זה\u0006 שנאמר, \u0005במיתה\u0006 הוא ש\u0005נאמר],\u0006 שהכאה האמורה שם היא הכאה של מיתה! \u0003אלא האי \"מכה\"\u0004 \u0005[\"מכה\" זה]\u0006 שנאמר במקום אחר; \u0003\"\u0004ו\u0003מכה נפש בהמה ישלמנה נפש תחת נפש\"\u0004 (ויקרא, כד יח), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 \u0003\"ואיש כי יתן מום בעמיתו כאשר עשה כן יעשה לו\"\u0004 (ויקרא כד, יט), ומשוים חייבי מלקות לחייבי ממון לפטור אותם מממון, אף על זה יש להקשות:","\u0003והאי לאו\u0004 \u0005[ו\u0006הלא \u0005זה לא]\u0006 \u0003\"מכה\" היא!\u0004 שהרי בפסוק זה לא נאמרה המלה \"מכה\" כלל, אלא \"כי יתן מום בעמיתו\", ואם כן אין כאן גזירה שווה! ומשיבים: אין זו גזירה שווה של מילים זהות, אלא \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003\"הכאה\" \"הכאה\" קאמרינן\u0004 \u0005[אומרים],\u0006 שהיא גזירה שווה הקשורה במושגים, שכן נתינת מום היא תוצאה של הכאה, ובכך די כדי להשוות דין הכאה בבהמה לדין הכאה באדם. ומקשים: \u0003והא כי כתיב\u0004 \u0005[והרי כאשר נאמר]\u0006 כתוב זה של נתינת מום — \u0003בחובל בחבירו הוא דכתיב\u0004 \u0005[שנאמר],\u0006 \u0003וחובל בחבירו\u0004 הלא \u0003בר תשלומין הוא\u0004 ואינו לוקה, ואם כן כל הראיה מעורערת מעיקרה! ומשיבים: \u0003אם אינו ענין להכאה שיש בה שוה פרוטה,\u0004 שבה הוא משלם ואינו לוקה — \u0003תנהו ענין להכאה שאין בה שוה פרוטה,\u0004 שעל הכאה כזו אינו משלם, ולכן חייב מלקות."],["\u0003סוף סוף\u0004 הרי חובל זה שלוקה \u0003לאו בר\u0004 \u0005[לא בן]\u0006 \u0003תשלומין הוא,\u0004 כיון שאין בו שוה פרוטה, ולא משום שנתחייב במלקות, ומהיכן למדים להלכה הכללית שבכל מקום, שיש בו צד חיוב מלקות אינו משלם, גם כאשר אינו לוקה ממש? ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 ההשוואה בין הכתובים אלא באופן כזה, \u0003דבהדי דמחייה\u0004 \u0005[שביחד,\u0006 באותו זמן \u0005שהיכה אותו]\u0006 \u0003קרע\u0004 גם \u0003שיראין דיליה\u0004 \u0005[משי שלו],\u0006 שהיו כאן שתי עבירות שונות ובכל זאת למדים מן ההיקש שהוא פטור מכל תשלום ממון שהוא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חייא לרבא: ול\u0004שיטת ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה\u0004 ש\u0003אמר \"מכה אדם\" ו\"מכה בהמה\", ממאי\u0004 \u0005[ממה,\u0006 מניין\u0005]\u0006 יודע הוא שכל אלה \u0003ב\u0004יום \u0003חול כתיב\u0004 \u0005[נאמרו],\u0006 \u0003וליכא לאיפלוגי\u0004 \u0005[ואין לחלק]\u0006 בין שוגג למזיד, \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003בשבת כתיב\u0004 \u0005[נאמר\u0006 הדבר\u0005]\u0006 שחבל בבהמה בשבת ש\u0003בבהמה גופה\u0004 \u0005[עצמה]\u0006 \u0003איכא לאיפלוגי\u0004 \u0005[יש\u0006 מקום \u0005לחלק],\u0006 בין שוגג למזיד, שבשוגג שאינו חייב במיתה, הוא מתחייב בתשלומים, ובמזיד פטור מתשלומים, מפני שנענש עונש חמור על חילול שבת, ואם כן אין מקום כלל ללימוד זה!","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[תעלה על דעתך]\u0006 לומר כך, משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ומכה בהמה ישלמנה ומכה אדם יומת\"\u0004 (ויקרא כד, כא) ויש לברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר במקרה ש\u0003לא אתרו ביה\u0004 \u0005[התרו בו],\u0006 אם כן \u0003מכה אדם אמאי\u0004 \u0005[מדוע]\u0006 \u0003יומת?\u0004 הלא אין עונשים עונשי גוף אלא לאחר התראה! \u0003אלא פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006 \u0003דאתרו ביה\u0004 \u0005[שהתרו בו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר שעשה זאת \u0003בשבת\u0004 והתרו בו, וכי \u0003מכה בהמה ישלמנה?!\u0004 שכן אם התרו בו שלא להרוג את הבהמה בשבת, הריהו חייב משום חילול שבת שיש בהריגת הבהמה ובודאי לא ישלמנה. \u0003אלא לאו\u0004 \u0005[לא]\u0006 מדובר פה אלא \u0003ב\u0004יום \u0003חול.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: לרבה\u0004 ש\u0003אמר\u0004 כי \u0003חידוש הוא שחידשה תורה בקנס, ואף על גב דמיקטיל\u0004 \u0005[ואף על פי שנהרג]\u0006 והתחייב מיתה על מה שעשה, \u0003משלם\u0004 קנס, \u0003מתניתין כמאן מוקים לה\u0004 \u0005[\u0006את \u0005משנתנו כמי\u0006 הוא \u0005מעמיד,\u0006 מסביר \u0005אותה]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 הוא מפרש \u0003כ\u0004דעת \u0003ר' מאיר\u0004 הסובר שבכל מקום שעושה מעשה המחייבו מלקות ותשלום, הריהו לוקה ומשלם, אם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדוע לא שנה גם \u0003בתו,\u0004 שלדעתו אין הבדל בין בתו לאחרת, שהרי לשיטת רבה סבור ר' מאיר שאף שחייב מיתה משלם! \u0003אי\u0004 \u0005[אם]\u0006 \u0005כ\u0006דעת \u0003ר' נחוניא בן הקנה,\u0004 הסובר אף הוא כר' מאיר שלוקה ומשלם, אם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדוע נאמר שם שחייב על \u0003אחותו,\u0004 שהרי לדעתו חייבי כריתות הם כחייבי מיתות בית דין לפטור מן הקנס, ואף שאין המלקות פוטרות אותו מן התשלום, מכל מקום יפטרנו הכרת! \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003ר' יצחק,\u0004 הסבור שחייבי כריתות אינם לוקים, ולכן משלמים קנס, אבל בדרך כלל אין לוקה ומשלם \u0003קשיא\u0004 \u0005[קשה]\u0006 מדוע מנויה במשנה \u0003ממזרת\u0004 שיש בה חיוב מלקות לדעת הכל!","\u0003הניחא\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 \u0003אי סבר לה\u0004 \u0005[אם סבור\u0006 רבה\u0005]\u0006 \u0003כר' יוחנן\u0004 הסובר שמי שלא התרו בו, אף שעבר עבירה שיש עליה חיוב מלקות — משלם אם היה גם חיוב ממון, אם כן \u0003הוא נמי\u0004 \u0005[גם כן]\u0006 \u0003מתרץ לה\u0004 \u0005[אותה,\u0006 את המשנה\u0005]\u0006 \u0003כר' יוחנן\u0004 שכל אלה חייבי מלקות השנויים במשנה הם כאשר לא התרו בו. \u0003אלא אי סבר\u0004 \u0005[אם סבור\u0006 רבה\u0005]\u0006 \u0003כריש לקיש,\u0004 שעבירה שיש בה חיוב מלקות, גם אם אינו לוקה בפועל מכיון שלא התרו בו, מכל מקום פטור מתשלומים, \u0003היכי\u0004 \u0005[כיצד]\u0006 הוא \u0003מתרץ לה\u0004 \u0005[אותה]?\u0006 שהרי אינה כאף אחת מהשיטות! ומשיבים: \u0003על כרחך\u0004 אתה צריך לומר ש\u0003כר' יוחנן סבירא ליה\u0004 \u0005[סבור הוא]\u0006 בענין זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מתנא לאביי, לריש לקיש\u0004 ש\u0003אמר: בפירוש ריבתה תורה חייבי מלקיות כחייבי מיתות,\u0004 שאף אם חטא בשוגג פטור מן התשלומים, \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא דפליג עליה\u0004 \u0005[שחולק עליו]\u0006 על \u0003ר' נחוניא בן הקנה\u0004 ומחייב תשלומים במקום חיוב כרת, והרי יש עם הכרת גם חיוב מלקות, שפוטר מממון? ומשיבים: \u0003אי\u0004 \u0005[או]\u0006 \u0003ר' מאיר\u0004 הסבור שלוקה ומשלם, \u0003אי\u0004 \u0005[או]\u0006 \u0003ר' יצחק\u0004 האומר שחייבי כריתות אינם לוקים.","ומעתה עוברים לדון בענין אחר הקשור באותה בעיה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 הבא על אחת מן \u0003עריות\u0004 או ה\u0003שניות לעריות\u0004 — \u0003אין להן\u0004 ממנו \u0003לא קנס\u0004 של אונס, \u0003ולא\u0004 קנס של \u0003פיתוי.\u0004 וכן \u0003הממאנת,\u0004 שהיא היתומה שהשיאוה אימה או אחיה ובטרם בגרה מיאנה בבעלה — \u0003אין לה לא קנס ולא פיתוי,\u0004 שכיון שנישאה כבר, אף שיצאה במיאון אינה עוד בחזקת בתולה. \u0003איילונית\u0004 היא זו שיש בה מום שאינה מגיעה להתבגרות, וכיון שאין לה סימני נערות אינה בגדר נערה, ו\u0003אין לה לא קנס ולא פיתוי, והיוצאת משום שם רע אין לה לא קנס ולא פיתוי.\u0004 ומבארים את דברי הברייתא הזו.","תחילה דנים בפירוש המושגים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"עריות\" ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"שניות לעריות\"? אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003\"עריות\"\u0004 הן"],["\u0003עריות ממש,\u0004 נשים האסורות מן התורה משום גילוי ערוה, ו\u0003\"שניות\"\u0004 הן כמשמען בכל מקום — אותן קרובות שהוסיפו חכמים לאסור \u0003מדברי סופרים\u0004 — אי אפשר לומר כן, לפי שאותן שניות \u0003כיון דמדאורייתא חזיא ליה\u0004 \u0005[שמן התורה\u0006 היא \u0005ראויה לו]\u0006 להינשא לאונס, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין להן קנס? אלא\u0004 יש לפרש שכוונת הדברים היא, בשינוי המשמעות הרגילה: \u0003\"עריות\",\u0004 הן עריות חמורות, \u0003חייבי מיתות בית דין, \"שניות\"\u0004 הן \u0003חייבי כריתות,\u0004 שהן שניות בחומרתן לחייבי מיתות בית דין, \u0003אבל חייבי לאוין — יש להן קנס, ו\u0004אם כן \u0003מני\u0004 \u0005[ו\u0006שיטת \u0005מי היא] —\u0006 שיטת \u0003שמעון התימני היא\u0004 שפוטר מקנס רק את האונס אשה שאין קדושין תופסים בה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאפשר לפרש ש\u0003\"עריות\"\u0004 הכוונה לעריות חמורות, והן כוללות \u0003חייבי מיתות בית דין וחייבי כריתות, שניות\u0004 הן השניות להן בחומרה והן — \u0003חייבי לאוין.\u0004 ולפי זה \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא] —\u0006 שיטת \u0003ר' שמעון בן מנסיא היא,\u0004 שאמר שאף האונס אשה שהיא מחייבי לאוין שקידושין תופסים בה — אין לה קנס.","שנינו בברייתא, ש\u0003הממאנת אין לה לא קנס ולא פיתוי\u0004 משום שהיתה כבר נשואה, ומן הסתם אינה עוד בתולה, ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003קטנה בעלמא\u0004 \u0005[סתם] —\u0006 \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה\u0004 קנס. ואם כן \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 ברייתא זו — כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא דאמרי\u0004 \u0005[שאומרים\u0006 בכלל\u0005]:\u0006 \u0003קטנה יש לה קנס,\u0004 אולם \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של ברייתא זו: \u0003איילונית אין לה לא קנס ולא פיתוי\u0004 לפי שאינה מביאה סימני בגרות (שתי שערות) ונחשבת קטנה עד שנתה העשרים, ומאותו זמן ואילך נחשבת כבוגרת. ואם כן \u0003אתא\u0004 \u0005[בא,\u0006 הגיע\u0005]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר,\u0004 ש\u0003אמר: קטנה אין לה קנס, והא\u0004 \u0005[וזו]\u0006 האיילונית \u0003מקטנותה יצתה\u0004 (יצאה) \u0003לבגר\u0004 (בגרות), כשמגיעה לגיל עשרים, ואין לה כלל זמן של נערות. ולכן אין לאיילונית קנס לפי שאין קנס אלא בנערה בלבד. וזו שיטת ר' מאיר. נמצא איפוא שברייתא זו \u0003רישא רבנן\u0004 \u0005[ראשה\u0006 כשיטת \u0005חכמים]\u0006 \u0003וסיפא\u0004 \u0005[וסופה]\u0006 כשיטת \u0003ר' מאיר!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי הברייתא \u0003כולה\u0004 כשיטת \u0003ר' מאיר היא ו\u0004אולם \u0003בממאנת סבר לה\u0004 \u0005[סבור]\u0006 ר' מאיר \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 שלא רק קטנה אלא גם נערה רשאית למאן, ומדובר גם בנערה, ואין ללמוד על קטנה כלום. אולם \u0003ומי סבר לה\u0004 \u0005[והאם סבור\u0006 הוא \u0005כן]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עד מתי הבת ממאנת — עד שתביא שתי שערות,\u0004 כלומר, עד תחילת זמן נערותה, אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 יכולה עוד למאן \u0003עד שירבה\u0004 במקום ערווה שיער \u0003שחור על הלבן\u0004 שהוא כחצי שנה לאחר מכן, עד שמגיעה לבגרות.","\u0003אלא,\u0004 יש להסביר להיפך: שהברייתא הזו כשיטת \u0003ר' יהודה היא, ו\u0004אולם \u0003בקטנה סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 שקטנה אין לה קנס, ולכן אין קנס באיילונית. ומקשים: \u0003ומי סבר לה\u0004 \u0005[והאם סבור\u0006 הוא \u0005כך]\u0006? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר רב\u0004 על המשנה להלן (כתובות מ, ב) שנאמר בה שבזמן שיש זכות מכר לאב (כשהבת היא קטנה) אין לה קנס. ואמר רב: \u0003זו דברי ר' מאיר. ואם איתא\u0004 \u0005[יש]\u0006 מקום לסברה שגם ר' יהודה סבור כן, אם כן \u0003זו דברי ר' מאיר ור' יהודה מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 אלא יש לומר כי כאן יש שיטה שלישית, וכי \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 של הברייתא \u0003סבר לה\u0004 \u0005[סבור]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר בחדא\u0004 \u0005[ב\u0006הלכה \u0005אחת],\u0006 בענין שאין קנס לקטנה, \u0003ופליג עליה בחדא\u0004 \u0005[וחלק עליו באחת]\u0006 בענין עד מתי ממאנת, ובזו סבר כר' יהודה שגם בנערותה ממאנת.","\u0003רפרם אמר\u0004 הסבר אחר: ברייתא זו כולה כדעת ר' מאיר, ו\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ממאנת\"\u0004 האמור כאן — אותה \u0003הראויה למאן,\u0004 כלומר, כל שהיא עדיין קטנה. ולשיטת ר' מאיר אין קנס בקטנה. ומקשים: לשם מה לו לשנות בברייתא בלשון מסובכת זו? \u0003וליתני\u0004 \u0005[ושישנה]\u0006 במפורש \u0003\"קטנה\"!\u0004 ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","שנינו בברייתא שה\u0003איילונית אין לה לא קנס ולא פיתוי. ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא אחרת: \u0003החרשת והשוטה והאיילונית — יש להן קנס, ויש להן טענת בתולים.\u0004 שאם נישאה בחזקת בתולה, יכול הבעל לטעון כנגדה שלא מצא לה בתולים ולהפסיד את כתובתה. קושיה זו דוחים: \u0003והא, מאי רומיא\u0004 \u0005[וזו, מה סתירה\u0006 היא\u0005]?\u0006 הלא אפשר להסביר בפשטות \u0003הא\u0004 \u0005[זו],\u0006 הברייתא הראשונה, היא כדעת \u0003ר' מאיר,\u0004 ואילו \u0003הא\u0004 \u0005[זו],\u0006 הברייתא השניה — כדעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 המחייבים קנס בקטנה, וגם איילונית בכלל זה! ותוהים: כיון שהתירוץ פשוט כל כך, \u0003ודקארי לה, מאי קארי לה\u0004 \u0005[ו\u0006זה \u0005שהקשה אותה, מה הקשה אותה],\u0006 מה ראה מקום לקושיה זו, הלא ידוע שיש מחלוקת בדבר!","ומשיבים: \u0003משום דאית ליה למירמא אחריתי עילויה\u0004 \u0005[שיש לו להשליך,\u0006 להראות סתירה, \u0005אחרת עליה],\u0006 וקושיה זו היא רק כעין הקדמה לה, שכן שנינו בברייתא שלישית: \u0003החרשת והשוטה והבוגרת ומוכת עץ — אין להן טענת בתולים,\u0004 שאינן עוד בחזקת בתולות. אולם \u0003הסומא\u0004 (עוורת) \u0003ואיילונית — יש להן טענת בתולים. סומכוס אומר משום ר' מאיר: סומא — אין לה טענת בתולים.\u0004 ועל כל פנים יש כאן סתירה בין הברייתות לענין טענת בתולים בחרשת ושוטה.","\u0003אמר רב ששת: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 \u0003הא\u0004 \u0005[זו],\u0006 כשיטת \u0003רבן גמליאל\u0004 האומר שמאמינים לאשה הטוענת שלאחר האירוסין נאנסה. ואף חרשת ושוטה, למרות שהן עצמן אינן טוענות זאת — טוענים אנו עבורן. לכן אינו יכול לבוא בטענת בתולים, שמא נאנסו אחרי האירוסין. \u0003והא\u0004 \u0005[וזו]\u0006 שיטת \u0003ר' יהושע,\u0004 שאומר שאין מאמינים לה בטענה זו. על הסבר זה מקשים: \u0003אימר דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את \u0003רבן גמליאל\u0004 שסומך על דבריה \u0003היכא דקא טענה איהי\u0004 \u0005[היכן שטוענת היא]\u0006 במפורש שנאנסה אחר האירוסין, ואולם \u0003היכא דלא קא טענה איהי, מי שמעת ליה\u0004 \u0005[היכן שאין היא טוענת, האם שמעת אותו]\u0006 שיש לתלות באונס כזה ולטעון בשבילה? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003כיון\u0004 ש\u0003אמר רבן גמליאל\u0004 שבטענה כגון זו \u0003מהימנא\u0004 \u0005[נאמנת],\u0006 הרי באשה \u0003כגון זו,\u0004 כשהיא חרשת או שוטה, בכלל דברי הכתוב \u0003\"פתח פיך לאלם\"\u0004 (משלי לא, ח) \u0003הוא,\u0004 וצריך לטעון עבורה, כיון שאין לה דעת לטעון כך בעצמה.","שנינו באותה ברייתא ש\u0003הבוגרת אין לה טענת בתולים,\u0004 כלומר, שאנחנו מניחים שבתוליה כלו מאליהם בזמן בגרותה. ומקשים, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: בוגרת\u0004 שנבעלה, \u0003נותנין לה לילה הראשון,\u0004 שמניחים שכל דם שיוצא ממנה בלילה הראשון דם בתולים הוא ולא דם נדה. ואם כן מוכח מכאן שאף בוגרת יש לה בתולים!"],["\u0003אי דקא טעין\u0004 \u0005[אם ש\u0006הוא \u0005טוען\u0006 עליה\u0005]\u0006 \u0003טענת דמים,\u0004 שבעל ולא מצא דם — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 הוא הדין שאף בבוגרת אם היא בתולה יש לה דמים. \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003דקטעין\u0004 \u0005[ש\u0006הוא \u0005טוען]\u0006 \u0003טענת פתח פתוח,\u0004 ובוגרת פתחה פתוח.","שנינו בברייתא: \u0003סומכוס אומר משום ר' מאיר: סומא\u0004 (עיוורת) \u0003אין לה טענת בתולים.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003סומכוס? אמר ר' זירא: מפני ש\u0004העיוורת פעמים רבות \u0003נחבטת\u0004 (נופלת ומקבלת מכה) \u0003על גבי קרקע\u0004 ושמא נשרו בתוליה על ידי כך. ותוהים: \u0003כולהו נמי חבוטי מיחבטי\u0004 \u0005[\u0006כל הבנות \u0005כולן גם כן\u0006 עלולות \u0005להיחבט\u0006 על הקרקע\u0005]\u0006 ואם כן מה המיוחד לגבי עיוורת? ומשיבים: \u0003כולהו\u0004 \u0005[כולן]\u0006 \u0003רואות\u0004 שזב מהן דם לאחר החבטה \u0003ומראות לאמן,\u0004 והאם בודקת ויודעת שהבת שוב אינה בתולה, ואילו \u0003זו,\u0004 העיוורת \u0003אינה רואה\u0004 בזוב דמה \u0003ו\u0004ממילא \u0003אינה מראה לאמה\u0004 ולכן ייתכן שאירע לה דבר ואין איש יודע, וכשנשאה ודאי העלה על דעתו שמא אינה בתולה, ואינו יכול לטעון טענת בתולים.","שנינו שם: \u0003והיוצאת משום שם רע אין לה לא קנס ולא פיתוי.\u0004 והבינו תחילה שהכוונה היא שיוצאת מבעלה משום שזינתה. ותוהים: \u0003היוצאת משום שם רע\u0004 הלא בעצם \u0003בת סקילה היא\u0004 (ראויה להיסקל) שהלא זינתה תחת בעלה, ופשוט שאין לה קנס! \u0003אמר רב ששת: הכי קאמר\u0004 \u0005[כך אמר],\u0006 זו היא הכוונה: \u0003מי שיצא עליה שם רע בילדותה\u0004 שזינתה — \u0003אין לה לא קנס ולא פיתוי,\u0004 כי אנו מניחים שהיא כבר בעולה.","\u0003אמר רב פפא: שמע מינה\u0004 \u0005[למד מכאן],\u0006 מהלכה זו, לענין אחר: \u0003האי שטרא ריעא\u0004 \u0005[שטר זה\u0006 שנעשה \u0005רעוע],\u0006 שנתעורר חשש לגבי אמיתותו, \u0003לא מגבינן ביה\u0004 \u0005[אין אנו גובים בו].\u0006 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא דנפק קלא עליה דשטרא דזייפא\u0004 \u0005[אם תאמר שיצא קול עליו ששטר מזויף]\u0006 \u0003הוא, דכוותה הכא\u0004 \u0005[\u0006ו\u0005כיוצא בזה כאן]\u0006 במקרה שלנו, של שם רע, \u0003דנפק עלה קלא דזנאי\u0004 \u0005[שיצא עליה קול שזינתה],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבא:\u0004 אשה ש\u0003יצא לה שם מזנה בעיר — אין חוששין לה,\u0004 ומניחים שאין ממש בקול זה. ואם כן מדין זה אפשר ללמוד שאין ממש בקול בלא עדות ממשית.","\u0003אלא\u0004 כך צריך לומר: \u0003דאתו בי תרי ואמרי\u0004 \u0005[שבאו שניים ואמרו,\u0006 העידו\u0005]:\u0006 \u0003לדידהו תבעתנהי באיסורא\u0004 \u0005[אותנו תבעה\u0006 לתשמיש \u0005באיסור],\u0006 ואם כן, \u0003דכוותה הכא\u0004 \u0005[כיוצא בזה כאן,\u0006 בענין שטר\u0005]\u0006 \u0003דאתו בי תרי ואמרי\u0004 \u0005[שבאו שניים ואמרו]:\u0006 \u0003לדידהו אמר להו\u0004 \u0005[לנו אמר]:\u0006 \u0003\"זייפו לי\u0004 שטר\". ותוהים: \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 בענין זנות — \u0003שכיחי\u0004 \u0005[מצויים]\u0006 \u0003פרוצין\u0004 ואם שניים אלה נתבעו ולא נענו לה, יש להניח שהיא תבעה אחר והוא בעל אותה. \u0003אלא הכא\u0004 \u0005[כאן]\u0006 בענין זיוף \u0003אם הוא הוחזק\u0004 כמחזר אחר זיוף \u0003כל ישראל מי\u0004 \u0005[האם]\u0006 \u0003הוחזקו\u0004 כזייפנים? ואם כן מדוע נחשוד שמישהו זייף לו את השטר? ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כיון דקא מהדר אזיופא\u0004 \u0005[\u0006ש\u0005הוא מחזר,\u0006 מחפש, \u0005אחר הזיוף],\u0006 \u0003אימר\u0004 \u0005[אמור]\u0006 מתוך שלא נענה, לבסוף הוא עצמו \u0003זיופי זייף\u0004 \u0005[זייף]\u0006 \u0003וכתב,\u0004 וגם אם אין לחשוד באחרים — בו עצמו יש מקום לחשוד ויש איפוא דמיון בין שטר רעוע למי שיצא עליה שם רע.","\u0003ואלו\u0004 הן נערות \u0003שאין להן קנס: הבא על הגיורת,\u0004 או \u0003על השבויה,\u0004 או \u0003על השפחה, שנפדו,\u0004 או \u0003שנתגיירו,\u0004 או \u0003שנשתחררו\u0004 כשהיו \u0003יתירות על בנות שלש שנים ויום אחד,\u0004 שיש להניח שאינן בתולות, ואין קנס אלא לבתולות. \u0003ר' יהודה אומר: שבויה שנפדית הרי היא בקדושתה אף על פי ש\u0004היא \u0003גדולה,\u0004 שאין לומר שבודאי נבעלה.","ועוד נערות שאין להן קנס: \u0003הבא על בתו,\u0004 או \u0003על בת בתו,\u0004 או \u0003על בת בנו,\u0004 או \u0003על בת אשתו,\u0004 או \u0003על בת בנה,\u0004 או \u0003על בת בתה\u0004 — כל אלה \u0003אין להן קנס, מפני שמתחייב בנפשו\u0004 על עבירה זו, \u0003שמיתתן בידי בית דין, וכל המתחייב בנפשו — אין משלם ממון. שנאמר: \"ו(אם) לא יהיה אסון ענוש יענש\"\u0004 (שמות כא, כב), ומכאן למדים שאם היה אסון, והמכה חייב מיתה, אינו נענש בממון.","\u0003אמר ר' יוחנן: ר' יהודה ור' דוסא אמרו דבר אחד,\u0004 כלומר, יש להם שיטה אחת בענין היתר שבויה. \u0003ר' יהודה — הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 במשנה. \u0003ר' דוסא — דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003שבויה\u0004 בת כהן, או אשת כהן שנפדית משביה — \u0003אוכלת בתרומה,\u0004 אלו \u0003דברי ר' דוסא.\u0004 וכהסבר \u0003אמר ר' דוסא: וכי מה עשה לה ערבי הלז\u0004 (הזה) שהיה השובה שלה? \u0003וכי מפני שמיעך לה בין דדיה\u0004 בדרך פריצות, \u0003פסלה\u0004 משום כך \u0003מן הכהונה?\u0004 שלגבי שבויה אין חשש לבעילה ממש, והחשש המצוי הוא לפריצות בלבד.","\u0003אמר רבה: דלמא\u0004 \u0005[שמא]\u0006 \u0003לא היא\u0004 ואין כאן שיטה אחת, כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יהודה הכא\u0004 \u0005[כאן]\u0006 לענין קנס \u0003אלא\u0004 מפני הטעם \u0003שלא יהא חוטא נשכר,\u0004 וכי מפני שנשבתה אותה ילדה ייפטר האונס אותה מן הקנס? \u0003אבל התם\u0004 \u0005[שם,\u0006 לענין תרומה\u0005] —\u0006 \u0003כרבנן סבירא ליה\u0004 \u0005[כ\u0006דעת \u0005חכמים סבור הוא\u0006 ר' יהודה\u0005]\u0006 ותהיה אסורה לכהונה. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לחלק באופן אחר: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' דוסא התם\u0004 \u0005[שם]\u0006 \u0003אלא ב\u0004אכילת \u0003תרומה\u0004 בזמן הזה שהיא \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003אבל\u0004 בענין \u0003קנס\u0004 שהוא חיוב \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003כרבנן סבירא ליה\u0004 \u0005[כ\u0006דעת \u0005חכמים הוא סבור]\u0006 שאין לחייב אותו בחיוב ממון מן התורה אלא כשיש ודאות בדבר, וכאן יש חשש שהיא בעולה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבה: \u0003וטעמיה\u0004 \u0005[ו\u0006כי \u0005טעמו]\u0006 של \u0003ר' יהודה הכא\u0004 \u0005[כאן]\u0006 בקנס \u0003שלא יהא חוטא נשכר הוא? והא תניא\u0004 \u0005[והרי\u0006 \u0005שנינו בברייתא\u0006\u0005],\u0006 \u0003ר' יהודה אומר: שבויה שנשבית הרי היא בקדושתה\u0004 ובחזקת בתולה, ו\u0003אפילו\u0004 היתה \u0003בת עשר שנים — כתובתה מאתים.\u0004 וכיון שמדובר בכתובה, \u0003והתם מאי\u0004 \u0005[ושם מה\u0006 נימוק\u0005]\u0006 \u0003שלא יהא חוטא נשכר איכא\u0004 \u0005[יש],\u0006 הלא אין כאן חטא? ומשיבים: \u0003התם נמי דלמא מימנעי\u0004 \u0005[שם גם כן\u0006 הטעם הוא \u0005שמא יימנעו]\u0006 \u0003ולא נסבי לה\u0004 \u0005[ישאו אותה]\u0006 מפני החשש שהיא בעולה, ולכן אמר שמחזיקים אותה כבתולה ונותנים לה כתובה מאתיים זוז, ולא יהא לה קושי להינשא.","ושואלים: \u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003ר' יהודה\u0004 ששבויה \u0003בקדושתה קיימה\u0004 \u0005[עומדת]\u0006 היא? \u0003והתניא\u0004 \u0005[והרי\u0006 \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003הפודה את השבויה — ישאנה.\u0004 מותר לו לשאתה אפילו אם הוא כהן. אבל אם הוא עצמו \u0003מעיד בה\u0004 שלא נבעלה — \u0003לא ישאנה. ר' יהודה אומר: בין כך ובין כך לא ישאנה,\u0004 שמא נבעלה ונפסלה לכהונה! ומעירים: \u0003הא גופה קשיא\u0004 \u0005[היא\u0006 הברייתא \u0005עצמה קשה],\u0006 \u0003אמרת\u0004 מצד אחד: \u0003הפודה את השבויה ישאנה, והדר תנא\u0004 \u0005[וחזר ושנה]\u0006 \u0003מעיד בה לא ישאנה.\u0004 וכי \u0003משום ש\u0004גם \u0003מעיד בה לא ישאנה?!\u0004","ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זו אינה קשה],\u0006 כי ודאי \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את הדברים: \u0003הפודה את השבויה ומעיד בה\u0004 שהיא טהורה — \u0003ישאנה, מעיד בה כדי\u0004 \u0005[סתם]\u0006 שפדאה משביה — \u0003לא ישאנה.\u0004","ולענייננו, \u0003מכל מקום קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005]\u0006 \u0003לר' יהודה,\u0004 שהרי מברייתא זו נראה שהוא מניח שסתם שבויה בחזקת בעולה היא! \u0003אמר רב פפא: אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 את הגרסה כך: \u0003ר' יהודה אומר: בין כך ובין כך ישאנה. רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אומר: לעולם כדקתני\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 בלא תיקון, אלא \u0003ר' יהודה לדבריהם דרבנן\u0004 \u0005[של חכמים]\u0006 \u0003קאמר להו\u0004 \u0005[אומר להם],\u0006 וכך יש להבין את דבריו: \u0003לדידי\u0004 \u0005[לשיטתי]\u0006 שאני מניח שהשבויה היא טהורה — \u0003בין כך ובין כך ישאנה, אלא לדידכו\u0004 \u0005[לשיטתכם]\u0006 שאתם חוששים לבעילה, אם כן \u0003בין כך ובין כך לא ישאנה מבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 להיות\u0005]!\u0006","ומסבירים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה טעמם — \u0003הפודה את השבויה ומעיד בה ישאנה\u0004 כי \u0003לא שדי איניש זוזי בכדי\u0004 \u0005[אין אדם זורק כסף לחינם],\u0006 ואם הוציא עליה כספים ודאי בטוח הוא שלא נבעלה. אבל \u0003מעיד בה כדי\u0004 \u0005[סתם]\u0006 \u0003לא ישאנה — שמא עיניו נתן בה\u0004 שרוצה לשאתה לאשה, ומעיד שקר.","\u0003רמי ליה\u0004 \u0005[השליך לו,\u0006 הראה לו סתירה\u0005]\u0006 \u0003רב פפא בר שמואל לרב יוסף:\u0004"],["\u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003ר' יהודה\u0004 ששבויה \u0003בקדושתה קיימא\u0004 \u0005[עומדת]?\u0006 \u0003והתניא\u0004 \u0005[והרי\u0006 \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003הגיורת שנתגיירה וראתה דם\u0004 נדה בו ביום, \u0003ר' יהודה אומר: דיה שעתה.\u0004 ואין גוזרים שתטמא דברים שנגעה בהם גם למפרע, מחשש שמא יצא הדם קודם לכן, אלא רק מאותה שעה שראתה היא מטמאה. \u0003ר' יוסי אומר: הרי היא ככל הנשים\u0004 בישראל, \u0003ומטמאה מעת לעת\u0004 (עשרים וארבע שעות) למפרע מאז שנתגיירה, או \u0003מפקידה לפקידה,\u0004 מבדיקה אחת לבדיקה אחרת, כלומר, מזמן הבדיקה האחרונה.","\u0003ו\u0004עוד אמר בגיורת: \u0003צריכה להמתין\u0004 מאז שנתגיירה \u0003שלשה חדשים\u0004 עד שתינשא לישראל, שאנו חוששים שמא היא מעוברת, ויתערב זרעה זה שלא היה בקדושת ישראל בזה שיוולד בקדושת ישראל, אלו \u0003דברי ר' יהודה. ר' יוסי מתיר ליארס ולינשא מיד.\u0004 משמע שלגבי גיורת חושש ר' יהודה שנבעלה קודם! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: מ\u0003גיורת\u0004 על \u0003שבויה קא רמית\u0004 \u0005[אתה משליך,\u0006 מקשה\u0005]?\u0006 \u0003גיורת\u0004 לפני שמתגיירת \u0003לא מנטרא נפשה\u0004 \u0005[אינה שומרת\u0006 את \u0005עצמה\u0006 מלהיבעל\u0005],\u0006 \u0003שבויה מנטרא נפשה\u0004 \u0005[שומרת\u0006 את \u0005עצמה]\u0006 בגלל מודעותה לקדושת ישראל ואינה רוצה להיטמא.","\u0003ו\u0004מצד אחר \u0003רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 מדין \u0003שבויה\u0004 על דין \u0003שבויה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003הגיורת והשבויה והשפחה שנפדו\u0004 או \u0003שנתגיירו\u0004 או \u0003שנשתחררו\u0004 כשהן \u0003יתירות על בנות שלש שנים ויום אחד\u0004 — \u0003צריכות להמתין שלשה חדשים\u0004 עד שתנשאנה, אלו \u0003דברי ר' יהודה, ר' יוסי מתיר ליארס ולינשא מיד.\u0004 ועל כל פנים נראה מכאן שר' יהודה חושש גם בשבויות שמא נבעלו, בניגוד לדברים שאמרנו כאן! \u0003אשתיק\u0004 \u0005[שתק]\u0006 רב יוסף ולא מצא תשובה.","אחר כך \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מידי שמיע לך בהא\u0004 \u0005[האם שמעת דבר\u0006 מה \u0005ב\u0006ענין \u0005זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב ששת\u0004 בפירוש הלכה זו, שדברי ר' יהודה אלה הם בשבויה \u0003שראוה שנבעלה.\u0004 ושואלים: \u0003אי הכי מאי טעמא\u0004 \u0005[אם כך, מה הטעם]\u0006 של \u0003ר' יוסי\u0004 המתיר לה להינשא מיד? הלא יש חשש שהיא מעוברת! \u0003אמר רבה, קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יוסי: אשה מזנה משמשת במוך,\u0004 שמניחה מוך בצוואר הרחם כדי \u0003שלא תתעבר.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003גיורת, כיון\u0004 ש\u0003דעתה לאיגיורי\u0004 \u0005[להתגייר]\u0006 הריהי \u0003מנטרא נפשה\u0004 \u0005[שומרת\u0006 את \u0005עצמה]\u0006 ונוקטת באמצעים לא להתעבר, \u0003שבויה נמי\u0004 \u0005[גם כן]\u0006 שומרת את עצמה מלהתעבר, כיון \u0003דלא ידעה היכא ממטו לה\u0004 \u0005[שאינה יודעת להיכן מביאים אותה]\u0006 ולכן אינה רוצה להיות מעוברת. \u0003שפחה נמי\u0004 \u0005[גם כן]\u0006 אפשר לומר שהיא משמשת במוך, כיון \u0003דשמעה\u0004 \u0005[ששומעת]\u0006 \u0003מפי מרה\u0004 \u0005[אדוניה]\u0006 שהוא עומד לשחררה, ולכן היא רוצה שבניה שיוולדו לאחר מכן יהיו כשרים בלא ספק. \u0003אלא\u0004 שפחה שנשתחררה מפני ש\u0003יוצאה בשן ועין,\u0004 שחבל בה אדוניה ופצע אותה ובגלל כך יצאה לחירות, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי במקרה כזה אינה יודעת שתשתחרר, ומן הסתם אינה שומרת את עצמה, והרי פה מדובר שראוה שנבעלה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003כל\u0004 דבר שנעשה \u0003ממילא\u0004 \u0005[מעצמו]\u0006 שלא מדעת האשה כמו ביוצאת בשן ועין \u0003לא אמר ר' יוסי\u0004 שמותרת להנשא מיד, ובמקרה זה מודה לר' יהודה, \u0003הרי אנוסה ומפותה,\u0004 שהדבר בא \u0003ממילא\u0004 \u0005[מעצמו],\u0006 כלומר, בלא שהיא מוכנה לכך, \u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003אנוסה ומפותה צריכות להמתין שלשה חדשים\u0004 עד שתנשאנה, אלו \u0003דברי ר' יהודה. ר' יוסי מתיר\u0004 להן \u0003ליארס ולינשא מיד!\u0004","\u0003אלא אמר רבה:\u0004 טעמו של ר' יוסי אינו משום שאשה משמשת במוך שמכניסה לפני תשמיש, אלא \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יוסי: אשה מזנה מתהפכת\u0004 לאחר הבעילה \u0003כדי שלא תתעבר.\u0004 ולכן גם אם נבעלה שלא ברצונה — עושה מעשה שלא תתעבר. ושואלים: ואם כך הוא, \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יהודה\u0005]\u0006 מה טעמו? ומשיבים: \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא לא נהפכה יפה יפה\u0004 ונשאר הזרע במעיה וממנו התעברה.","נאמר במשנה שראיה לדבר שהמתחייב בנפשו איננו משלם, ממה \u0003שנאמר: \"ולא יהיה אסון ענוש יענש\" וכו'\u0004 (שמות כא, כב) ושואלים: \u0003והא, מהכא נפקא\u0004 \u0005[ו\u0006דבר \u0005זה, מכאן\u0006 הוא \u0005יוצא]?\u0006 הלא \u0003מהתם נפקא\u0004 \u0005[משם,\u0006 ממקור אחר, הוא \u0005יוצא],\u0006 שנאמר: \u0003\"\u0004והכהו לפניו \u0003כדי רשעתו\"\u0004 (דברים כה, ב), ודיוק הלשון \"רשעתו\" בא ללמד כי \u0003משום רשעה אחת אתה מחייבו,\u0004 כלומר, שאדם מתחייב רק בעונש אחד על מה שעבר בפעם אחת גם אם היו במעשה זה שני עונשים, \u0003ואי\u0004 \u0005[ואין]\u0006 \u0003אתה מחייבו משום שתי רשעיות!\u0004","ומשיבים: \u0003חדא\u0004 \u0005[אחת]\u0006 מן הדרשות נאמרה \u0003במיתה וממון,\u0004 שחיוב מיתה מפקיעו מלשלם ממון, והוא הפסוק \"ולא יהיה אסון\", \u0003וחדא\u0004 \u0005[ואחת]\u0006 הדרשות, מהפסוק \"כדי רשעתו\" — \u0003במלקות וממון,\u0004 ומסבירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שתיאמרנה שתיהן: \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 ב\u0003מיתה וממון\u0004 בלבד, היינו אומרים ששם הוא פטור מלשלם \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 \u0003איבוד נשמה,\u0004 שהוא עונש חמור מאד ודיו בעונש זה, \u0003אבל מלקות וממון, דליכא\u0004 \u0005[שאין]\u0006 במלקות \u0003איבוד נשמה,\u0004 ואינו עונש כה חמור \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יפטר ויצטרך ללקות וגם לשלם.","ולהיפך: \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק שב\u0003מלקות וממון\u0004 לוקה ואינו משלם, הייינו אומרים: \u0003משום\u0004 שהעבירה שחייבים עליה מלקות \u0003דלא חמיר איסוריה\u0004 \u0005[שאין איסורו חמור]\u0006 כל כך, שהרי אינו נידון אלא במלקות, ולכן אין מענישים אותו בשני עונשים, \u0003אבל מיתה וממון דחמיר איסוריה\u0004 \u0005[שאיסורו חמור],\u0006 שהרי חייב עליו מיתה, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יפטר וייענש כפליים, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמר הדבר במפורש שבשני המקרים אינו משלם.","ושואלים: \u0003ולר' מאיר\u0004 ש\u0003אמר\u0004 בכלל שכל העושה דבר שבעטיו הוא מתחייב מלקות וממון הריהו \u0003לוקה ומשלם,\u0004 אם כן \u0003תרתי\u0004 \u0005[שתי\u0006 ראיות\u0005]\u0006 \u0003למה לי?\u0004 שהרי לדעתו שני הכתובים באים ללמד שאין אדם מת ומשלם! ומשיבים: \u0003חדא\u0004 \u0005[אחת]\u0006 מהן נאמרה \u0003במיתה וממון,\u0004 שמי שחייב מיתה אינו משלם ממון,"],["\u0003וחדא\u0004 \u0005[ואחת]\u0006 מהדרשות מדברת \u0003במיתה ומלקות,\u0004 שמי שחייב מיתה אין מלקים אותו. ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שני כתובים: \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק בענין \u0003מיתה וממון,\u0004 היינו אומרים: \u0003משום דחדא בגופיה וחדא בממוניה לא עבדינן\u0004 \u0005[ש\u0006עונש \u0005אחד בגופו ואחד בממונו אין אנו עושים]\u0006 להעניש שני עונשים נבדלים, \u0003אבל במיתה ומלקות דאידי ואידי בגופיה\u0004 \u0005[שזה וזה בגופו],\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מיתה אריכתא\u0004 \u0005[ארוכה]\u0006 \u0003היא, ונעביד ביה\u0004 \u0005[ונעשה בו]\u0006 את שניהם, שקודם ילקו אותו ומיד אחר כך ימיתוהו, ותהא זו כאילו מיתה מיסורים.","ולהיפך: \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק לענין \u0003מיתה ומלקות,\u0004 היינו אומרים \u0003דתרתי בגופיה לא עבדינן\u0004 \u0005[ששני\u0006 עונשים \u0005בגופו אין אנו עושים],\u0006 \u0003אבל מיתה וממון דחדא בגופיה וחדא בממוניה\u0004 \u0005[שאחד בגופו ואחד בממונו]\u0006 אין זה קשה כל כך, ואם כן \u0003אימא נעביד ביה\u0004 \u0005[אמור\u0006 ש\u0005נעשה בו],\u0006 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הכתובים, שמהם נלמד כי רק עונש אחד נעשה בו.","ושואלים: הפסוק \u0003\"ולא תקחו כפר לנפש רצח\u0004 אשר הוא רשע למות\u0003\"\u0004 (במדבר לה, לא) שאפשר להבינו במשמעות שאין לקחת עונש כספי מאדם שנידון למוות, \u0003למה לי\u0004 אם הדבר נלמד ממקור אחר? ומסבירים: \u0003דאמר רחמנא\u0004 \u0005[שאמרה התורה]:\u0006 \u0003לא תשקול ממונא מיניה ותפטריה מקטלא\u0004 \u0005[אל תקח כסף ממנו\u0006 כעונש \u0005ותפטור אותו ממיתה].\u0006 וכן מה שנאמר שם \u0003\"\u0004ו\u0003לא תקחו כפר לנוס אל עיר מקלטו\"\u0004 (במדבר לה, לב), \u0003למה לי? דאמר רחמנא\u0004 \u0005[שאמרה התורה]:\u0006 \u0003לא תשקול ממונא מיניה ותפטריה\u0004 \u0005[אל תקח ממון ממנו ותפטור אותו]\u0006 \u0003מן\u0004 ה\u0003גלות.\u0004","ושואלים: \u0003ותרי קראי\u0004 \u0005[ושני כתובים]\u0006 \u0003למה לי,\u0004 הרי התוכן אחד הוא בשניהם! ומסבירים: \u0003חד\u0004 \u0005[אחד]\u0006 מהם הרי מדבר במי שרצח \u0003בשוגג, וחד\u0004 \u0005[ואחד]\u0006 מדבר ברוצח \u0003במזיד. וצריכי\u0004 \u0005[וצריכים]\u0006 שני הפסוקים להיכתב, \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק ב\u0003מזיד\u0004 שאינו נפטר בעונש ממון, היינו אומרים \u0003משום דחמיר איסוריה\u0004 \u0005[שחמור איסורו]\u0006 שעבר עבירה חמורה, \u0003אבל שוגג דלא חמיר איסוריה אימא\u0004 \u0005[שאין איסורו חמור\u0006 כל כך \u0005אמור]\u0006 ש\u0003לא,\u0004 ואולי יפטר בממון. ולהיפך: \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק ב\u0003שוגג\u0004 היינו אומרים \u0003משום דליכא\u0004 \u0005[שאין]\u0006 בו \u0003איבוד נשמה,\u0004 שהרי הוא רק גולה, והיינו סבורים שאין לפטור אותו מן הגלות שהרי אין זה עונש כבד כל כך, \u0003אבל מזיד דאיכא\u0004 \u0005[שיש]\u0006 בכך \u0003איבוד נשמה\u0004 של הרוצח — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 ושמא יוכל להציל עצמו על ידי כופר של ממון ולא יהיה איבוד נשמה, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שניהם.","ושואלים: אם כן, מה שנאמר שם עוד \u0003\"ולארץ לא יכפר לדם אשר שפך בה כי אם בדם שפכו\"\u0004 (במדבר לה, לג) שמובן ממנו שאינו נפטר בממון, \u0003למה לי?\u0004","ומסבירים: \u0003מבעי ליה\u0004 \u0005[צריך אותו]\u0006 \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]\u0006 לענין אחר: \u0003מנין שאם נתערפה עגלה\u0004 ערופה, שכאשר מוצאים הרוג ואין יודע מי הרגו, זקני העיר הקרובה למקום המצאו של החלל עורפים עגלה בנחל ומתפללים שעוון הרצח הזה יכופר, \u0003ו\u0004אם \u0003אחר כך,\u0004 אחר עריפת העגלה \u0003נמצא ההורג, מנין שאין פוטרין אותו,\u0004 ואין אומרים שכבר נתכפר לו על ידי עריפת העגלה — \u0003שנאמר: \"ולארץ לא יכפר לדם אשר שפך בה\u0004 כי אם בדם שופכו\u0003\"\u0004, ללמדנו: ולא בדם אחר, של העגלה.","ושואלים: והכתוב בסוף פרשת עגלה ערופה \u0003\"ואתה תבער הדם הנקי מקרבך\"\u0004 (דברים כא, ט), \u0003למה לי?\u0004 שהרי לכאורה אומר הכתוב אותו דבר עצמו, שצריך להמית את הרוצח! ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך לו]\u0006 כתוב זה, \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מנין למומתים ב\u0004מיתת \u0003סייף,\u0004 שהוא עונשם של הרוצחים, \u0003שהוא מן הצואר\u0004 ולא באופן אחר — \u0003תלמוד לומר: \"ואתה תבער הדם הנקי מקרבך\"\u0004 — \u0003הוקשו\u0004 (הושוו) \u0003כל שופכי דמים לעגלה ערופה\u0004 הבאה על שפיכות דמים, \u0003מה להלן\u0004 בעגלה ערופה עריפתה \u0003מן הצואר — אף שופכי דמים\u0004 עונשם הוא בהסרת הראש \u0003מן הצואר.\u0004","ושואלים: \u0003אי\u0004 \u0005[או]\u0006 \u0003מה להלן\u0004 בעגלה ערופה עושים זאת \u0003בקופיץ\u0004 (סכין גדולה) \u0003וממול עורף\u0004 (מתחת לראש מאחוריו) — \u0003אף כאן\u0004 בחייבי מיתות בית דין שמא נעשה זאת \u0003בקופיץ וממול עורף? אמר רב נחמן אמר רבה בר אבוה: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואהבת לרעך כמוך\"\u0004 (ויקרא יט, יח), ומכאן למדים בין השאר: \u0003ברור\u0004 (בחר) \u0003לו מיתה יפה,\u0004 שלא יתנוול במיתתו, והמיתה בקופיץ היא מיתה מגונה, ולכן דיו שממיתים אותו בהתזת הראש מן הצואר, אבל לא בכל הפרטים כבעגלה ערופה.","ושואלים עוד: מהכתוב \u0003\"כל חרם אשר יחרם מן האדם לא יפדה\"\u0004 (ויקרא כז, כט), שמבינים אותו במשמעות שמי שנגזר עליו דין מוות (\"חרם\") אין לו פדיון בכסף — \u0003למה לי?\u0004 ומסבירים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך אותו לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מנין ל\u0004אדם שהיה \u0003יוצא ליהרג, ואמר אחד \"ערכו עלי\",\u0004 כלומר, אני נודב למקדש את ערכו של זה היוצא להיהרג, \u0003מנין שלא אמר כלום,\u0004 שאין ממש בנדר זה —","\u0003שנאמר: \"כל חרם אשר יחרם מן האדם לא יפדה\",\u0004 שהנדר הזה (\"חרם\") שמעריכים אדם היוצא למות (\"יחרם מן האדם\") — אין לו ערך, משום שאדם זה שיוצא למות נחשב כבר כמת, שאין לו ערך. \u0003יכול אף קודם שנגמר דינו\u0004 שהיה נאשם בעבירה שעונשה מיתה, יהא דינו \u0003כן\u0004 שאם אמר אדם \"ערכו של הנידון עלי\" שמא לא אמר כלום? — \u0003תלמוד לומר: \"מן האדם\"\u0004 — למעט: \u0003ולא כל האדם,\u0004 שכל זמן שלא נגמר דינו למיתה נחשב הוא לאדם שלם שיש לו ערך.","ושואלים: \u0003ול\u0004דעת \u0003ר' חנניא בן עקביא,\u0004 ש\u0003אמר\u0004 כי גם זה שיוצא ליהרג \u0003נערך,\u0004 כלומר, אם נודרים את ערכו חייבים לשלמו, ומדוע — \u0003מפני שדמיו קצובין.\u0004 כי הערך האמור בתורה אינו תלוי בשוויו של הנערך, אלא קבוע לפי מספר שנותיו, ולכן כל עוד לא מת — יש לו ערך, אם כן חוזרת הקושיה למקומה: \u0003האי\u0004 \u0005[\u0006הפסוק \u0005הזה]\u0006 \u0003\"כל חרם\" מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו]?\u0006","ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך\u0006 הוא \u0005לו לכפי ששנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: לפי שמצינו למומתים בידי שמים,\u0004 כלומר, למי שחייב מיתה בידי שמים, \u0003שנותנין ממון ומתכפר להן, שנאמר:\u0004 \"השור יסקל וגם בעליו יומת. \u0003אם כפר יושת עליו\u0004 ונתן פדיון נפשו ככל אשר יושת עליו\" (שמות כא, כט-ל), שמי ששורו הרג אדם חייב בעצם מיתה בידי שמים, אלא שיכול להתכפר בממון. \u0003יכול אף\u0004 המומתים \u0003בידי אדם כן\u0004 יכולים לתת כופר נפשם ולהיפטר? \u0003תלמוד לומר: \"חרם מן האדם לא יפדה\"\u0004 כלומר, שאם מצות החרם (עונש המוות) היא \"מן האדם\" שהוא חייב מיתה בידי אדם, אין הוא נפדה על ידי כסף.","\u0003ואין לי אלא מיתות חמורות\u0004 כגון מכה אביו וכיוצא בהן \u0003שלא ניתנה שגגתן לכפרה,\u0004 שלא נתפרש בכתוב מה כפרתו של העושה אותן בשוגג, אבל \u0003מיתות קלות\u0004 כגון חילול שבת \u0003שניתנה שגגתן לכפרה,\u0004 שנתפרש שאם עושה אותן בשגגה מביא קרבן חטאת, \u0003מנין\u0004 שגם להן אין כפרה בממון — \u0003תלמוד לומר: \"כל חרם\"\u0004 המרבה גם שאר מיתות.","ושואלים: \u0003ולא ממילא\u0004 (והאם לא מעצם הדבר) \u0003מ\u0004מה שנאמר ברציחה \u0003\"\u0004ו\u0003לא תקחו כפר\u0004 לנפש רוצח\u0003\"\u0004 (במדבר לה, לא) \u0003שמעת מינה\u0004 \u0005[שומע אתה ממנה]\u0006 \u0003לא תשקול ממונא מיניה ותיפטריה\u0004 \u0005[אל תקח ממון ממנו ותפטרנו]\u0006 ואם כן ריבוי הפסוק \u0003\"כל חרם\" למה לי?\u0004 הלא כבר אנחנו יודעים זאת מפסוק אחר! \u0003אמר רמי בר חמא: איצטריך\u0004 \u0005[צריך]\u0006 שייכתב הדבר שנית, ומדוע — \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006"]]};
